window.CHAMPA_NORTH = {"version":"0.3.1","date":"2026-11-04","articles":{"BDS-0022":{"id":"BDS-0022","title":"Mỹ Đức — Một cơ sở Phật giáo bên hệ sông Kiến Giang","lead":"Mỹ Đức được nhận biết qua nền tháp, các tác phẩm điêu khắc và một mảnh minh văn. Di tích cho thấy việc nghiên cứu Phật giáo Bắc Champa phải đi cùng lịch sử phát hiện và sự phân tán hiện vật, bởi phần kiến trúc tại chỗ không còn đủ để tự kể lại toàn bộ lịch sử của nó.","province_source":"Quảng Bình","address_source":"Sơn Thủy - Lệ Thủy","source_page":"62","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng BDS-0022 ghi Sơn Thủy, Lệ Thủy, Quảng Bình. Nguyễn Văn Quảng đặt di tích tại thôn Mỹ Đức, trên gò cao trong vùng bán sơn địa, gần sông Cẩm Ly thuộc hệ Kiến Giang. Đó là địa chỉ theo nguồn trước sắp xếp hành chính, chưa phải xác nhận địa chỉ hoặc lối vào hiện nay. [1, tr.52–53]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án dẫn các cuộc đào của Henri de Pirey năm 1921–1922, nhưng thừa nhận thông tin chủ yếu được bảo tồn trong những tường thuật công bố sau đó. Vì vậy, lịch sử khai quật có khoảng trống: không nên xem bản sơ đồ dẫn lại là hồ sơ địa tầng hoàn chỉnh. Niên đại cuối thế kỷ IX–đầu X là nhận định tổng hợp của tác giả từ minh văn và điêu khắc. [1, tr.53–54] Catalogue Parmentier 1919 đã ghi hai tượng nam thần tìm trong đợt đào sơ bộ của de Pirey năm 1918, nghĩa là việc thu thập hiện vật bắt đầu trước các đợt 1921–1922. [13, mục 14,1–14,2] Theo Finot và Goloubew, đợt đào 1921–1922 cho thấy mặt bằng gần giống Đại Hữu: ba tháp mặt trước, điện nhỏ phía Nam, tường bao; hiện vật gồm hai tượng Avalokiteśvara, một tượng nữ, một Maitreya nhỏ và nhiều tượng Phật kim loại. [17, tr.474]"},{"title":"Kiến trúc và cảnh quan","text":"Theo khảo tả được luận án tổng hợp, khu thờ gồm ba tháp chính cùng các kiến trúc phụ, trong đó có công trình ba cửa được đặt câu hỏi là tháp cổng. Khảo sát sau này gặp gạch rải trên gò và dấu tường từng được ghi nhận năm 2005. Chúng hỗ trợ nhận diện một quần thể, nhưng chưa cho phép dựng chắc hành trình nghi lễ hoặc số pha xây dựng. [1, tr.53–54]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Các tượng Bồ tát và mảnh văn khắc là căn cứ quan trọng để nhận diện tính chất Phật giáo. Việc có Garuḍa trong sưu tập không tự bác bỏ nhận diện ấy: một mô típ hình tượng có thể xuất hiện trong nhiều ngữ cảnh. Quan hệ Mỹ Đức–Đại Hữu nên được xét qua từng hiện vật và bối cảnh phát hiện, thay vì đồng nhất cả hai cơ sở. [1, tr.53–54]"},{"title":"Văn khắc liên quan","text":"Luận án ghi một mảnh minh văn có các từ được diễn giải liên quan đến Phật giáo. Corpus của dự án ghi C.172 là mảnh văn khắc Sanskrit, Golzio xếp thế kỷ IX; catalogue 2012 ghi mảnh này đã thất lạc. [14, C.172] Finot và Goloubew năm 1925 cho biết mảnh nhỏ khoảng 8 × 18 cm này được tìm trong một hàng rào gần đó, có hai dòng, đọc được các danh hiệu Phật ‘jagadguru’ và ‘abhayada’. Vì không tìm tại chỗ, mảnh chưa định tuổi được tháp nào. [17, tr.474] Chưa có căn cứ ở đây để gán cho Mỹ Đức một ngày lập tự chính xác. [1, tr.53–54]"},{"title":"Hiện vật và nơi lưu giữ","text":"Các tường thuật trong luận án phân biệt những tác phẩm từng về Guimet, Bảo tàng Điêu khắc Chăm Đà Nẵng, Bảo tàng Lịch sử Quốc gia và sưu tập khác. Tên hiện vật và nơi giữ phản ánh lịch sử ghi nhận, chưa thay thế số kiểm kê và xác nhận hiện hành. Khi nối bản đồ, phải giữ Mỹ Đức là nơi xuất xứ được báo cáo, bảo tàng là nơi lưu giữ; không nhập hai vai trò thành một điểm. [1, tr.53] Tượng Parmentier 14,1 khớp số BTC 189 trong danh mục bảo tàng; BTC 188 cùng tên là phiên bản. [13, mục 14,1; 15]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên bảo tồn là xác định vùng còn dấu kiến trúc dưới mặt đất, kiểm lại các đoạn tường đã được báo cáo và lập hồ sơ gạch tái sử dụng trong khu dân cư. Đây là đề xuất biên soạn từ tình trạng nguồn ghi, chưa phải kết quả kiểm tra hiện trường năm 2026. Chưa nên đưa một ứng viên tọa độ thành điểm dẫn đường."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần truy hồi nhật ký và ảnh đào của de Pirey, khóa số kiểm kê các tượng và kiểm lại mảnh C.172. Một câu hỏi có sức phân biệt là các hiện vật có thực sự thuộc cùng pha sử dụng hay đã được tập hợp qua nhiều đợt. Chỉ sau bước đó mới có thể so sánh tổ chức thờ tự Mỹ Đức với Đại Hữu và Đồng Dương ở cấp thiết chế."}],"thesis_locator":"52–54","reference_numbers":[1,13,14,15,17],"related_ids":["BDS-0023","BDS-0024"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0022","name":"Mỹ Đức","identity_note":"Mỹ Đức: đầu mối C.172 chưa mở được ấn bản trong lượt này.","word_count":790,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":14,"title":"Corpus văn khắc Champa của dự án, bản 3.2: danh mục 179 dòng mã C (tổng hợp Golzio 2004, kiểm kê EFEO/DHARMA chép trong corpus cũ, Griffiths và cộng sự 2012).","url":"","scope":"Đọc các dòng C.111, C.112, C.113, C.148, C.149, C.150, C.171, C.172, C.181, C.234, C.252, C.260, C.265: nơi phát hiện, nơi lưu giữ theo nguồn, niên đại từng nguồn, vật mang chữ, ngôn ngữ. Nơi lưu giữ là ghi chép kiểm kê cũ, chưa phải tình trạng năm 2026. Chưa đọc lại toàn văn ấn bản của từng mã.","access":"du_lieu_du_an"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày.","access":"du_lieu_du_an"},{"number":17,"title":"Louis Finot và Victor Goloubew (1925). Fouilles de Đại-hữu (Quảng-bình, Annam). BEFEO 25, tr.469–475, pl. LIII–LVI. DOI: 10.3406/befeo.1925.3065.","url":"https://www.persee.fr/doc/befeo_0336-1519_1925_num_25_1_3065","scope":"Đọc trọn lớp chữ Persée tr.469–474 (phần Đại Hữu và đoạn so sánh Mỹ Đức). Chưa xem các bản ảnh pl. LIII–LVI và sơ đồ fig. 19 ở độ phân giải đủ đo. Tác giả tự ghi đây là công bố trước khi khai quật xong, dựa trên báo cáo vắn tắt của de Pirey; báo cáo gộp hai đợt 10/1922 và 10/1925.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Một cơ sở Phật giáo bên hệ sông Kiến Giang","primary_crosscheck":[{"source":13,"locator":"mục 14,1–14,2","data":"Hai tượng nam thần đứng, ‘Cồn Giàng de Mỹ-đức, canton de Ngô-xá, phủ de Quảng-ninh, Quảng-bình’; 14,1 ‘trouvée au cours des fouilles sommaires exécutées par le P. H. de Pirey pour le compte de l’École en 1918’ (BEFEO XVIII, x, tr.61); 14,2 cùng lịch sử. Parmentier thấy hình Phật nhỏ trước búi tóc và nêu khả năng Avalokiteśvara nhưng không kết luận.","relation":"bo_sung","note":"Có một đợt đào sơ bộ năm 1918, sớm hơn các đợt 1921–1922 bài đang nêu."},{"source":14,"locator":"C.172","data":"Mảnh văn khắc Sanskrit (kiểm kê: fragment d’inscription), Golzio 2004 xếp thế kỷ IX; catalogue 2012 (tr.20 bản Việt, tr.184 bản Anh) ghi đã thất lạc; số cũ 1,7.","relation":"bo_sung","note":"Giải quyết một phần đầu mối C.172; toàn văn ấn bản vẫn chưa đọc."},{"source":17,"locator":"tr.474","data":"C.172 là một mảnh nhỏ khoảng 8 × 18 cm tìm trong một hàng rào gần đó, có hai dòng rời. Finot đọc được ‘jagadguru’ (thầy của thế gian) và ‘abhayada’ (đấng ban sự vô úy), xác định là văn khắc Sanskrit Phật giáo, chữ viết giống hệt vòi bồn tắm Đại Hữu.","relation":"bo_sung","note":"Mảnh không tìm tại chỗ trong đền, nên quan hệ với từng tháp Mỹ Đức còn để mở. Sự giống chữ viết là nhận định của Finot."},{"source":17,"locator":"tr.474, chú thích","data":"Finot đính chính: tượng Lokeśvara đá cao 0,45 m ở Bảo tàng Hà Nội (I.11896) mà BEFEO XXIII, tr.536 ghi xuất xứ Đại Hữu thực ra tìm ở làng Thu Thừ, cách Mỹ Đức 8 km về phía bắc.","relation":"khac_biet","note":"Cần chặn việc gán tượng này cho Đại Hữu hoặc Mỹ Đức trong danh mục hiện vật."}],"inventory_links":[{"BTC":"189","P":"14.1","status":"confirmed","basis":"BTC ghi P 14.1 (tên trong danh mục: Bồ tát Avalokiteśvara); Parmentier 14,1 ghi Mỹ Đức. BTC 188 cùng tên là phiên bản, không phải hiện vật gốc.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 18","verified_against_original":"2026-11-04"}],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,13,14,15,17],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [13], [17]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[{"phase":"1","date":"1918","actor":"H. de Pirey, đào sơ bộ cho EFEO","area":"Không mô tả","architecture":"Không mô tả","finds":"Hai tượng nam thần (Parmentier 14,1–14,2; 14,1 = BTC 189)","measurements":"14,1: 1,28 m kể cả chân đế 0,13 m","locator":"[13, mục 14,1–14,2]"},{"phase":"2","date":"1921–1922","actor":"H. de Pirey","area":"Khu đền (BEFEO XXII, tr.372 trở đi — chưa đọc)","architecture":"Mặt bằng gần giống Đại Hữu: ba tháp xếp hàng mặt trước, một điện nhỏ phía Nam, tường bao","finds":"Hai tượng Avalokiteśvara, một tượng nữ giống tượng Đại Hữu, một Maitreya nhỏ, nhiều tượng Phật kim loại. C.172 tìm trong một hàng rào gần đó","measurements":"Mảnh C.172 khoảng 8 × 18 cm, hai dòng","locator":"[17, tr.474]"}],"source_location":{"description":"Phủ Quảng Bình, tỉnh Quảng Bình theo cách ghi năm 1925.","coordinates_as_printed":"Lg. 115 G 95, Lt. 19 G 17","conversion_test":"≈ 17,253° B; 106,692° Đ, nếu giả định đơn vị grad và kinh tuyến gốc Paris. Phép đổi thử, chưa kiểm; không dùng làm tọa độ bản đồ.","source":"[17, tr.474]"}},"BDS-0023":{"id":"BDS-0023","title":"Đại Hữu — Kiến trúc và dấu tích thờ Ratnalokeśvara","lead":"Đại Hữu là một đầu mối nổi bật của Phật giáo Champa ở Quảng Bình. Giá trị của di tích nằm ở sự gặp nhau giữa bố cục ba tháp, những hố đặt vật thiêng và mảnh văn khắc còn tên Ratnalokeśvara; mỗi lớp chứng cứ cần được đọc đúng giới hạn.","province_source":"Quảng Bình","address_source":"An Ninh - Quảng Ninh","source_page":"62","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0023 ghi Đại Hữu tại An Ninh, Quảng Ninh, Quảng Bình. Luận án mô tả gò di tích trong địa hình bán sơn địa, có núi Thần Đinh về phía tây và sông Long Đại ở phía bắc. Các khoảng cách là ghi nhận của nguồn, không phải phép đo GIS mới. Chưa dùng tên vùng cổ trong minh văn làm tên hành chính thay thế. [1, tr.50]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Henri de Pirey đào ở Đại Hữu bốn lần: tháng 1/1918, tháng 10/1922, tháng 10/1925 và tháng 6/1926. [17, tr.469–470; 18, tr.359] Nguyễn Văn Quảng đối chiếu các công bố của Finot–Goloubew và Aurousseau, đồng thời chỉ ra số đo mặt bằng giữa các báo cáo chưa hoàn toàn khớp. Mốc cuối thế kỷ IX–đầu X là một nhận định niên đại tổng hợp; các ngày đào không phải ngày xây. [1, tr.50–52]"},{"title":"Kiến trúc và cảnh quan","text":"Bố cục được dẫn lại gồm ba tháp chính song song, mở cửa về phía đông, bao quanh bởi tường và các công trình phụ. Tại tháp nam và tháp bắc, báo cáo đào ghi những lớp cát, cuội cùng đồ đặt nền bằng vàng, đá quý và đồ đựng nhỏ; ở tháp giữa, đợt đào năm 1926 xuống khoảng 4,5 m không tìm thấy hố vật thiêng; đây là kết quả trong phạm vi đã đào. [18, tr.361–362] Không nên lấy sự giống nhau của hai hố làm bằng chứng tự đủ rằng mọi công trình đồng thời. [1, tr.50–51] Báo cáo 1925 ghi tường bao 26 × 24 m, dày 0,60 m, khi mặt Tây chưa dọn; năm 1926 tường phía Tây lộ ra bằng đá lớn, dày 1,80 m. Bệ tháp Bắc mà năm 1925 tưởng quay vào tường Nam thực ra đã bị một hố đào cũ làm xê dịch. Đợt 1926 bổ sung và giải thích một số khác biệt, như hướng bệ tháp Bắc; nguyên nhân chênh lệch số đo tường bao chưa được giải quyết. [17, tr.469–470; 18, tr.359–361]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tượng Phật, các dạng Lokeśvara và tác phẩm được định danh Prajñāpāramitā đặt Đại Hữu vào lịch sử Phật giáo Champa. Hố vật thiêng cho biết có một thực hành thiết lập kiến trúc được báo cáo; bản thân các vật đặt nền không cho phép phục nguyên đầy đủ nghi quỹ hoặc tự kết luận một dòng Mật giáo cụ thể. [1, tr.51–52] Finot và Goloubew năm 1925 không nhận ba tượng nữ thần là Prajñāpāramitā và đề nghị một dạng nữ của Lokeśvara; hồ sơ ghi cả hai cách định danh, chưa phân xử. [17, tr.473–474]"},{"title":"Văn khắc liên quan","text":"C.171 là mảnh bệ có văn khắc nhiều chỗ khuyết. Bản DHARMA hiện đọc được tên Ratnalokeśvara, từ chỉ chất liệu bạc và tên Jayasiṅhavarmmadeva. Trang ấn bản chưa có bản dịch hoàn chỉnh; vì thế bài này không gán toàn bộ việc hiến cúng cho một chủ thể duy nhất hoặc khôi phục trọn sự kiện từ các mảnh câu. [9, A3–B3] Kiểm kê cũ chép trong corpus ghi C.171 là mảnh bồn tắm tượng, lưu ở Bảo tàng Lịch sử Hà Nội; điều này chưa phải xác nhận hiện hành. [14, C.171] Ấn bản đầu của Finot đặt văn khắc vào thời Jayasiṃhavarman I, khoảng năm 900 CN, và đọc tên nơi dựng là Vṛddha-Ratnapura; báo cáo không ghi C.171 được tìm ở tháp nào. [17, tr.472–473]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi một số tác phẩm có xuất xứ Đại Hữu được lưu tại các bảo tàng ở Thành phố Hồ Chí Minh và Hà Nội, đồng thời nêu trường hợp hiện vật từng ở Đà Nẵng nhưng đã thất lạc. Danh mục này cần đối chiếu hồ sơ nhập kho hiện hành. Một pho tượng mang tên Đại Hữu tại bảo tàng không còn là bằng chứng về vị trí nguyên thủy của nó trong từng tháp. [1, tr.52] Catalogue 1919 cho một liên kết vật thể chắc: tượng nữ thần 14,3 được tìm nguyên cùng bệ 22,1 trên nền một công trình năm 1918; bệ hiện mang số BTC 187. [13, mục 14,3; 22,1; 15]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Khảo sát được luận án công bố mô tả gạch vỡ, việc lấy gạch dùng lại và thay đổi dấu nền giữa năm 2005 với đợt khảo sát sau. Bảo tồn cần chú ý cả phần nền và cảnh quan quanh gò; chỉ bảo vệ một hiện vật nổi không đủ giữ quan hệ kiến trúc. Chưa có khảo sát mới trong bộ bài này để xác nhận mức mất mát hiện nay. [1, tr.51–52]"},{"title":"Những vấn đề đang nghiên cứu","text":"Hai báo cáo khai quật đã được đặt cạnh nhau trong bảng các đợt và tên tháp đã xác định. Ưu tiên tiếp theo là đối chiếu sơ đồ fig. 19 (1925) và fig. 1 (1926) để biết hai số đo tường bao thuộc đoạn nào, trước khi dùng số liệu cho nghiên cứu mô đun. [17, tr.469–470; 18, tr.359] Cần xét riêng mối liên hệ giữa C.171, các tượng và ba kiến trúc. Đại Hữu có thể giúp nghiên cứu mạng các cơ sở Phật giáo phía bắc, nhưng sự tương đồng chưa tự chứng minh một tuyến quản lý hay truyền thừa trực tiếp."}],"thesis_locator":"50–52","reference_numbers":[1,9,13,14,15,17,18],"related_ids":["BDS-0022","BDS-0024"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0023","name":"Đại Hữu","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":905,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":9,"title":"Arlo Griffiths và Dániel Balogh (biên tập). DHARMA, INSCIC00171: Đại Hữu pedestal fragment. Phiên bản hiển thị 19/09/2026.","url":"https://dharmalekha.info/texts/INSCIC00171","scope":"Đọc bản chuyển tự, tên Ratnalokeśvara, chỉ chất liệu bạc và Jayasiṅhavarmmadeva; văn bản nhiều chỗ khuyết và chưa có bản dịch hoàn chỉnh trên trang đã kiểm.","access":"cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":14,"title":"Corpus văn khắc Champa của dự án, bản 3.2: danh mục 179 dòng mã C (tổng hợp Golzio 2004, kiểm kê EFEO/DHARMA chép trong corpus cũ, Griffiths và cộng sự 2012).","url":"","scope":"Đọc các dòng C.111, C.112, C.113, C.148, C.149, C.150, C.171, C.172, C.181, C.234, C.252, C.260, C.265: nơi phát hiện, nơi lưu giữ theo nguồn, niên đại từng nguồn, vật mang chữ, ngôn ngữ. Nơi lưu giữ là ghi chép kiểm kê cũ, chưa phải tình trạng năm 2026. Chưa đọc lại toàn văn ấn bản của từng mã.","access":"du_lieu_du_an"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày.","access":"du_lieu_du_an"},{"number":17,"title":"Louis Finot và Victor Goloubew (1925). Fouilles de Đại-hữu (Quảng-bình, Annam). BEFEO 25, tr.469–475, pl. LIII–LVI. DOI: 10.3406/befeo.1925.3065.","url":"https://www.persee.fr/doc/befeo_0336-1519_1925_num_25_1_3065","scope":"Đọc trọn lớp chữ Persée tr.469–474 (phần Đại Hữu và đoạn so sánh Mỹ Đức). Chưa xem các bản ảnh pl. LIII–LVI và sơ đồ fig. 19 ở độ phân giải đủ đo. Tác giả tự ghi đây là công bố trước khi khai quật xong, dựa trên báo cáo vắn tắt của de Pirey; báo cáo gộp hai đợt 10/1922 và 10/1925.","access":"cong_khai"},{"number":18,"title":"L. Aurousseau (1926). Nouvelles fouilles de Đại-hữu (Quảng-bình, Annam). BEFEO 26, tr.359–362, pl. XIII–XXI. DOI: 10.3406/befeo.1926.3094.","url":"https://www.persee.fr/doc/befeo_0336-1519_1926_num_26_1_3094","scope":"Đọc trọn lớp chữ Persée tr.359–362: đợt đào tháng 6/1926 theo ghi chép của de Pirey. Chưa xem sơ đồ từng phần fig. 1 và các bản ảnh ở độ phân giải đủ đo.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Kiến trúc và dấu tích thờ Ratnalokeśvara","primary_crosscheck":[{"source":13,"locator":"mục 14,3; 22,1","data":"Tượng nữ thần đứng có mắt thứ ba và hình Phật nhỏ trên tóc (14,3), ‘Cồn Giàng de Đại-hữu, canton de Cổ-hiền, phủ de Quảng-ninh’; ‘trouvée complète avec son piédestal 22,1 sur l’emplacement d’un édifice čam’ trong đợt đào của de Pirey năm 1918; vào bảo tàng năm 1918. Bệ 22,1 có bồn rửa bốn vòi trong.","relation":"bo_sung","note":"Một cặp tượng–bệ tìm cùng nhau tại chỗ: liên kết vật thể chắc nhất trong các nguồn đã đọc cho Đại Hữu; chưa so sánh với toàn bộ chứng cứ di tích. Nhận định Prajñāpāramitā trong luận án cần đối chiếu lại đúng tác phẩm này."},{"source":14,"locator":"C.171","data":"Mảnh bồn tắm tượng (kiểm kê: fragment de cuve à ablution), Sanskrit, Golzio 2004 xếp thế kỷ IX; nơi lưu giữ theo kiểm kê cũ: Bảo tàng Lịch sử Hà Nội, số 21179.","relation":"bo_sung","note":"Vật mang chữ là bồn tắm tượng, khớp cách gọi ‘mảnh bệ’. Chưa có căn cứ nối C.171 với bệ 22,1."},{"source":9,"locator":"siêu dữ liệu và thư mục, đọc 04/11/2026","data":"DHARMA ghi ngôn ngữ Chăm cổ và Sanskrit; vật mang chữ là mảnh bệ có rãnh dẫn nước chia văn bản thành A và B; ấn bản đầu: Finot và Goloubew 1925, BEFEO 25, tr.469–475; dựa thác bản EFEO 507; chưa có bản dịch. Số BTLS Hà Nội LSb 21179 chỉ nằm trong chú thích mã nguồn của tệp.","relation":"khac_biet","note":"Corpus 3.2 ghi chỉ Sanskrit; DHARMA ghi Chăm cổ và Sanskrit. Ghi khác biệt theo phiên bản, chưa hòa giải. Ấn bản 1925 trùng nguồn khai quật Đại Hữu cần đọc tiếp."},{"source":18,"locator":"tr.359","data":"Tên tháp: A, B, C lần lượt là tháp Nam, tháp giữa và tháp Bắc. Phần phía Tây chưa được dọn trước đợt 1926.","relation":"bo_sung","note":"Như vậy tượng nữ thần và bệ năm 1918 thuộc tháp A, tức tháp Nam. Số đo tường bao năm 1925 được ghi khi mặt Tây chưa dọn, nên là số đo của một giai đoạn mở."},{"source":18,"locator":"tr.361","data":"Bệ tháp Bắc bị xê dịch bởi một hố đào cũ của người Việt (sâu khoảng 1,80 m) nên đang dựa tường Nam.","relation":"khac_biet","note":"Báo cáo 1925 ghi bệ tháp C quay vào tường Nam như một quan sát. Đợt 1926 cho thấy đó là vị trí sau xáo trộn, không phải hướng nguyên thủy. Đợt 1926 giải thích được khác biệt này; điều đó không mặc nhiên áp cho các khác biệt khác."},{"source":18,"locator":"tr.359–360; so với [17, tr.469–470]","data":"Tường bao phía Tây bằng đá lớn, dày 1,80 m. Báo cáo 1925 ghi tường bao dày 0,60 m.","relation":"khac_biet","note":"Nguyên nhân chênh lệch chưa được giải quyết: hai số đo có thể thuộc hai đoạn tường, hai loại vật liệu hoặc hai cách đo khác nhau. Không coi số nào sai và không lấy trung bình."},{"source":18,"locator":"tr.362","data":"Tháp giữa đào tới khoảng 4,50 m mà không tìm thấy hố vật thiêng.","relation":"bo_sung","note":"Đây là kết quả trong phạm vi đã đào, chưa chứng minh tháp giữa không có đồ đặt nền."},{"source":17,"locator":"tr.472–473","data":"C.171: khắc trên vòi bồn tắm tượng (snānadroṇī), văn vần śloka. Finot đọc: một thủ quỹ hoàng gia dựng tượng Ratna-Lokeśvara bằng bạc ở Vṛddha-Ratnapura; vua xác nhận là Jayasiṃhavarman I, khoảng năm 900 CN, suy từ mốc 820 Śaka ở bia Bàn Lành và so sánh chữ viết. ‘Hjai’ được Finot hiểu là ‘hajai’ (lãnh địa).","relation":"bo_sung","note":"Báo cáo không ghi vị trí tìm C.171, nên chưa gắn văn khắc với một tháp. ‘Hajai’ là từ Chăm; điều này có thể giải thích vì sao DHARMA ghi cả Chăm cổ và Sanskrit (suy luận, cần kiểm bản đọc DHARMA). Kết luận của Finot rằng ba kalan ‘không thể muộn hơn cuối thế kỷ IX’ là suy luận của tác giả, không phải dữ kiện."},{"source":17,"locator":"tr.473–474, chú thích 5","data":"Finot nhận xét ba tượng nữ thần (một ở Đà Nẵng, một ở pl. LIV-B, một tượng vỡ) giống nhau hoàn toàn. Ông cho rằng chúng không phải Prajñāpāramitā (vì tượng này không mang hình Phật trên búi tóc) và nghi ngờ Tārā (vì không có văn khắc Champa nào gọi tên). Ông đề nghị một dạng nữ của Lokeśvara hoặc một công chúa được tạc dưới dạng ấy.","relation":"can_kiem","note":"Đây là một lớp lịch sử học khác với định danh Prajñāpāramitā trong luận án. Hồ sơ ghi cả hai, chưa phân xử."},{"source":17,"locator":"tr.471–472","data":"Finot cho rằng Lokeśvara đồng mạ vàng có thể là tác phẩm Trung Hoa, muộn nhất thời Đường.","relation":"can_kiem","note":"Nhận định phong cách của tác giả, cần đối chiếu nghiên cứu sau."}],"inventory_links":[{"BTC":"187","P":"22.1","status":"confirmed","basis":"BTC ghi P 22.1; Parmentier 22,1 là bệ của tượng 14,3, Đại Hữu. Tượng 14,3 chưa thấy số BTC trong phòng đã đọc.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 17","verified_against_original":"2026-11-04"}],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,9,13,14,15,17,18],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [9], [13], [17], [18]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[{"phase":"1","date":"01/1918","actor":"H. de Pirey, tự bỏ kinh phí, được làng cho phép","area":"Đào vội phía sau miếu nhỏ, trong tháp A (tháp Nam theo [18])","architecture":"Không mô tả mặt bằng","finds":"Tượng nữ thần và bệ thờ, sau vào Bảo tàng Đà Nẵng (= Parmentier 14,3 và 22,1; bệ = BTC 187)","measurements":"Tượng 0,97 m (theo [13])","locator":"[17, tr.469–470]; [18, tr.359]; [13, mục 14,3; 22,1]"},{"phase":"2–3","date":"10/1922 và 10/1925 (báo cáo gộp)","actor":"H. de Pirey, theo ý kiến Parmentier; Finot–Goloubew công bố","area":"Gò kéo dài về phía bắc; phần phía tây chưa dọn (theo [18])","architecture":"Hai kalan nhỏ B và C rất đổ nát; M là điện nhỏ, N là dấu tích không rõ công năng; tường bao 26 m (B–N) × 24 m (Đ–T), dày 0,60 m; cổng lớn giữa mặt Đông. Bệ ở B áp tường Tây, đá bệ đổ dựa tường Bắc; bệ ở C quay vào tường Nam, còn tấm đá vuông mang hai bàn chân tượng vỡ (đã đưa về Đồng Hới)","finds":"Phật đồng đứng; Lokeśvara đồng không đầu (trước kalan giữa); đồ thờ đồng; Lokeśvara đồng mạ vàng (đoạn trên); tượng đá nữ thần (trong tháp C, Bắc); mảnh một tượng đá khác (đầu, hai cẳng tay, đoạn gậy, trước tháp giữa); C.171 trên vòi bồn tắm tượng, không ghi vị trí tìm. Theo [18], hai Lokeśvara đồng tìm tháng 10/1925","measurements":"Phật đồng 0,445 m; Lokeśvara đồng 0,335 m có đế; đồ thờ 0,082 m; Lokeśvara mạ vàng 0,122 m; tượng đá 0,65 m; mảnh vòi C.171 dài 0,29 m, rộng 0,37–0,17 m, cao 0,17 m","locator":"[17, tr.469–472]; [18, tr.359]"},{"phase":"4","date":"06/1926","actor":"H. de Pirey; Aurousseau công bố","area":"Dọn mặt Tây tường bao; mở nền tháp Bắc, tháp giữa, tháp Nam","architecture":"Phía Tây không có công trình nào ngoài tường bao, tường bằng đá lớn dày 1,80 m. Tháp Bắc có hố đào cũ của người Việt sâu khoảng 1,80 m, làm xê dịch bệ thờ nên bệ đang dựa tường Nam. Tháp Bắc: cuội ở khoảng 3,50 m, cát sông ở khoảng 4 m (dày khoảng 0,35 m) rồi tới hố vật thiêng. Tháp giữa: cuội 3,30 m, đá ong 4 m, đào thêm 0,50 m, không có kết quả. Tháp Nam: cuội khoảng 3,60 m, cát mịn khoảng 4 m, hố vật thiêng bố trí như tháp Bắc","finds":"Tháp Bắc: tay đồng cầm vajra, cẳng tay và bàn chân đồng của một tượng cao ít nhất 0,60 m (trong đất đào cũ); lá vàng hình rùa trên lớp cát; hố vật thiêng gồm 4 bình đất nung ở bốn góc, lá vàng hình sen, hũ vàng có nắp đựng đá quý trắng, khuyên vàng, 7 bình kim loại mỗi bình 2 (một bình 3) viên đá quý, các khối thạch anh. Tháp Nam: cùng bố trí, hũ vàng đựng đá quý tím, một khuyên tai vàng, 7 bình kim loại đựng đá đỏ hoặc trắng; không có rùa vàng. Không tìm lại được đầu hai Lokeśvara đồng","measurements":"Tay 0,093 m; cẳng tay 0,093 m; bàn chân 0,088 m (cao 0,122 m có mộng); rùa vàng 0,057 m; bình đất nung 11–12 cm; lá sen vàng 0,065 m; hũ vàng cao 0,037 m (Bắc) và 0,04 m (Nam); bình kim loại 0,035–0,048 m","locator":"[18, tr.359–362]"}],"source_location":{"description":"Giữa đường sắt và đường núi, cách bến đò Long Đại khoảng 1.800 m theo hướng Mỹ Đức; một lùm cây lớn có ngôi chùa từ thời Gia Long; làng cách nửa giờ đi bộ về phía Đông. Tổng Cổ Hiền, phủ Quảng Ninh.","coordinates_as_printed":"Lg. 115 G 87, Lt. 19 G 22 (dẫn BEFEO XVIII, x, 61)","conversion_test":"≈ 17,298° B; 106,620° Đ, nếu giả định đơn vị grad (1 grad = 0,9°) và kinh tuyến gốc Paris. Đây là phép đổi thử, chưa kiểm hệ quy chiếu; không dùng làm tọa độ bản đồ.","source":"[17, tr.469–470, chú thích 1]"}},"BDS-0024":{"id":"BDS-0024","title":"Vân Tập — Dấu kiến trúc trong cảnh quan bắc sông Gianh","lead":"Vân Tập hiện diện trong tư liệu chủ yếu qua một gò đất và những mảnh gạch. Chính sự mỏng của chứng cứ khiến nơi này cần một cách giới thiệu thận trọng: giữ dấu vết vật chất, lời kể địa phương và các giả thuyết về cảnh quan ở những lớp riêng.","province_source":"Quảng Bình","address_source":"Quảng Lưu - Quảng Trạch","source_page":"62","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng BDS-0024 ghi Quảng Lưu, Quảng Trạch, Quảng Bình; luận án xác định khu gò ở thôn Vân Tiền. Tên Vân Tập và Vân Tiền cần được ghi song song để người đọc truy nguyên, không tự coi là hai di tích. Tên đơn vị hành chính được giữ theo thời điểm nguồn. [1, tr.57]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Theo Nguyễn Văn Quảng, địa điểm chưa được nhận diện trong nhóm khảo tả Pháp mà tác giả sử dụng và cũng ít được quan tâm sau năm 1975. Đây là nhận xét về tư liệu đã khảo sát, không chứng minh rằng chưa từng có người biết đến di tích. Luận án chưa xác lập niên đại kiến trúc. [1, tr.57–58]"},{"title":"Kiến trúc và cảnh quan","text":"Khảo sát ghi gò cao hơn mặt ruộng xung quanh, dấu gạch phân bố trên phạm vi khoảng một nghìn mét vuông và một số mảnh tập trung ở gốc cây. Không có mặt bằng khai quật đủ để đếm tháp hoặc xác định hướng cửa. Phạm vi gạch trên bề mặt cũng không thể dùng ngay như diện tích nền công trình. [1, tr.57–58]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Chưa có một tượng thờ hay cấu trúc nghi lễ được khóa xuất xứ trong phần tư liệu đã đọc. Lời kể về phế đô Lâm Ấp là dữ liệu ký ức địa phương do luận án ghi lại; nó không tự xác nhận chức năng kinh đô hoặc tôn giáo của khu gò. [1, tr.58]"},{"title":"Văn khắc liên quan","text":"Bộ bài chưa có văn khắc nào được nối chắc với Vân Tập. Không chuyển bia ở cửa Ròn, một bia vùng Quảng Bình hoặc văn khắc Phong Nha sang di tích này chỉ vì gần về địa lý."},{"title":"Hiện vật và nơi lưu giữ","text":"Hiện vật được mô tả chủ yếu là gạch, với các đặc điểm chất liệu và kích thước trong bảng khảo sát của tác giả. Chúng có giá trị để thiết kế khảo sát, nhưng chưa đủ làm mẫu chuẩn niên đại hoặc kết luận kỹ thuật nung. Chưa có danh mục hiện vật bảo tàng đã khóa số kiểm kê cho Vân Tập. [1, tr.57–58]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Nên ưu tiên lập bình đồ vi địa hình, nhận diện các vùng gạch nằm nguyên vị và ghi sự tác động của canh tác. Luận án đặt Vân Tập trong tương quan với lũy cũ Hoàn Vương và mộ cổ lân cận; bảo tồn cần khảo sát cả khoảng không gian giữa chúng, chưa nên dựng tuyến tham quan theo một câu chuyện kinh đô đã định sẵn. [1, tr.58]"},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi chính là đây có phải một cơ sở thờ tự độc lập, một phần của cụm cư trú–thành lũy hay nhiều dấu tích khác thời. Phép kiểm thích hợp là khảo sát có lưới và thám sát được cấp phép, gắn địa tầng với mẫu định niên đại. Nếu chưa có những dữ liệu đó, nên giữ tên hồ sơ là ứng viên di tích, không mở rộng thành một trung tâm chính trị chắc chắn."}],"thesis_locator":"57–58","reference_numbers":[1],"related_ids":["BDS-0022","BDS-0023"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0024","name":"Vân Tập","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":545,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Dấu kiến trúc trong cảnh quan bắc sông Gianh","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0025":{"id":"BDS-0025","title":"An Xá — Nền tháp và tranh luận về kiến trúc phụ","lead":"An Xá là một trong những phế tích Bắc Champa có kết quả khai quật đáng chú ý. Cấu trúc móng và các khối bệ thờ cho phép đi xa hơn việc xác nhận có đền tháp, đồng thời cũng đặt ra tranh luận về chức năng công trình phụ và cách định niên đại.","province_source":"Quảng Trị","address_source":"Trung Sơn - Gio Linh","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0025 ghi An Xá tại Trung Sơn, Gio Linh, Quảng Trị. Luận án đặt địa điểm trên vùng gò đất đỏ bazan thuộc dải Cồn Tiên–Dốc Miếu, gần hệ sông Bến Hải. Địa chỉ này là thông tin nguồn, chưa được đổi sang tên xã hiện hành trong bộ bài. [1, tr.63] Lưu ý: ‘canton An Xá’ trong catalogue 1919 là tổng chứa làng Hà Trung, không chỉ di tích này. [13, mục 22,3]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Cuộc khai quật tháng 7/1994 do Trung tâm Văn hóa Việt Nam thuộc Đại học Quốc gia Hà Nội phối hợp Bảo tàng Quảng Trị thực hiện đã làm lộ các nền kiến trúc. Các cách định niên đại được luận án dẫn không thống nhất: có ý kiến xếp sớm, có ý kiến đặt trong thế kỷ IX; Nguyễn Văn Quảng nghiêng về giữa thế kỷ IX. Phải giữ tên người đưa ra từng nhận định. [1, tr.63–64]"},{"title":"Kiến trúc và cảnh quan","text":"Luận án dẫn nền tháp trung tâm có lòng vuông cạnh khoảng 4,3 m và cách gia cố móng bằng các lớp vật liệu. Công trình phía nam được người khai quật xem là nhà dài, trong khi tác giả luận án đề xuất tháp lửa dựa trên bình đồ và vị trí. Đây là hai cách đọc một dấu nền, chưa phải hai công trình đã được chứng minh tồn tại đồng thời. [1, tr.63–64]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Linga–yoni và hệ khối bệ thờ là căn cứ liên quan đến thực hành thờ Śiva. Chúng không tự cho biết mọi thần được thờ trong cả quần thể. Tên nhà dài, kho hoặc tháp lửa chỉ nên dùng kèm mức giả định khi chưa có tổ hợp kiến trúc và vật dụng chức năng đủ phân biệt. [1, tr.64]"},{"title":"Văn khắc liên quan","text":"Trong phần tư liệu đã kiểm, chưa có bản khắc riêng của An Xá được định danh và đọc làm mốc. Do đó, niên đại đang dựa đáng kể vào khảo cổ và đối sánh phong cách; không thể trình bày một năm xây dựng chính xác."},{"title":"Hiện vật và nơi lưu giữ","text":"Bảy khối đá thuộc bệ thờ, một phần bệ yoni và các bộ phận linga–yoni là những nhóm hiện vật được luận án nhấn mạnh. Phần lớn đã được báo cáo chuyển về Bảo tàng Quảng Trị. Các lỗ mộng liên kết có thể giúp nghiên cứu cấu tạo bệ; muốn phục dựng phải đo và kiểm mặt ghép từng khối, không chỉ xếp theo hoa văn giống nhau. [1, tr.64]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn cần gắn hồ sơ hiện vật đã di chuyển với bình đồ khai quật và vị trí những dấu nền còn lại. Các con số chiều cao tháp ước tính trong tài liệu không phải số đo công trình nguyên vẹn, nên không dùng trực tiếp cho phục dựng toàn chiều cao. Tình trạng hiện trường năm 2026 cần kiểm riêng."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần mở báo cáo khai quật 1994, xác định hệ tọa độ và cao độ từng nền, rồi thử hai phương án công năng công trình phía nam. Việc đối sánh hoa văn với Mỹ Sơn, Trà Liên hoặc Hóa Châu có giá trị tạo khoảng niên đại, nhưng chưa cho phép đồng nhất người xây, cơ quan bảo trợ hay một thiết kế chuẩn truyền đi nguyên vẹn."}],"thesis_locator":"63–64","reference_numbers":[1,13],"related_ids":["BDS-0030","BDS-0034","BDS-0037"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0025","name":"An Xá","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":594,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Nền tháp và tranh luận về kiến trúc phụ","primary_crosscheck":[{"source":13,"locator":"mục 22,3","data":"‘Canton de An-xá’ trong Parmentier 1919 là tổng hành chính chứa làng Hà Trung.","relation":"khac_biet","note":"Không dùng các hiện vật Hà Trung ghi ‘canton An Xá’ làm tư liệu cho di tích An Xá (Trung Sơn)."}],"inventory_links":[],"source_basis":{"level":"single_secondary_with_disambiguation","reference_numbers":[1,13],"note":"Nội dung chính dựa vào một nguồn thứ cấp; nguồn gốc chỉ dùng để loại nhầm địa danh, chưa bổ sung chứng cứ trực tiếp về di tích."},"excavation_phases":[]},"BDS-0026":{"id":"BDS-0026","title":"Duy Viên — Dấu thờ linga trong cảnh quan sông Sa Lung","lead":"Duy Viên là trường hợp phần kiến trúc đã suy giảm mạnh trong khi dấu vết hiện vật còn giữ một phần thông tin về tín ngưỡng. Hồ sơ cần đọc lịch sử phát hiện, những mất mát đã được báo cáo và sự không chắc của phép suy niên đại từ tượng sang tháp.","province_source":"Quảng Trị","address_source":"Vĩnh Lâm - Vĩnh Linh","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0026 ghi Vĩnh Lâm, Vĩnh Linh, Quảng Trị. Nguyễn Văn Quảng đặt khu gò tại làng Duy Viên, bên sông Sa Lung thuộc hệ Bến Hải. Đây là tên và không gian theo nguồn; chưa xác định lối tiếp cận hoặc ranh giới bảo vệ hiện hành. [1, tr.78]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Tác giả tổng hợp hồi ức về tường gạch từng còn cao và việc san phá những năm 1980, sau đó ghi phát hiện linga–yoni tháng 3/1986. Lời kể về trạng thái tường trước đây phải tách khỏi quan sát tại đợt khảo sát. Không coi các mô tả qua hồi ức là bản đo kiến trúc. [1, tr.78–79]"},{"title":"Kiến trúc và cảnh quan","text":"Khu gò được sử dụng cho canh tác và chôn cất trong thời điểm nguồn ghi, trên mặt còn gạch. Chưa có mặt bằng khai quật được dùng trong bài để xác định số tháp hoặc trục kiến trúc. Quan hệ với dòng Sa Lung là đầu mối khảo cổ cảnh quan, không tự xác nhận chức năng cảng hay đường thủy cổ. [1, tr.79]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Các ghi nhận về linga–yoni hỗ trợ nhận diện một lớp thờ Śiva. Dạng linga được so với Nhan Biều, Đông Hà và Vân Trạch Hòa; sự giống hình thái không chứng minh cùng xưởng hoặc cùng nghi lễ địa phương. [1, tr.79]"},{"title":"Văn khắc liên quan","text":"Chưa có minh văn được nối chắc với Duy Viên trong tập nguồn đã đọc. Mốc đầu thế kỷ X trong luận án là gợi ý từ đối sánh hiện vật, không phải năm lập đền được văn bản xác nhận. [1, tr.79]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án phân biệt tổ hợp được báo cáo tìm thấy năm 1986 nhưng về sau thất lạc với một linga nhỏ có xuất xứ Duy Viên được lưu tại Bảo tàng Quảng Trị. Cần tránh gộp hai nhóm thành cùng một hiện vật chỉ vì tên xuất xứ giống nhau. Số kiểm kê và lịch sử nhập kho vẫn là bước phải làm tiếp. [1, tr.78–79]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là nhận diện phạm vi gò còn lại và thu thập tư liệu ảnh, lời chứng có ngày cùng hồ sơ bảo tàng. Việc hiện vật đã mất làm tăng giá trị của chứng từ cũ, nhưng không cho phép dựng lại vị trí chính xác của bệ thờ bằng suy đoán."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần kiểm lại hiện vật mang tên Duy Viên và đối chiếu cấu tạo mặt gãy, thân linga với các bản ảnh. Niên đại phải đặt cho từng hiện vật trước khi hỏi về pha kiến trúc. Tương quan với An Xá và các điểm bên Bến Hải là giả thuyết khảo sát, chưa phải một mạng lưới đồng thời đã được xác lập."}],"thesis_locator":"78–79","reference_numbers":[1],"related_ids":["BDS-0025","BDS-0027","BDS-0028","BDS-0038"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0026","name":"Duy Viên","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":499,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Dấu thờ linga trong cảnh quan sông Sa Lung","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0027":{"id":"BDS-0027","title":"Huỳnh Xá — Phế tích ven Bến Hải và những biến đổi mặt đất","lead":"Huỳnh Xá được luận án nhận diện ở Cồn Gạch, trong một cảnh quan đã chuyển đổi mạnh. Đây là nơi cần ưu tiên lịch sử địa hình và dấu nền còn lại, bởi bản ghi gạch bề mặt chưa đủ để hình dung một ngôi tháp nguyên vẹn.","province_source":"Quảng Trị","address_source":"Vĩnh Sơn - Vĩnh Linh","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng sách ghi Huỳnh Xá, Vĩnh Sơn, Vĩnh Linh; luận án dùng địa danh làng Huỳnh Thượng và chú rõ tên cũ Huỳnh Xá. Hai tên được giữ cùng nhau để truy nguyên. Không tự đổi thành một điểm mới chỉ vì tên làng thay đổi. [1, tr.81]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Theo Nguyễn Văn Quảng, địa điểm không nằm trong các khảo tả Pháp mà tác giả dùng. Người dân kể việc san gò đã gặp đá, gạch và lá vàng; những lời kể này chưa thay cho nhật ký phát hiện hoặc hiện vật có xuất xứ được kiểm. Niên đại di tích còn để mở. [1, tr.81]"},{"title":"Kiến trúc và cảnh quan","text":"Nguồn mô tả khu di tích sát vùng ven sông Bến Hải và đã chuyển thành hồ nuôi tôm; trên bờ thửa còn gạch và cuội. Khi mặt đất bị hạ thấp hoặc đào sâu, phạm vi vật liệu nhìn thấy có thể lệch khỏi nền ban đầu. Vì vậy không thể xác định hướng tháp bằng hình hồ hiện nay. [1, tr.81]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Một am thờ thổ thần được ghi tại khu vực. Sự tồn tại của am là dữ liệu về lớp sử dụng về sau, chưa đủ xác định thần chủ của cơ sở Champa trước đó. Không dùng tên Cồn Gạch hoặc lời kể về lá vàng để suy một nghi quỹ cụ thể. [1, tr.81]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được định danh cho Huỳnh Xá trong phần nguồn đã kiểm. Chưa thể gắn di tích với một đời vua hoặc sự kiện lập tự."},{"title":"Hiện vật và nơi lưu giữ","text":"Gạch là nhóm vật liệu được tác giả đo và mô tả trực tiếp. Những vật đá và lá vàng trong lời kể cần lập hồ sơ riêng, ghi người cung cấp và thời điểm; chưa có số kiểm kê bảo tàng để nối chắc chúng với di tích. [1, tr.81]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Đề xuất bảo tồn là rà lịch sử đào hồ và lập bản đồ các bờ thửa còn vật liệu trước khi kiến nghị thám sát. Không thu gom gạch rải mà bỏ vị trí và cao độ, vì chính sự phân bố có thể giúp nhận ra phần di tích bị tác động."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi cần giải quyết là còn lớp nền nguyên vị ngoài phạm vi hồ hay chỉ còn vật liệu bị xáo trộn. Ảnh địa hình cũ, lời chứng có đối chiếu và khảo sát địa vật lý có thể giúp chọn vị trí kiểm, nhưng chưa có căn cứ để khẳng định quy mô, chức năng hoặc niên đại của tháp."}],"thesis_locator":"81","reference_numbers":[1],"related_ids":["BDS-0025","BDS-0026","BDS-0028"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0027","name":"Huỳnh Xá","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":470,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Phế tích ven Bến Hải và những biến đổi mặt đất","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0028":{"id":"BDS-0028","title":"Nam Sơn — Một tên di tích cần được khóa lại trên thực địa","lead":"Nam Sơn cần được giữ trong danh mục Bắc Champa, nhưng lượng chứng cứ hiện có chưa cho phép viết một lịch sử kiến trúc chi tiết. Hồ sơ giới thiệu phải cho người đọc thấy địa điểm được nhắc ở đâu và những điều chưa được xác lập, thay vì lấp chỗ trống bằng mô tả của một phế tích lân cận.","province_source":"Quảng Trị","address_source":"Vĩnh Sơn - Vĩnh Linh","source_page":"63","review_status":"editorial_draft_identity_unresolved","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0028 ghi Nam Sơn tại Vĩnh Sơn, Vĩnh Linh, Quảng Trị. Bài của Nguyễn Văn Mạnh năm 2015 cũng liệt kê tên này trong nhóm phế tích ở Vĩnh Sơn. Đây là căn cứ để tiếp tục truy tìm, chưa khóa được một vị trí riêng. [12, đoạn thống kê đền tháp]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Chưa nối được Nam Sơn với một mục trong bảng Quảng Trị của luận án 2018. Kết quả ấy chỉ có nghĩa là phép nối trong phần bảng đã kiểm chưa hoàn tất. Nó không phủ nhận di tích và cũng chưa chứng minh Nam Sơn là tên khác của Huỳnh Xá. [1, bảng 2.2]"},{"title":"Kiến trúc và cảnh quan","text":"Chưa có bình đồ, ảnh nền hay đoạn khảo tả riêng đã kiểm để trình bày kiến trúc. Không chuyển các dấu gạch, hồ nuôi tôm hoặc khoảng cách tới sông của Huỳnh Xá sang Nam Sơn."},{"title":"Thần linh và thực hành tín ngưỡng","text":"Thần chủ và thực hành tín ngưỡng của cơ sở cổ chưa được xác định. Những mô tả chung về miếu Bà hoặc cồn Giàng ở Quảng Trị chỉ cung cấp bối cảnh nghiên cứu, không là chứng cứ riêng cho điểm này."},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc nối chắc với Nam Sơn. Tất cả đề nghị về đời vua, tên thiêng hoặc niên đại phải giữ trống cho đến khi có văn bản hoặc tổ hợp khảo cổ phù hợp."},{"title":"Hiện vật và nơi lưu giữ","text":"Chưa có hiện vật được khóa bằng số kiểm kê và hồ sơ xuất xứ Nam Sơn. Cần tìm trong sổ kiểm kê di tích, báo cáo khảo sát địa phương và bộ ảnh cũ, giữ nguyên tên do từng hồ sơ sử dụng."},{"title":"Bảo tồn và tiếp cận di tích","text":"Hồ sơ hiện thích hợp làm điểm tra cứu chờ định danh, chưa thích hợp làm điểm dẫn đường. Bảo tồn ở giai đoạn này bắt đầu bằng việc giữ nguồn, truy lại người ghi tên và xác định thửa đất có căn cứ."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần phân biệt ba khả năng: địa điểm độc lập còn ít tư liệu, tên gọi khác của một nơi đã có hồ sơ, hoặc sai biệt trong quá trình chép danh mục. Chỉ sửa mã hoặc tên sau khi đối chiếu trang sách gốc và nguồn điền dã; không gộp theo sự gần nhau trên bản đồ."}],"thesis_locator":"Bảng 2.2 tr.59–62 chưa nối được tên","reference_numbers":[1,12],"related_ids":["BDS-0026","BDS-0027"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0028","name":"Nam Sơn","identity_note":"Tên Nam Sơn chưa nối được mục bảng luận án; không gộp Huỳnh Xá.","word_count":433,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":12,"title":"Nguyễn Văn Mạnh (14/05/2015). Văn hóa Champa ở Quảng Trị: tiềm năng và giải pháp phát triển du lịch. Tạp chí Cửa Việt.","url":"https://tapchicuaviet.vn/nguoi-dat-que-huong/van-hoa-champa-o-quang-tri-tiem-nang-va-giai-phap-phat-trien-du-lich--9787.html","scope":"Đọc danh sách địa điểm, trong đó có Nam Sơn và Phương Sơn; giữ dạng Trung Dân của bài để đối chiếu, không tự sửa thành Trung Sơn.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Một tên di tích cần được khóa lại trên thực địa","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,12],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0029":{"id":"BDS-0029","title":"Phường Sỏi — Cấu kiện thờ tự trong lớp miếu làng","lead":"Phường Sỏi cho thấy vật liệu Champa có thể tồn tại ngay trong các công trình thờ tự về sau. Bệ đá được dùng làm bậc cấp và gạch rải quanh miếu giúp nhận diện dấu cũ, đồng thời đặt ra yêu cầu tách cấu kiện nguyên thủy khỏi vị trí sử dụng lại.","province_source":"Quảng Trị","address_source":"Gio Phong - Gio Linh","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0029 ghi Gio Phong, Gio Linh; luận án đặt Phường Sỏi tại Lòi Giàng, tiểu khu III thị trấn Gio Linh và nhắc tên làng Lạc Tân trước đó. Đây là khác biệt địa chỉ cần đối chiếu theo thời điểm, không tự kết luận một bảng sai. [1, tr.80]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án truy ghi chép đầu thế kỷ XX về gò gạch sau miếu Bà Giàng, rồi đối chiếu với dấu vết ở lần khảo sát của tác giả. Hai lát cắt cho phép nhận biết sự thay đổi di tích, nhưng không thay thế một chuỗi hồ sơ liên tục suốt thế kỷ. [1, tr.80]"},{"title":"Kiến trúc và cảnh quan","text":"Khu gò chạy theo trục bắc–nam và quay ra vùng đồng ruộng được mô tả trong nguồn. Bốn chân tảng đá ong cùng phần bệ sa thạch được dùng làm bậc không tự xác nhận mặt bằng Champa. Chân tảng của ngôi miếu và cấu kiện lấy từ tháp phải được phân loại riêng. [1, tr.80]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Một phần bệ thờ gợi ý chức năng nghi lễ của cơ sở trước, nhưng chưa đủ để gọi chắc tên thần chủ. Ngôi miếu được xây lại và tín ngưỡng tại đó thuộc một lớp lịch sử khác; sự dùng lại vật liệu chưa chứng minh thực hành không gián đoạn. [1, tr.80]"},{"title":"Văn khắc liên quan","text":"Chưa có bản khắc được nối chắc với Phường Sỏi trong nguồn đã kiểm. Tên Lòi Giàng là đầu mối địa danh, không phải tên thiêng được văn khắc xác nhận."},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi một phần bệ sa thạch hình chữ nhật và một khối đá chưa rõ công dụng tại khu miếu. Phải giữ cả tình trạng chưa định danh của khối đá, thay vì đưa tất cả vào danh mục đồ thờ đã biết. Nơi lưu giữ được báo cáo là tại chỗ vào đợt khảo sát. [1, tr.80]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Đề xuất bảo tồn là lập hồ sơ ảnh và bản đo các cấu kiện đang bị bước chân, thoát nước hoặc tu sửa miếu tác động. Việc dịch chuyển vật liệu cần giữ đầy đủ vị trí cũ, người thực hiện và ngày chuyển; không nên sửa bệ để làm rõ một cách phục dựng chưa được kiểm."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần xác định gò gạch có còn nền nguyên vị, những cấu kiện nào thực sự thuộc đền tháp và địa chỉ nào tương ứng ở từng thời kỳ. Niên đại vẫn chưa được xác lập. Quan hệ với Hà Trung và An Xá là hướng khảo sát vùng, không phải kết luận về cùng một tổ chức tôn giáo."}],"thesis_locator":"80","reference_numbers":[1],"related_ids":["BDS-0025","BDS-0030"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0029","name":"Phường Sỏi","identity_note":"Phường Sỏi: Gio Phong khác thị trấn Gio Linh; cần lịch sử địa giới.","word_count":480,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Cấu kiện thờ tự trong lớp miếu làng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0030":{"id":"BDS-0030","title":"Hà Trung — Văn khắc và tổ hợp thờ Indrakānteśvara","lead":"Hà Trung có vị trí đặc biệt trong nhóm phế tích Bắc Champa vì còn kết hợp được dấu kiến trúc, hiện vật sa thạch và văn khắc. Di tích giúp đặt cơ sở thờ tự vào lịch sử bảo trợ và ruộng đất, nhưng một sự kiện khắc trên trụ chưa định tuổi cho toàn bộ các nền tháp.","province_source":"Quảng Trị","address_source":"Gio Châu - Gio Linh","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0030 ghi Gio Châu, Gio Linh, Quảng Trị. Luận án đặt phế tích trong khuôn viên chùa Bình Trung, làng Hà Trung. Cần phân biệt rõ với chùa Hà Trung ở Huế: trùng tên không phải cùng một di tích. Địa chỉ và phạm vi sử dụng hiện nay cần một lớp xác nhận riêng. [1, tr.70]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Cadière và Parmentier đã ghi nhận vật liệu kiến trúc tại địa điểm; luận án bổ sung khảo sát và thông tin bia phát hiện năm 2000. Vì các lớp tư liệu quan sát vào những thời điểm khác nhau, không thể cộng mọi hiện vật trong chúng thành một sưu tập nguyên vị duy nhất. [1, tr.70–71] Catalogue Parmentier 1919 ghi ít nhất chín cấu kiện Hà Trung đã về Đà Nẵng, trong đó bậc bệ thờ do chủ một chùa họ tên Bồ Đông Tự hiến năm 1918; tên chùa này khác tên chùa Bình Trung trong luận án và cần kiểm. [13, mục 22,3; 22,6; 24,1; 26,1–26,8]"},{"title":"Kiến trúc và cảnh quan","text":"Các trụ cửa, ngưỡng, bệ và cấu kiện lớn cho thấy quy mô xây dựng đáng kể. Hai trụ đang đứng trong mô tả khảo sát không đủ để phục nguyên một cổng nguyên thủy: một trụ gồm các khối chồng khác nhau, cần kiểm vị trí ghép và sự dịch chuyển. Bình đồ toàn quần thể vẫn cần được làm rõ. [1, tr.70]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tên Indrakānteśvara trong văn khắc hỗ trợ nhận diện một lớp thờ Śiva gắn với sự bảo trợ hoàng gia. Các vật trang trí và bệ thờ bổ sung ngữ cảnh vật chất, nhưng không cho phép coi mọi hiện vật tại chùa hiện nay đều thuộc riêng sự kiện lập tượng này. [1, tr.70–71]"},{"title":"Văn khắc liên quan","text":"C.113 mang mốc 838 Śaka. DHARMA công bố văn bản Chăm cổ và Sanskrit; phần dịch được kiểm có các danh mục ruộng và mốc giới đi qua sông, suối, bờ và nơi trữ nước. Đó là chứng cứ về cách văn bản xác lập tài sản, chưa là bản đồ có thể ghim thẳng lên thủy hệ hiện đại. [8, A20–A29; B1–B8] Corpus còn ghi C.260, một bia Sanskrit tái dùng làm ngưỡng cửa hoặc đá mài, xuất xứ Hà Trung. [14, C.260] DHARMA đã công bố chuyển tự dạng bản thảo, phần dịch còn trống; chưa xác định đây có phải bia phát hiện năm 2000 hay không. [16]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án phân biệt cấu kiện còn ở di tích, một bia chuyển về Bảo tàng Quảng Trị và nhóm hiện vật từng đưa về bảo tàng Đà Nẵng. Chưa tự coi bia mới được nhắc là một phần của C.113 khi chưa đối chiếu mã và bề mặt khắc. Cần nối từng hiện vật bằng số kiểm kê, ảnh và hồ sơ nhập kho. [1, tr.70–71] Bốn số BTC 40, 41, 46, 47 nối được với số Parmentier của Hà Trung; BTC 272 là ứng viên cần kiểm vật. [15; 13]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là kiểm kê trụ có chữ, tình trạng bề mặt và các cấu kiện bị chồng ghép; không can thiệp cơ học vào chữ để làm rõ nét. Hồ sơ bảo tồn phải bao gồm cả vị trí chứa và sử dụng lại đá trong khu chùa. Những đề nghị này chưa thay cho đánh giá hiện trường năm 2026."},{"title":"Những vấn đề đang nghiên cứu","text":"Hà Trung có thể được nghiên cứu như một thiết chế gắn cảnh quan sản xuất, nhưng muốn đi từ lời ghi ruộng đất đến năng lực kinh tế thực tế phải có chứng cứ bổ sung. Cần khóa từng pha kiến trúc và nhận diện riêng các địa danh trong C.113, thay vì lấy sự gần sông làm bằng chứng về cảng hoặc quyền kiểm soát vùng."}],"thesis_locator":"70–71","reference_numbers":[1,8,13,14,15,16],"related_ids":["BDS-0025","BDS-0029","BDS-0033","BDS-0038"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0030","name":"Hà Trung","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":679,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":8,"title":"Salomé Pichon (biên tập). DHARMA, INSCIC00113: Hà Trung, 838 Śaka. Phiên bản hiển thị 19/09/2026.","url":"https://dharmalekha.info/texts/INSCIC00113","scope":"Đọc thông tin ấn bản và các đoạn danh mục đất, mốc giới, thần danh. Các vị trí thủy văn trong bản dịch chưa được nhận diện với thủy hệ hiện đại.","access":"cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":14,"title":"Corpus văn khắc Champa của dự án, bản 3.2: danh mục 179 dòng mã C (tổng hợp Golzio 2004, kiểm kê EFEO/DHARMA chép trong corpus cũ, Griffiths và cộng sự 2012).","url":"","scope":"Đọc các dòng C.111, C.112, C.113, C.148, C.149, C.150, C.171, C.172, C.181, C.234, C.252, C.260, C.265: nơi phát hiện, nơi lưu giữ theo nguồn, niên đại từng nguồn, vật mang chữ, ngôn ngữ. Nơi lưu giữ là ghi chép kiểm kê cũ, chưa phải tình trạng năm 2026. Chưa đọc lại toàn văn ấn bản của từng mã.","access":"du_lieu_du_an"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày.","access":"du_lieu_du_an"},{"number":16,"title":"Arlo Griffiths. DHARMA, INSCIC00260: Hà Trung stele (C. 260), between 898 and 909 CE. Bản số hóa hiển thị 19/09/2026.","url":"https://dharmalekha.info/texts/INSCIC00260","scope":"Đọc siêu dữ liệu, chuyển tự và tình trạng biên tập ngày 04/11/2026: Sanskrit, chữ Chăm; có chuyển tự; phần dịch mới có dòng giữ chỗ; lịch sử sửa ghi ‘initial encoding’, trạng thái draft. Trang không nêu nơi tìm, nơi lưu giữ hay việc tái dùng đá.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Văn khắc và tổ hợp thờ Indrakānteśvara","primary_crosscheck":[{"source":13,"locator":"mục 22,3","data":"Bậc bệ thờ chạm sư tử và voi; xuất xứ ‘village de Hà-trung, pagode de Bồ-đông-tự, canton de An-xá, huyện de Do-linh [Gio Linh]’; ‘art primitif (VIIe–VIIIe siècle)’; chủ chùa họ hiến năm 1918, nửa bậc còn lại để tại chỗ.","relation":"khac_biet","note":"Tên chùa năm 1919 là Bồ Đông Tự, luận án ghi chùa Bình Trung: cần kiểm có phải cùng cơ sở. Định niên phong cách VII–VIII sớm hơn C.113 (917 CN): xác nhận nguyên tắc không lấy một mốc bia định tuổi cả quần thể."},{"source":13,"locator":"mục 22,6 (hai tiêu mục); 24,1; 26,1–26,3; 26,6; 26,8","data":"Phần dưới bệ tròn (có thể của liṅga), một tay vịn bậc lên (échiffre de perron) và năm trụ cửa đều ghi xuất xứ Hà-trung (cf. 22,3).","relation":"bo_sung","note":"Ít nhất chín cấu kiện Hà Trung đã về Đà Nẵng trước 1919."},{"source":14,"locator":"C.113; C.260","data":"C.113: cột (pilier), Chăm cổ và Sanskrit; Golzio 2004 quy đổi thứ Tư 19/3/917 CN (qua corpus 3.2), DHARMA đặt nhan đề 838 Śaka; chưa kiểm phép quy đổi ngày trên ấn bản DHARMA; kiểm kê cũ ghi in situ. C.260: corpus 3.2 (theo kiểm kê EFEO) ghi bia tái dùng làm ngưỡng cửa hoặc đá mài, Sanskrit, 898–909 CN, nơi lưu giữ chưa xác minh.","relation":"bo_sung","note":"C.260 là một văn khắc Hà Trung thứ hai bài chưa nêu. Cần kiểm C.260 có phải bia phát hiện năm 2000 ở Bảo tàng Quảng Trị hay không; chưa đồng nhất."},{"source":16,"locator":"C.260, siêu dữ liệu và lịch sử sửa","data":"Ấn bản DHARMA dạng bản thảo: Sanskrit, chữ Chăm, 898–909 CN; có chuyển tự, phần dịch còn trống; không nêu nơi tìm, nơi lưu giữ hay việc tái dùng đá.","relation":"can_kiem","note":"Có thể đọc chuyển tự ngay; chưa đủ đồng nhất với bia phát hiện năm 2000. Mô tả ‘tái dùng làm ngưỡng/đá mài’ đến từ kiểm kê EFEO trong corpus, không từ trang DHARMA."}],"inventory_links":[{"BTC":"46","P":"22.3","status":"confirmed","basis":"BTC ghi P 22.3; Parmentier 22,3 ghi Hà Trung.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 7","verified_against_original":"2026-11-04"},{"BTC":"47","P":"22.6","status":"confirmed","basis":"BTC ghi P 22.6; Parmentier 22,6 ghi Hà Trung.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 8","verified_against_original":"2026-11-04"},{"BTC":"40","P":"26.6","status":"confirmed","basis":"BTC ghi P 26.6; Parmentier 26,6 ghi Hà Trung.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 3","verified_against_original":"2026-11-04"},{"BTC":"41","P":"26.8","status":"confirmed","basis":"BTC ghi P 26.8; Parmentier 26,8 ghi Hà Trung.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 4","verified_against_original":"2026-11-04"},{"BTC":"272","P":"24.1","status":"candidate","basis":"BTC ghi P 24.1 nhưng tên ‘Đầu rắn’ (sân vườn); Parmentier 24,1 là tay vịn bậc lên chạm xoắn ốc ở Hà Trung. Cần kiểm vật.","source_row":"Sân vườn, dòng 1","verified_against_original":"2026-11-04"}],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,8,13,14,15,16],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [8], [13]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0031":{"id":"BDS-0031","title":"Lâm Lang — Dấu nền còn lại trong đồng bằng Cam Lộ","lead":"Lâm Lang là một phế tích mà phần lớn thông tin hiện có nằm ở dấu móng và phân bố gạch. Một bài giới thiệu đúng sức dữ liệu phải làm rõ giá trị của lớp nền ấy, đồng thời không dựng nên một ngôi tháp hoàn chỉnh từ vài mảnh vật liệu.","province_source":"Quảng Trị","address_source":"Cam Hiếu - Cam Lộ","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng BDS-0031 ghi Cam Hiếu, Cam Lộ, trong khi luận án ghi Cửa Đình, làng Lâm Lang, xã Cam Thủy. Cần đối chiếu lịch sử địa giới và trang nguồn trước khi chuẩn hóa. Không dùng sự khác xã để tự tách thành hai địa điểm. [1, tr.81–82]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Tư liệu khảo sát cho biết khu gò đã bị thu hẹp do canh tác. Chưa có một niên đại lập tháp hoặc cuộc khai quật được dùng để khóa lịch sử công trình trong bài này. Hồi ức về việc cắm nêu xuống đồng tại gò là dữ liệu đời sống làng, không phải chứng cứ trực tiếp cho công năng ban đầu. [1, tr.81]"},{"title":"Kiến trúc và cảnh quan","text":"Nguyễn Văn Quảng mô tả gò cao hơn ruộng xung quanh, còn khoảng 150 m² ở thời điểm khảo sát, có gạch rải và một số dấu nền. Diện tích này là phần gò còn lại, không phải diện tích nguyên thủy của đền. Các nhóm kích thước gạch chưa tự xác định số đợt xây. [1, tr.81–82]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Chưa có tượng hoặc đồ thờ được định danh chắc cho Lâm Lang trong phần tư liệu đã đọc. Vì vậy bài chưa gán thần chủ, chưa nối cơ sở vào một giáo phái và không lấy tên Cửa Đình làm dấu chắc của một thiết chế Champa."},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc liên quan được khóa mã. Không thể dùng niên đại bia Hà Trung hoặc Nhan Biều làm niên đại thay thế cho Lâm Lang chỉ vì cùng vùng Quảng Trị."},{"title":"Hiện vật và nơi lưu giữ","text":"Nhóm vật liệu được tác giả ghi trực tiếp là gạch và dấu nền tại gò. Chưa có danh mục tác phẩm điêu khắc mang xuất xứ Lâm Lang được xác nhận trong bộ nguồn này. Cần giữ trạng thái chưa biết của nơi lưu giữ hiện vật, không đổi thành khẳng định không có hiện vật. [1, tr.81–82]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Hướng bảo tồn phù hợp là lưu dấu mặt bằng, giới hạn canh tác và vị trí những đoạn móng còn thấy. Nếu tổ chức điền dã, cần đối chiếu thửa đất trước khi tiếp cận; điểm KMZ trùng tên không đủ làm ranh giới di tích."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi ưu tiên là phần nền còn nguyên vị đến đâu và khác biệt địa chỉ hình thành vào thời điểm nào. Việc so sánh với Định Xá hoặc Trương Xá chỉ có ích khi đã khóa từng địa điểm; không nên hợp nhất một cụm đền bằng khoảng cách gần trên bản đồ."}],"thesis_locator":"81–82","reference_numbers":[1],"related_ids":["BDS-0032","BDS-0033"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0031","name":"Lâm Lang","identity_note":"Lâm Lang: Cam Hiếu khác Cam Thủy; cần lịch sử địa giới.","word_count":468,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Dấu nền còn lại trong đồng bằng Cam Lộ","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0032":{"id":"BDS-0032","title":"Trương Xá — Từ khai quật năm 1911 đến hồ sơ xuất xứ hiện vật","lead":"Trương Xá có lịch sử khai quật sớm và nhóm hiện vật đáng chú ý, nhưng địa chỉ trong danh mục hiện có chưa thống nhất. Giá trị của hồ sơ nằm ở việc nối lại báo cáo đào, các cấu kiện và lịch sử chuyển vào bảo tàng, đồng thời giữ khoảng trống về hiện trường.","province_source":"Quảng Trị","address_source":"Cam Hiếu - Cam Lộ","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0032 ghi Cam Hiếu, Cam Lộ; luận án đặt địa điểm ở phường 4, Đông Hà. Khác biệt này cần kiểm bằng địa danh làng và lịch sử địa giới. Chưa sửa địa chỉ nguồn thành địa chỉ hiện hành, cũng chưa dùng một điểm ứng viên làm vị trí chắc chắn của cuộc khai quật. [1, tr.63]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguyễn Văn Quảng dẫn cuộc khai quật của Gariod năm 1911, cùng thông tin về việc chuyển hiện vật về cơ quan bảo tàng. Tác giả cho biết không được khảo sát bên trong khu đất tại thời điểm làm luận án. Vì vậy, phần mô tả hiện trường cổ chủ yếu đi qua báo cáo cũ, không phải một lần kiểm lại đầy đủ. [1, tr.63] Báo cáo của Gariod cho biết đây là một ngày đào đầu năm 1911 trên gò đối diện làng, ở bờ phải sông Cam Lộ, và mới thăm dò khoảng một phần năm diện tích gò. [19, tr.199–201]"},{"title":"Kiến trúc và cảnh quan","text":"Báo cáo được luận án tóm lược nhắc gò đất gần sông Hiếu, các cột đá, cấu kiện ngưỡng và dấu của một kiến trúc quay mặt về đông. Chưa đủ để khóa mặt bằng cả quần thể hoặc số tháp. Một cấu kiện được phát hiện trong nền nhà dân phải tách khỏi phần kiến trúc tìm tại hố đào. [1, tr.63] Gariod ghi gò bầu dục 30 × 20 m, cao khoảng 3 m, cách ga Đông Hà khoảng 6 km và cách sông 50 m; hai cột tròn, hai trụ vuông và ngưỡng cửa còn tại chỗ được ông hiểu là cổng hiên quay về Đông. [19, tr.200–201]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tượng Gaṇeśa trong danh mục khai quật gợi một lớp hình tượng thuộc bối cảnh Hindu. Vật trang trí được đề nghị là Rāhu và những đá chưa rõ công dụng không tự tạo thành một chương trình thờ tự hoàn chỉnh. Cần xác minh định danh từ ảnh và bản gốc trước khi diễn giải nghi lễ. [1, tr.63]"},{"title":"Văn khắc liên quan","text":"Chưa có một văn khắc được nối chắc với Trương Xá trong phần nguồn đã kiểm. Niên đại di tích vì thế vẫn để mở; không lấy phong cách một tác phẩm làm năm xây tất cả kiến trúc."},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi tượng Gaṇeśa từng được đưa về Đà Nẵng và về sau không còn tìm thấy, cùng các nhóm cấu kiện chuyển nơi lưu giữ. Đây là lịch sử ghi nhận theo nguồn; chưa phải xác nhận kiểm kê hiện hành. Muốn dựng hồ sơ gốc phải so ảnh, số catalogue và chứng từ nhập kho, không chỉ tìm theo nhãn Trương Xá. [1, tr.63] Tượng Gaṇeśa là mục Parmentier 5,4: được giữ ở Tòa Công sứ, rồi ở nhà xứ Bồ Liêu, vào bảo tàng Đà Nẵng năm 1918; số P này không có trong danh mục BTC đã đọc. Đĩa đồng Rāhu được gửi Bảo tàng EFEO. [19, tr.201; 13, mục 5,4; 15]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn trước hết cần xác định vị trí cuộc đào và quan hệ với khu đất sử dụng về sau. Trường hợp không tiếp cận được phải ghi rõ giới hạn, không trình bày ảnh vệ tinh hoặc lời kể như kết quả khảo sát nền móng."},{"title":"Những vấn đề đang nghiên cứu","text":"Báo cáo Gariod 1911 và catalogue Parmentier 1919 đã được đọc. Ưu tiên tiếp theo là kiểm các hình fig. 12–14 và sơ đồ gò của Gariod, rồi khóa chuỗi hiện vật bằng số kiểm kê: đĩa đồng Rāhu gửi Bảo tàng EFEO, các mảnh cột gửi Tòa Công sứ Quảng Trị và Gaṇeśa P 5,4. [19, tr.200–201; 13, mục 5,4] Khác biệt địa chỉ giữa các bảng cần được xử lý trước khi nghiên cứu cảnh quan sông Hiếu. Cần hỏi riêng về lịch sử xây, lịch sử phá dỡ và lịch sử sưu tập; ba quá trình không có cùng mốc."}],"thesis_locator":"63","reference_numbers":[1,13,15,19],"related_ids":["BDS-0031","BDS-0033"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0032","name":"Trương Xá","identity_note":"Trương Xá: địa chỉ Cam Hiếu khác phường 4 Đông Hà; cần lịch sử địa giới.","word_count":698,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR. Bản lớp chữ đã dùng: SHA-256 348d0e29f1015333b0a0a6a3200b42cee3dd734c9a323822f579c91fae7dd709. Kiểm độc lập ngày 04/11/2026 chưa mở lại được trọn lớp chữ các mục; cần đọc ảnh trang cho các mục quyết định.","access":"cong_khai"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày. Tệp gốc: Mã_Số.DOC, SHA-256 700912863c766412545fa2e057207b643343f545a19245064f68971d8ca45dff; 247 dòng bảng. Mỗi liên kết ghi phòng và số thứ tự dòng; cả 17 cặp BTC–P đã đối chiếu lại trực tiếp trên bảng của tệp gốc ngày 04/11/2026.","access":"du_lieu_du_an"},{"number":19,"title":"Ch. Gariod (1911). Une journée de fouilles à Trương-xá. BEFEO 11, tr.199–201. DOI: 10.3406/befeo.1911.2681.","url":"https://www.persee.fr/doc/befeo_0336-1519_1911_num_11_1_2681","scope":"Đọc trọn lớp chữ Persée tr.199–201. Các hình fig. 12–14 (cột, đầu Rāhu, sơ đồ gò) chưa xem ở độ phân giải đủ đo.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Từ khai quật năm 1911 đến hồ sơ xuất xứ hiện vật","primary_crosscheck":[{"source":19,"locator":"tr.199, 201","data":"Địa điểm: bờ phải sông Cam Lộ, đối diện làng Trương Xá, huyện Cam Lộ; cách ga Đông Hà khoảng 6 km; cách sông 50 m.","relation":"can_kiem","note":"Dòng BDS ghi Cam Hiếu, Cam Lộ; luận án ghi phường 4, Đông Hà. Mô tả năm 1911 cho manh mối định vị (bờ sông, khoảng cách tới ga) nhưng chưa đủ chọn một trong hai địa chỉ. Địa chỉ nguồn giữ nguyên."},{"source":19,"locator":"tr.199","data":"Đầu năm 1911 có tin một người làng nhặt gạch về xây nhà đã thấy bốn tượng đá; chánh tổng chỉ xác nhận một tượng, được người làng lấp lại bằng gạch vụn.","relation":"bo_sung","note":"Giải thích nguồn gốc chi tiết ‘cấu kiện trong nền nhà dân’ mà bài nêu; số ‘bốn tượng’ là tin đồn, không phải dữ kiện."},{"source":19,"locator":"tr.200","data":"Hai cột tròn và hai trụ vuông còn chân tại chỗ, ngưỡng cửa đá có lỗ mộng và hốc trục, đĩa đồng Rāhu cạnh ngưỡng.","relation":"xac_nhan","note":"Khớp tóm lược của luận án về cột đá, ngưỡng và kiến trúc quay về Đông. Việc gọi đó là ‘cổng hiên’ và đĩa Rāhu là đồ khóa cửa là cách hiểu của Gariod."},{"source":13,"locator":"mục 5,4","data":"Gaṇeśa ngồi xếp chân, rất thô, sa thạch nâu 0,46 × 0,43 × 0,27 m; xuất xứ ‘vestiges de Trương-xá, canton et huyện de Cam-lộ’; giữ ở Tòa Công sứ rồi nhà xứ Bồ Liêu; vào bảo tàng năm 1918; dẫn Inventaire tập II, tr.602.","relation":"xac_nhan","note":"Chuỗi lưu giữ khớp Gariod 1911 (Tòa Công sứ). Số P 5.4 không có trong danh mục BTC đã đọc [15]: phù hợp với ghi chép ‘không còn tìm thấy’ của luận án, nhưng ‘không thấy trong danh mục’ chưa chứng minh hiện vật đã mất."}],"inventory_links":[],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,13,15,19],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [13], [19]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[{"phase":"1","date":"đầu năm 1911, một ngày","actor":"Ch. Gariod, Công sứ Quảng Trị, do de Pirey báo tin","area":"Gò thấp trơ trụi, làm bãi chăn bò, ở bờ phải sông Cam Lộ, đối diện làng Trương Xá, huyện Cam Lộ; mới thăm dò khoảng 1/5 diện tích","architecture":"Hai cột tròn và hai trụ vuông (phần chân bám khối xây gạch, để lại tại chỗ), được Gariod hiểu là cổng hiên quay về Đông. Phía Bắc cổng có ngưỡng cửa đá với lỗ mộng và hốc trục cửa","finds":"Tượng Gaṇeśa đá (mặt và đầu tay vỡ, tìm được 3/4 mảnh mặt); một đoạn cột đá tròn có gờ vòng gồm hai mảnh khớp nhau; 4 phiến lát đá phiến đỏ có dấu chữ X; đĩa đồng mặt Rāhu có đinh tán và quai, tìm cạnh ngưỡng cửa (Gariod cho là đồ khóa cửa)","measurements":"Gò hình bầu dục, trục 30 × 20 m, cao trung bình 3 m; cách ga Đông Hà khoảng 6 km, cách sông 50 m; phiến lát 0,33 × 0,20 × 0,11 m","locator":"[19, tr.199–201]"},{"phase":"lưu giữ","date":"1911–1918","actor":"—","area":"—","architecture":"—","finds":"Đĩa đồng gửi Bảo tàng EFEO. Gaṇeśa và các mảnh cột tạm gửi ở Tòa Công sứ Quảng Trị. Parmentier 5,4 ghi Gaṇeśa xuất xứ Trương Xá được giữ ở Tòa Công sứ rồi ở nhà xứ Bồ Liêu, vào bảo tàng Đà Nẵng năm 1918","measurements":"Gaṇeśa 5,4: 0,46 × 0,43 × 0,27 m, sa thạch nâu","locator":"[19, tr.201]; [13, mục 5,4]"}]},"BDS-0033":{"id":"BDS-0033","title":"Kim Đâu — Nandin và bệ thờ giữa đồng ruộng","lead":"Kim Đâu được nhận diện qua gò Cồn Giàng, những dấu gạch và nhóm đá thờ. Đặc biệt, tượng Nandin cho phép đặt câu hỏi về một cơ sở thờ Śiva, nhưng khoảng niên đại của tác phẩm vẫn phải được phân biệt với thời điểm xây đền.","province_source":"Quảng Trị","address_source":"Cam An - Cam Lộ","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0033 ghi Cam An, Cam Lộ, Quảng Trị. Luận án dùng tên làng Kim Đâu; một số nghiên cứu trước dùng Cam Giang. Tác giả chủ trương phân biệt tên làng với tên xã, nên hồ sơ giữ các dạng này dưới mục truy nguyên, không tự coi là đồng nghĩa đã khóa. [1, tr.71]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Các đợt nghiên cứu sau năm 1975 đã mô tả hiện vật ở Cồn Giàng. Số lượng vật đá được ghi thay đổi giữa các lần khảo sát; có vật chuyển đi, có vật nằm dưới đất không xác định được hình loại. Không thể cộng số của nhiều đợt thành số hiện vật đang còn cùng lúc. [1, tr.71–72]"},{"title":"Kiến trúc và cảnh quan","text":"Khu gò giữa đồng ruộng, gần hệ nước nối sông Hiếu, đã bị san thu hẹp ở thời điểm nguồn ghi. Nền tháp chưa được phục nguyên chắc. Các bệ và đá kiến trúc giúp xác nhận dấu xây dựng, nhưng chưa đủ xác định hướng vào hoặc số gian của công trình. [1, tr.71]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Nandin cùng những ghi nhận về linga và yoni hỗ trợ nhận diện lớp thờ Śiva. Kiểu bệ sen của Nandin được tác giả chú ý vì ít gặp; tính ít gặp không tự chứng minh một tín ngưỡng địa phương riêng hoặc dấu của một xưởng duy nhất. [1, tr.71–72]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được xác lập trong nguồn đã kiểm. Mốc khoảng thế kỷ X được luận án đề nghị dựa trên đối sánh hiện vật; bài này giữ đó là niên đại học thuật của một nhóm chứng cứ, chưa là ngày khởi dựng. [1, tr.71–72]"},{"title":"Hiện vật và nơi lưu giữ","text":"Theo luận án, Bảo tàng Quảng Trị có Nandin và một bệ tròn trang trí sen mang xuất xứ Kim Đâu; tại gò còn một số khối đá bị vùi. Cần kiểm các ảnh cũ để phân biệt vật đã chuyển với vật tại chỗ. Chưa gán số kiểm kê khi chưa mở hồ sơ bảo tàng. [1, tr.71–72]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Đề xuất là lập hồ sơ từng khối đá, kiểm dấu vùi lấp và quan hệ với lớp nền trước khi thu gom. Không dựng lại một bộ linga–yoni chỉ vì đường kính hoặc hình thức có vẻ khớp; sự lắp ghép cần căn cứ mặt tiếp xúc và xuất xứ."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi quan trọng là các vật đá có cùng pha với dấu gạch còn lại hay đã được đưa về gò. Có thể đối chiếu Nandin Kim Đâu với Quảng Điền hoặc Đức Nhuận ở cấp hình thái, nhưng quan hệ nguồn và khoảng niên đại phải được kiểm riêng trước khi suy một trung tâm sản xuất."}],"thesis_locator":"71–72","reference_numbers":[1],"related_ids":["BDS-0030","BDS-0036","BDS-0047"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0033","name":"Kim Đâu","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":487,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Nandin và bệ thờ giữa đồng ruộng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0034":{"id":"BDS-0034","title":"Trà Liên — Những tác phẩm lớn và khoảng trống của mặt bằng đền","lead":"Trà Liên nổi bật nhờ điêu khắc, nhưng một sưu tập phong phú chưa tự cho biết cấu trúc ngôi đền đã sinh ra nó. Hồ sơ cần đặt tác phẩm, vị trí phát hiện và lịch sử di chuyển cạnh nhau.","province_source":"Quảng Trị","address_source":"Triệu Giang - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt di tích tại gò cát xóm Nam Bồi, làng Trà Liên, Triệu Giang, Triệu Phong, gần sông Thạch Hãn. Đây là địa chỉ theo thời điểm nguồn; chưa xác nhận ranh giới di tích và địa chỉ hành chính hiện nay. Tên Trà Liên trên nhãn bảo tàng cũng cần nối với chính địa điểm này bằng hồ sơ xuất xứ. [1, tr.74–75]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguyễn Văn Quảng dẫn các ghi chép Cadière năm 1905 và Parmentier năm 1909, rồi khảo sát năm 1983 của Viện Khảo cổ học và Đại học Tổng hợp Huế. Bộ linga–yoni từng được báo cáo không còn được nhóm năm 1983 nhận thấy. Không tìm thấy trong một đợt khảo sát chưa đủ xác định thời điểm và nguyên nhân thất tán. [1, tr.74]"},{"title":"Kiến trúc và cảnh quan","text":"Gò có dấu gạch, đá kiến trúc và bệ; việc sử dụng làm nơi chôn cất đã làm phức tạp mặt bằng. Mô hình ba kalan được tác giả đặt ra từ nhóm hiện vật là một đề nghị phục nguyên, chưa phải kết quả khai quật ba nền tháp. Cần kiểm phạm vi gò và quan hệ từng khối bệ trước khi dựng sơ đồ. [1, tr.74–75]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Phù điêu Śiva–Umā và tác phẩm Sūrya với bảy ngựa cho thấy sự hiện diện của những hệ hình tượng Hindu khác nhau. Chưa thể từ đó kết luận có hai giáo phái độc lập hoặc hai đền riêng. Một chương trình hình tượng có thể tổ chức nhiều thần trong cùng không gian; muốn phân biệt cần thêm ngữ cảnh kiến trúc. [1, tr.75]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc gắn chắc với Trà Liên trong phần nguồn đã kiểm. Khoảng cuối thế kỷ IX–đầu X được luận án đề nghị qua phong cách điêu khắc, cần được giữ ở cấp niên đại tác phẩm; không biến thành niên đại khởi dựng của toàn gò. [1, tr.75]"},{"title":"Hiện vật và nơi lưu giữ","text":"Nhóm bệ và phù điêu Sūrya được ghi chuyển về Bảo tàng Quảng Trị; một số đá vẫn được tác giả thấy tại gò. Những thông tin về tác phẩm đã mất hoặc chỉ còn ảnh phải có bản ghi riêng. Tình trạng bảo vật và nơi trưng bày năm 2026 cần kiểm với bảo tàng, không suy từ danh mục năm 2018. [1, tr.74–75]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là đối chiếu ảnh trước và sau khi di chuyển, xác lập bản đồ phân bố cấu kiện còn tại chỗ và tránh thu gom làm mất ngữ cảnh. Những khối bệ có thể khớp hình dáng vẫn cần kiểm mặt tiếp xúc, vật liệu và lịch sử phát hiện trước khi ghép."},{"title":"Những vấn đề đang nghiên cứu","text":"Trà Liên cho phép nghiên cứu quan hệ giữa một cơ sở thờ và sự tập trung tác phẩm lớn trong vùng Thạch Hãn. Nhưng quy mô quyền lực bảo trợ, số điện thờ và quan hệ với Dương Lệ vẫn là câu hỏi. Một mạng liên kết học thuật nên biểu thị các quan hệ này là giả thuyết, bên cạnh quan hệ hiện vật–nơi giữ đã có chứng cứ."}],"thesis_locator":"74–75","reference_numbers":[1],"related_ids":["BDS-0035","BDS-0037","BDS-0038"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0034","name":"Trà Liên","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":548,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Những tác phẩm lớn và khoảng trống của mặt bằng đền","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0035":{"id":"BDS-0035","title":"Dương Lệ — Cồn Giàng, Cồn Kéc và nhiều lớp diễn giải","lead":"Dương Lệ có hai địa điểm thường được nhắc cùng nhau cùng nhiều hiện vật đá. Cần giữ cấu trúc nhiều điểm ấy để hiểu di tích, thay vì thu lại thành một gò và một niên đại duy nhất.","province_source":"Quảng Trị","address_source":"Triệu Thuận - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng nguồn và luận án dẫn làng Dương Lệ Đông, Triệu Thuận, Triệu Phong. Cồn Giàng và Cồn Kéc là hai vị trí cần hồ sơ con riêng. Tên Dương Lệ trong sử liệu, địa danh làng và nơi xuất xứ tác phẩm không mặc nhiên có cùng phạm vi. [1, tr.67–69]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án đặt các ghi chép địa phương và sử liệu cạnh khảo tả Cadière, Parmentier. Những chuyện được chép trong Ô Châu cận lục không phải biên bản xây tháp. Việc một địa danh xuất hiện trong văn bản thế kỷ XVI chỉ chứng minh sự ghi nhận ở thời điểm đó, không trực tiếp xác định tuổi những nền gạch. [1, tr.67]"},{"title":"Kiến trúc và cảnh quan","text":"Cồn Kéc được mô tả nằm cách Cồn Giàng khoảng 200–300 m về tây bắc trong ghi chép cũ. Tại Cồn Giàng, việc san đất, sử dụng nghĩa trang và canh tác đã thay đổi địa hình; ở Cồn Kéc có gạch và ngói dạng lá. Khoảng cách dẫn lại chưa là phép đo hiện trường và không đủ để nối hai nơi thành một trục nghi lễ. [1, tr.67–69]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Yoni và các đá thờ hỗ trợ nhận diện yếu tố Śiva giáo. Một tượng nữ thường được gọi Umā cần đối chiếu lại thuộc tính và các mô tả cũ; tên định danh lặp lại trong nhiều tài liệu không thay thế phân tích hình tượng. Không dùng một định danh còn mở để dựng một điện thờ đã hoàn chỉnh. [1, tr.68–69]"},{"title":"Văn khắc liên quan","text":"Chưa có một mã bia riêng được xác lập cho hai gò trong bộ nguồn đã kiểm. Luận án thiên về khoảng cuối IX–đầu X đối với một số tác phẩm, trong khi dẫn một cách xếp thế kỷ XI. Đây là bất đồng cần truy đối tượng so sánh và tiêu chí, không nên lấy trung bình thành thế kỷ X. [1, tr.69]"},{"title":"Hiện vật và nơi lưu giữ","text":"Các ghi nhận gồm yoni lớn, bệ, ngưỡng và tượng đã chuyển nơi lưu giữ. Với mỗi tác phẩm cần biết đến từ Cồn Giàng, Cồn Kéc hay chỉ mang nhãn Dương Lệ. Nhãn địa danh chung chưa đủ làm bằng chứng về một sưu tập cùng địa tầng. Nơi giữ hiện hành cần khóa bằng kiểm kê. [1, tr.68–69]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn nên bắt đầu bằng bản đồ hai gò và vùng đất đã bị biến đổi, kết hợp ảnh cũ với dấu nền dưới mặt đất. Mọi khảo sát trong nghĩa trang cần tôn trọng việc sử dụng hiện tại. Hồ sơ dẫn đường chưa nên công khai một điểm suy đoán như lối vào chắc chắn."},{"title":"Những vấn đề đang nghiên cứu","text":"Việc giải thích Dương Lệ như một trung tâm tôn giáo của Châu Ô hoặc gắn trực tiếp với thành Thuận Châu là một mô hình nghiên cứu, không phải dữ kiện đồng thời đã chứng minh. Cần kiểm riêng niên đại thành, pha đền và xuất xứ hiện vật trước khi dùng mô hình Đan–Mạng để bàn về huy động nguồn lực."}],"thesis_locator":"67–69","reference_numbers":[1],"related_ids":["BDS-0034","BDS-0036","BDS-0037"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0035","name":"Dương Lệ","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":535,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Cồn Giàng, Cồn Kéc và nhiều lớp diễn giải","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0036":{"id":"BDS-0036","title":"Quảng Điền — Cồn Dưới và dấu tích thờ Śiva bên hệ Vĩnh Định","lead":"Quảng Điền trong hồ sơ này là một địa điểm ở Quảng Trị, cần phân biệt với huyện Quảng Điền của Huế. Những dấu gạch và tượng Nandin mở ra một trường hợp thờ tự đáng nghiên cứu, dù mặt bằng đền chưa rõ.","province_source":"Quảng Trị","address_source":"Triệu Đại - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án ghi Cồn Dưới, xóm Dưới, xã Triệu Đại, Triệu Phong, Quảng Trị. Hệ thống tra cứu cần kèm tỉnh nguồn để tránh nhập nhầm với các di tích ở Quảng Điền, Huế. Chưa dùng địa chỉ trong luận án như địa chỉ hiện hành. [1, tr.72]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Các khảo tả được tác giả tập hợp ghi gò, vật liệu xây dựng và hiện vật đá. Chưa có một cuộc khai quật toàn diện được làm căn cứ cho bình đồ trong bài này. Việc miếu Bà và chôn cất xuất hiện trên gò phản ánh lịch sử sử dụng về sau, cần được lập thành lớp riêng. [1, tr.72–73]"},{"title":"Kiến trúc và cảnh quan","text":"Gò nằm trong cảnh quan gần sông Vĩnh Định, có phần sử dụng làm nghĩa trang và canh tác. Hai nhóm bề rộng gạch được ghi không tự chứng minh hai pha kiến trúc. Ngưỡng và cấu kiện có lỗ tròn được đề nghị thuộc cùng bộ cửa, nhưng cần kiểm lắp ghép và vị trí phát hiện. [1, tr.72–73]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Nandin là chỉ dấu quan trọng của bối cảnh thờ Śiva. Quan hệ giữa tượng này, miếu Bà về sau và các nền gạch phải được nghiên cứu thay vì xem là một truyền thống không gián đoạn. Một tên gọi làng hiện nay không đủ giải thích thần chủ của công trình Champa. [1, tr.73]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được khóa cho Quảng Điền. Khoảng cuối IX–đầu X trong luận án dựa vào đối sánh Nandin; bài giữ mốc ở cấp tác phẩm. Cần dữ liệu địa tầng hoặc văn khắc trước khi dùng mốc đó cho toàn bộ cơ sở. [1, tr.73]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi Nandin và một đá trang trí góc kiến trúc ở Bảo tàng Quảng Trị; các dấu nền và một số đá còn tại gò. Phải nối hồ sơ bảo tàng với ảnh tại chỗ, tránh lập hai hiện vật chỉ vì cùng vật được chụp trước và sau khi di chuyển. [1, tr.72–73]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Cần kiểm kê phần gò còn nguyên, vị trí đá bị tái sử dụng và dấu cửa có thể ghép. Hồ sơ bảo tồn nên tách nguy cơ đối với nền dưới đất khỏi nguy cơ đối với tượng đã ở bảo tàng. Đề xuất chưa thay cho khảo sát hiện trạng."},{"title":"Những vấn đề đang nghiên cứu","text":"Quảng Điền có thể đối sánh với Kim Đâu và Đức Nhuận qua Nandin. Một nghiên cứu có sức kiểm chứng phải so kỹ bệ, tư thế, vật liệu và niên đại độc lập; sự giống đề tài chưa chứng minh cùng xưởng hoặc cùng chủ thể bảo trợ."}],"thesis_locator":"72–73","reference_numbers":[1],"related_ids":["BDS-0033","BDS-0035","BDS-0047"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0036","name":"Quảng Điền","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":475,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Cồn Dưới và dấu tích thờ Śiva bên hệ Vĩnh Định","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0037":{"id":"BDS-0037","title":"Bích La — Điêu khắc tách khỏi kiến trúc và vấn đề định danh tượng nữ","lead":"Bích La cho thấy sự khác nhau giữa một địa điểm gần như mất mặt bằng và những tác phẩm còn tiếp tục được nghiên cứu trong bảo tàng. Chính sự tách rời ấy đòi hỏi hồ sơ xuất xứ chặt chẽ.","province_source":"Quảng Trị","address_source":"Triệu Đông - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Nguyễn Văn Quảng đặt di tích tại Cồn Giàng, xóm Chùa, làng Bích La Trung, Triệu Đông, Triệu Phong. Đây là địa chỉ theo nguồn. Những tên làng rộng hơn trên catalogue cần giữ nguyên trong trường xuất xứ, rồi mới liên kết với hồ sơ địa điểm. [1, tr.64]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án dẫn các khảo tả sớm và thông tin san gò năm 1988. Mốc san gò là lịch sử biến đổi địa điểm, không phải niên đại kết thúc sử dụng đền. Những cấu kiện từng được thấy trước khi san có giá trị chứng cứ riêng, cần truy ảnh và mô tả gốc. [1, tr.64–65]"},{"title":"Kiến trúc và cảnh quan","text":"Dấu gạch, cấu kiện cửa và đá thờ cho thấy có kiến trúc tôn giáo. Tên thành trong cách gọi địa phương không đủ xác lập đây là thành lũy. Khi mặt bằng bị thay đổi, không nên dùng một ranh đất hiện tại để phục nguyên tường bao Champa. [1, tr.64–66]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Phù điêu Śiva múa và bộ phận yoni hỗ trợ một lớp thờ Śiva. Tượng nữ trong các mô tả trước được gọi khác nhau, trong đó có Umā và dạng Durgā diệt trâu. Cần phân biệt từng tác phẩm và đọc lại ảnh; không hợp hai định danh thành một nữ thần hỗn dung chỉ để dung hòa tài liệu. [1, tr.65–66]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được nối chắc với Bích La. Luận án đề nghị niên đại thế kỷ IX cho nhóm điêu khắc qua phong cách. Khoảng này chưa tự xác định ngày lập đền và cũng không giải quyết được thứ tự các công trình trên gò. [1, tr.66]"},{"title":"Hiện vật và nơi lưu giữ","text":"Phù điêu Śiva múa được nguồn ghi ở Bảo tàng Điêu khắc Chăm Đà Nẵng, một bệ yoni ở Bảo tàng Quảng Trị. Đường đi của tượng nữ trong tài liệu cần truy lại catalogue; bài chưa khóa tên bảo tàng hoặc thành phố khi các mô tả chưa thống nhất. Không coi nơi giữ chưa biết là hiện vật đã mất. [1, tr.65–66] Phù điêu Śiva múa là mục Parmentier 15,4, xuất xứ xóm Nam Giáp, làng Bích La, hiện mang số BTC 43. Ba tượng Parmentier ghi ‘Cổ Thành, tổng Bích La’ thuộc một làng khác và không được nhập vào hồ sơ này. [13, mục 15,4; 10,4; 13,3–13,4; 15]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là bảo tồn hồ sơ xuất xứ: ảnh gò trước san, số catalogue và lịch sử nhập kho. Ở địa điểm, cần xác nhận khu vực còn lớp nền trước bất kỳ khai đào mới nào. Các dấu bảo tồn pháp lý phải dựa vào văn bản, không suy từ giá trị nghệ thuật của một tác phẩm."},{"title":"Những vấn đề đang nghiên cứu","text":"Bích La đặt ra câu hỏi về cách một chương trình hình tượng được tái dựng khi bối cảnh kiến trúc đã phân tán. Muốn liên hệ với Trà Liên hoặc Dương Lệ cần khóa từng tác phẩm, thay vì gom các ảnh Śiva thành bằng chứng về một xưởng vùng chưa được xác nhận."}],"thesis_locator":"64–66","reference_numbers":[1,13,15],"related_ids":["BDS-0034","BDS-0035"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0037","name":"Bích La","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":541,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày.","access":"du_lieu_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Điêu khắc tách khỏi kiến trúc và vấn đề định danh tượng nữ","primary_crosscheck":[{"source":13,"locator":"mục 15,4","data":"Phù điêu Śiva múa mười tay trên mi cửa (tympan); xuất xứ ‘hameau de Nam-giáp du village de Bích-la, canton du même nom, phủ Triệu-phong’; ‘art primitif’; vào bảo tàng năm 1918.","relation":"xac_nhan","note":"Khớp phù điêu Śiva múa của bài. Xóm Nam Giáp (1919) khác cách ghi Cồn Giàng, xóm Chùa, Bích La Trung (luận án): cần đối chiếu bản đồ làng, chưa đồng nhất."},{"source":13,"locator":"mục 10,4; 13,3; 13,4","data":"Ba tượng ghi xuất xứ làng Cổ Thành, tổng Bích La (gần chùa Long Khánh, chợ Sãi), không phải làng Bích La.","relation":"khac_biet","note":"Không nhập hiện vật Cổ Thành vào hồ sơ Bích La chỉ vì cùng tên tổng. Cổ Thành chưa có hồ sơ trong 37 bài."}],"inventory_links":[{"BTC":"43","P":"15.4","status":"confirmed","basis":"BTC ghi P 15.4; Parmentier 15,4 ghi Nam Giáp, Bích La.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 5","verified_against_original":"2026-11-04"}],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,13,15],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [13]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0038":{"id":"BDS-0038","title":"Nhan Biều — Văn khắc C.149 và giới hạn của việc đưa lịch sử lên bản đồ","lead":"Nhan Biều có giá trị đặc biệt bởi C.149, văn khắc cho biết những quan hệ và hành động cụ thể mà gạch đá đơn thuần không thể kể lại. Tuy nhiên, nơi dựng bia không mặc nhiên trùng mọi địa điểm và tài sản được bia nhắc đến.","province_source":"Quảng Trị","address_source":"Triệu Thượng - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt địa điểm ở Cồn Mã Ngựa, xóm Giàng, làng Nhan Biều, Triệu Thượng, Triệu Phong. Cần phân biệt Nhan Biều ở Quảng Trị với Giám Biều hoặc Nham Biều tại Huế. Hai điểm phía đông và tây của vùng làng cũ cũng không được hợp nhất chỉ vì tên chung trong tài liệu đầu thế kỷ XX. [1, tr.73–74] Catalogue 1919 cho biết Inventaire sommaire số 172 ghi dưới tên Nhan Biều thực là xóm Đa Nghi ở phía đông làng; vì vậy dẫn chiếu cũ mang tên Nhan Biều cần được kiểm từng trường hợp. [13, mục 8,1, chú thích 1]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Các nghiên cứu đầu thế kỷ XX được luận án dẫn ghi cả bia và dấu kiến trúc. Phần khảo sát của tác giả cho thấy gạch và một mảnh cấu kiện, chưa đủ kiểm lại toàn thể công trình đã được văn bản nói tới. Lịch sử dựng cơ sở thờ và lịch sử phát hiện bia là hai chuỗi sự kiện cần phân biệt. [1, tr.73–74]"},{"title":"Kiến trúc và cảnh quan","text":"Cảnh quan gần Thạch Hãn giúp đặt câu hỏi về liên hệ sông và đất hiến cúng. Chưa có cơ sở phục nguyên một cảng, kinh đô hoặc trục đường nghi lễ từ vị trí ấy. Các địa danh trong bia cần hồ sơ nhận diện riêng; không kéo chúng về một điểm tọa độ của Nhan Biều."},{"title":"Thần linh và thực hành tín ngưỡng","text":"Luận án đọc C.149 như chứng cứ của cả hoạt động thờ Śiva và Phật giáo. Điều đó cần được hiểu ở cấp những hành động lập cơ sở được văn bản ghi, chưa đủ xác lập một mô hình dung hợp cho toàn dân cư. Cần kiểm thần danh và địa điểm của từng thiết lập trong ấn bản. [1, tr.73–74]"},{"title":"Văn khắc liên quan","text":"Ấn bản DHARMA xác nhận C.149 có Sanskrit và Chăm cổ, với mốc 833 Śaka ở tiêu đề. Các đoạn A9–A12 và phần tiếp theo ghi sứ vụ đến Java của Rājadvāra theo lệnh vua. Vì vậy không nên gọi các chuyến đi đơn thuần là hành hương. Việc văn bản nhắc nhiều đất và cơ sở càng đòi hỏi tách nơi dựng bia khỏi nơi được nhắc. [7]"},{"title":"Hiện vật và nơi lưu giữ","text":"Bia phải có một hồ sơ vật thể riêng gồm mặt khắc, ảnh, chuyển vị và nơi giữ; phần di tích có hồ sơ nền gạch và cấu kiện riêng. Bài chưa đưa ra xác nhận kiểm kê hiện hành của bia khi chưa đối chiếu bảo tàng. Mọi bản dập hoặc ảnh lịch sử cần nối về cùng vật thể, tránh tính thành nhiều bia. Kiểm kê cũ chép trong corpus ghi bia C.149 ở Bảo tàng Lịch sử Hà Nội, số 21154; vị trí trưng bày hiện nay chưa xác minh. [14, C.149]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là bảo tồn và công bố ảnh đủ các mặt chữ, ghi rõ phiên bản bản đọc, rồi mới nối các quan hệ lên bản đồ. Không làm sạch hoặc tô chữ để phục vụ đọc khi chưa có quy trình bảo tồn. Địa điểm của đất hiến cúng chưa nhận diện không nên được biểu diễn bằng tọa độ chắc chắn."},{"title":"Những vấn đề đang nghiên cứu","text":"C.149 phù hợp để kiểm khung Đan–Mạng qua quan hệ vua–sứ giả–thiết lập thờ tự. Nhưng việc có quan hệ ngoại giao không tự chứng minh quyền kiểm soát thương mại hoặc sự lệ thuộc chính trị giữa hai vùng. Một mô hình tốt cần chỉ rõ quan hệ nào được câu chữ xác nhận, quan hệ nào mới là suy luận và điều gì có thể bác bỏ nó."}],"thesis_locator":"73–74","reference_numbers":[1,7,13,14],"related_ids":["BDS-0030","BDS-0039","BDS-0053"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0038","name":"Nhan Biều","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":640,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":7,"title":"Arlo Griffiths, với đóng góp của Salomé Pichon. DHARMA, INSCIC00149: Nhan Biều, 833 Śaka. Phiên bản hiển thị 19/09/2026.","url":"https://dharmalekha.info/texts/INSCIC00149","scope":"Đọc thông tin ấn bản, văn bản và các đoạn liên quan sứ vụ Java, nhân danh, đất và cơ sở thờ. Chú dẫn theo mặt và dòng; không đồng nhất nơi dựng bia với tất cả địa danh được nhắc.","access":"cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":14,"title":"Corpus văn khắc Champa của dự án, bản 3.2: danh mục 179 dòng mã C (tổng hợp Golzio 2004, kiểm kê EFEO/DHARMA chép trong corpus cũ, Griffiths và cộng sự 2012).","url":"","scope":"Đọc các dòng C.111, C.112, C.113, C.148, C.149, C.150, C.171, C.172, C.181, C.234, C.252, C.260, C.265: nơi phát hiện, nơi lưu giữ theo nguồn, niên đại từng nguồn, vật mang chữ, ngôn ngữ. Nơi lưu giữ là ghi chép kiểm kê cũ, chưa phải tình trạng năm 2026. Chưa đọc lại toàn văn ấn bản của từng mã.","access":"du_lieu_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Văn khắc C.149 và giới hạn của việc đưa lịch sử lên bản đồ","primary_crosscheck":[{"source":13,"locator":"mục 8,1, chú thích 1","data":"Inventaire sommaire số 172 ‘Nhan Biều’ thực chỉ xóm Đa Nghi/Đông Giáp ở phía đông làng.","relation":"can_kiem","note":"Một số dẫn chiếu ‘Nhan Biều’ đầu thế kỷ XX có thể chỉ khu Đa Nghi, không phải Cồn Mã Ngựa, xóm Giàng. Củng cố cảnh báo không gộp hai điểm của bài."},{"source":14,"locator":"C.149","data":"Bia (kiểm kê: stèle), Chăm cổ và Sanskrit; Golzio 2004 ghi 911/912 CN (= 833 Śaka của nhan đề DHARMA); nơi lưu giữ theo kiểm kê cũ: Bảo tàng Lịch sử Hà Nội, số 21154; chưa xác minh trưng bày.","relation":"bo_sung","note":"Bổ sung ghi chép kiểm kê còn thiếu ở mục Hiện vật; đây là kiểm kê cũ, chưa phải xác nhận hiện hành."},{"source":13,"locator":"mục 14,1, đoạn bàn luận","data":"Parmentier dẫn Huber (BEFEO XI, tr.310): bia Nhan Biều cho thấy hai tín ngưỡng Śiva và Avalokiteśvara cùng thời; ông vẫn từ chối gọi tên hỗn dung khi chưa có văn khắc nói rõ.","relation":"xac_nhan","note":"Gốc học thuật của cách đọc ‘thờ Śiva và Phật giáo’ trong luận án; cùng thái độ thận trọng như bài."}],"inventory_links":[],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,7,13,14],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [7], [13]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0039":{"id":"BDS-0039","title":"Đa Nghi — Dấu đền, chùa Phật Lồi và vấn đề địa chỉ","lead":"Đa Nghi là trường hợp cần kiểm định danh trước khi bổ sung tọa độ. Những mô tả về chùa Phật Lồi, hiện vật bảo tàng và làng Nhan Biều cũ có quan hệ, nhưng không được tự hòa thành một địa chỉ duy nhất.","province_source":"Quảng Trị","address_source":"Cam Hiếu - Cam Lộ","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0039 ghi Cam Hiếu, Cam Lộ, trong khi luận án khảo tả khu Đa Nghi ở Ái Tử, Triệu Phong. Khác biệt này chưa được giải quyết. Bài giới thiệu phần di tích được luận án mô tả và giữ trạng thái nối tên có điều kiện với dòng BDS, chưa sửa âm thầm địa chỉ nguồn. [1, tr.69–70] Parmentier 1919 ghi Đa Nghi là xóm của làng Nhan Biều, tổng An Đôn, phủ Triệu Phong, và cho biết Đa Nghi với Đông Giáp là một xóm; dữ kiện này gần vị trí của luận án hơn địa chỉ Cam Lộ của dòng nguồn, nhưng địa chỉ nguồn vẫn giữ nguyên chờ lịch sử địa giới. [13, mục 8,1, chú thích 1]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án dẫn Cadière và Parmentier về khu phía đông làng Nhan Biều cũ, rồi mô tả dấu chùa Phật Lồi. Cần phân biệt địa điểm chùa cũ với chùa Chánh Giác xây dựng về sau. Việc cùng tên hoặc kế tục thờ tự không bảo đảm nền kiến trúc hiện tại trùng nền tháp. [1, tr.69]"},{"title":"Kiến trúc và cảnh quan","text":"Nguồn ghi gạch rải và các mảnh sa thạch, trong khi công trình đền không còn thấy nguyên dạng. Khi chưa có khai quật khóa mặt bằng, vị trí miếu hoặc bàn thờ thay thế chỉ là mốc của lịch sử sử dụng sau này. Hướng và quy mô tháp vẫn để mở. [1, tr.69–70]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Các nhóm Garuḍa, Apsaras và một tượng được nhận diện Viṣṇu trong tư liệu cũ mở ra vấn đề chương trình hình tượng Hindu. Tên Phật Lồi không đủ để xác lập cơ sở gốc là Phật giáo, cũng như riêng Garuḍa chưa đủ quyết định toàn bộ thần chủ. [1, tr.69–70]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc nối chắc với chính Đa Nghi trong phần đã đọc. C.149 của Nhan Biều phải giữ quan hệ địa danh cần kiểm; không nhập thành bia của Đa Nghi chỉ vì hai khu từng được gọi bằng một tên làng rộng. [1, tr.69–70]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án dẫn nhóm hiện vật ở Đà Nẵng gồm Garuḍa và Apsaras; các cách xếp niên đại sớm cần kiểm lại catalogue và đúng tác phẩm. Chưa dùng khoảng thế kỷ VII–VIII của một tượng để định tuổi tất cả dấu đền. Các cấu kiện tại chỗ và vật đã đưa đi cần hai danh mục liên kết. [1, tr.70] Catalogue 1919 cho biết tượng Viṣṇu 8,1, các apsaras 32,5–32,8 và phù điêu 35,1 có xuất xứ Đa Nghi; bốn hiện vật mang số BTC 39, 51, 53, 54, ba số apsaras khác là ứng viên. Khoảng thế kỷ VII–VIII là định niên phong cách của riêng tượng Viṣṇu. [13, mục 8,1; 32,5–32,8; 35,1; 15]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Cần đối chiếu địa chỉ dòng nguồn, vị trí chùa cũ và bản đồ làng trước khi cắm điểm. Khảo sát nên ghi cả đá tái sử dụng trong kiến trúc về sau, với sự đồng thuận của cơ sở sử dụng. Chưa xác nhận lối tiếp cận hoặc hiện trạng bảo tồn năm 2026."},{"title":"Những vấn đề đang nghiên cứu","text":"Ưu tiên cao nhất là giải quyết đồng nhất địa điểm. Sau đó mới nghiên cứu xem nhóm điêu khắc có cùng xuất xứ và pha sử dụng không. Đây là điều kiện để bàn về quan hệ Đa Nghi–Nhan Biều và mạng tôn giáo Thạch Hãn, thay vì biến một vấn đề tên gọi thành một kết luận lịch sử."}],"thesis_locator":"69–70","reference_numbers":[1,13,15],"related_ids":["BDS-0038","BDS-0042"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0039","name":"Đa Nghi","identity_note":"Đa Nghi: Cam Hiếu trong BDS khác Ái Tử trong luận án.","word_count":610,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":13,"title":"Henri Parmentier (1919). Catalogue du Musée Cam de Tourane. BEFEO 19, tr.1–114. DOI: 10.3406/befeo.1919.5651.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5651","scope":"Đọc trực tiếp bản Persée (lớp chữ OCR) các mục có xuất xứ Quảng Bình, Quảng Trị: 8,1; 13,2–13,4; 10,4; 14,1–14,3; 15,4; 22,1; 22,3; 22,6; 24,1; 26,1–26,8; 32,5–32,8; 35,1. Chú dẫn theo số mục của catalogue (ổn định hơn số trang OCR). Lớp OCR đọc chữ Đ đầu tên làng thành B (‘Ba-nghi’); bài trích lại theo dạng Đa-nghi mà chính chú thích của Parmentier xác nhận. Mục 32,1–32,4 và 41,x không đọc được tiêu đề xuất xứ trong lớp OCR.","access":"cong_khai"},{"number":15,"title":"Bảo tàng Điêu khắc Chăm Đà Nẵng. Danh mục mã số hiện vật theo phòng trưng bày (cột BTC, P = số Parmentier, BTĐN).","url":"","scope":"Dùng phòng ‘Quảng Trị, Quảng Bình’ và mục sân vườn để nối số BTC với số Parmentier. Chỉ công bố từng số liên quan; không công bố toàn danh mục. Khớp số P mới là liên kết kiểm kê, chưa phải xác nhận hiện vật đang trưng bày.","access":"du_lieu_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Dấu đền, chùa Phật Lồi và vấn đề địa chỉ","primary_crosscheck":[{"source":13,"locator":"mục 8,1","data":"Viṣṇu đứng bốn tay; xuất xứ: ‘vestiges d’un monument čam au hameau de Đa-nghi, village de Nhan-biều, canton An-đôn, phủ Triệu-phong, Quảng-trị’. Parmentier xếp ‘art primitif (VIIe–VIIIe siècle)’. Bệ được nhận biết năm 1901; thân tượng tìm trong một đợt đào do một công sứ cho làm, được Huber báo theo De La Susse ở nơi gọi Đông-giáp, đồng nhất với Đa-nghi năm 1915; vào bảo tàng năm 1918.","relation":"bo_sung","note":"Khoảng thế kỷ VII–VIII mà luận án dẫn là định niên phong cách của riêng pho tượng này; không dùng cho toàn bộ dấu đền."},{"source":13,"locator":"mục 8,1, chú thích 1","data":"Hai tên Đa-nghi và Đông-giáp (‘xóm phía Đông’) chỉ cùng một xóm của làng Nhan Biều; điểm này từng được ghi dưới tên Nhan Biều trong Inventaire sommaire, số 172.","relation":"xac_nhan","note":"Nguồn gốc xác nhận Đa Nghi thuộc phủ Triệu Phong vào đầu thế kỷ XX, phù hợp vị trí Ái Tử của luận án hơn địa chỉ Cam Hiếu, Cam Lộ của dòng BDS. Không tự sửa địa chỉ nguồn: cần lịch sử địa giới."},{"source":13,"locator":"mục 32,5–32,8; 35,1","data":"Các ‘pièces d’accent’ hình apsaras (32,5–32,8) và mảnh phù điêu bình lễ giữa dây lá (35,1) ghi xuất xứ Đa-nghi (cf. 8,1).","relation":"bo_sung","note":"32,5–32,6 ghi ‘même histoire’ với 32,1–32,4; tiêu đề xuất xứ của 32,1–32,4 không đọc được trong OCR."}],"inventory_links":[{"BTC":"39","P":"35.1","status":"confirmed","basis":"BTC ghi P 35.1; Parmentier 35,1 ghi Đa-nghi.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 2","verified_against_original":"2026-11-04"},{"BTC":"51","P":"32.5","status":"confirmed","basis":"BTC ghi P 32.5; Parmentier 32,5 ghi Đa-nghi.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 9","verified_against_original":"2026-11-04"},{"BTC":"53","P":"32.6","status":"confirmed","basis":"BTC ghi P 32.6; Parmentier 32,6 ghi Đa-nghi.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 11","verified_against_original":"2026-11-04"},{"BTC":"54","P":"32.7","status":"confirmed","basis":"BTC ghi P 32.7; Parmentier 32,7–32,8 ghi Đa-nghi.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 12","verified_against_original":"2026-11-04"},{"BTC":"57","P":"32.2","status":"candidate","basis":"BTC ghi P 32.2; tiêu đề xuất xứ 32,1–32,4 không đọc được, chỉ có ‘même histoire’ ở 32,5–32,6.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 13","verified_against_original":"2026-11-04"},{"BTC":"59","P":"32.3","status":"candidate","basis":"Như trên.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 14","verified_against_original":"2026-11-04"},{"BTC":"61","P":"32.4","status":"candidate","basis":"Như trên.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 16","verified_against_original":"2026-11-04"},{"BTC":"52","P":"41.5","status":"unresolved","basis":"Garuḍa cùng phòng; số P 41,x chưa thấy trong lớp chữ Parmentier 1919 đã đọc; chưa nối với Đa Nghi.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 10","verified_against_original":"2026-11-04"},{"BTC":"60","P":"41.3","status":"unresolved","basis":"Như trên.","source_row":"Phòng Quảng Trị, Quảng Bình, dòng 15","verified_against_original":"2026-11-04"}],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,13,15],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [13]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0040":{"id":"BDS-0040","title":"Phương Sơn — Miếu Nghè và đời sống về sau của một tác phẩm đá","lead":"Phương Sơn cần được giới thiệu từ cả tác phẩm đá lẫn cách cộng đồng lưu giữ và kể về nó. Chuyện kể là một lớp tư liệu có giá trị riêng, cần phân biệt với biên bản phát hiện khảo cổ.","province_source":"Quảng Trị","address_source":"Triệu Sơn - Triệu Phong","source_page":"63","review_status":"editorial_draft_identity_unresolved","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0040 ghi Phương Sơn, Triệu Sơn, Triệu Phong, Quảng Trị. Bài của Yến Thọ trên Tạp chí Cửa Việt cung cấp đầu mối miếu Nghè ở phía đông làng. Đây là bước bổ sung định danh, chưa phải xác nhận tọa độ hay địa chỉ hiện hành. [2;11]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Bài báo ghi miếu được làm lại năm 1994 và kể truyền thuyết phát hiện đá khi đi đánh cá. Hai loại thông tin không có cùng giá trị: mốc sửa miếu cần hồ sơ công trình, còn truyền thuyết phản ánh ký ức cộng đồng, chưa xác lập nơi tìm thấy thật của hiện vật. [11]"},{"title":"Kiến trúc và cảnh quan","text":"Nguồn địa phương đặt miếu trên cồn cát trong không gian thờ tự của làng. Chưa có bình đồ nền đền Champa được kiểm trong lượt này. Cần khảo sát quan hệ giữa miếu, gò và lớp gạch dưới đất trước khi gọi toàn khu là phế tích tháp. [11]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Một phù điêu nam thần được kể gắn với thần Đá hoặc Bà Đá. Những tên gọi này cần giữ nguyên như dữ liệu dân gian, không dùng để kết luận giới tính hoặc thần danh Champa. Cũng chưa nên nhận diện là Śiva, Viṣṇu hay một Bồ tát nếu chưa có ảnh đủ thuộc tính. [11]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc Champa được khóa mã cho Phương Sơn. Bài báo nhắc sắc phong và tước hiệu thành hoàng, nhưng bản gốc các sắc chưa được mở ở đây. Văn bản triều Nguyễn, nếu xác minh, sẽ là chứng cứ của một lớp thờ tự về sau, không tự cho niên đại chế tác tác phẩm đá. [11]"},{"title":"Hiện vật và nơi lưu giữ","text":"Cần lập hồ sơ vật thể cho phù điêu: ảnh mặt trước, sau, cạnh, dấu gãy và lớp sơn. Chưa có kiểm kê bảo tàng hoặc chuỗi chuyển vị được kiểm trực tiếp. Do truyền thuyết còn nhắc quan hệ với làng khác, nơi đang thờ và nơi xuất xứ phải để thành hai trường riêng."},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên bảo tồn là ghi lại vật trong bối cảnh đang được cộng đồng thờ, trước mọi đề nghị di chuyển hoặc làm mới. Không tẩy màu, mài bề mặt hoặc lấy dấu khi chưa có ý kiến chuyên môn. Dẫn đường chỉ nên bổ sung sau xác nhận tại chỗ và điều kiện tiếp cận của miếu."},{"title":"Những vấn đề đang nghiên cứu","text":"Phương Sơn thích hợp cho nghiên cứu biến đổi tên thần và cách một vật cổ tham gia đời sống làng. Khung Đan–Mạng chỉ hữu ích nếu theo dõi được chủ thể, hành động và sự thay đổi theo thời gian; không thể lấy một truyền thuyết làm bằng chứng liên tục từ Champa đến hiện nay. Cần truy bài gốc Cadière mà nguồn địa phương dẫn và đối chiếu chính tác phẩm."}],"thesis_locator":"Chưa nối được bảng khảo tả","reference_numbers":[2,11],"related_ids":["BDS-0034","BDS-0037"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0040","name":"Phương Sơn","identity_note":"Phương Sơn được bổ sung nguồn địa phương; chưa nối mục bảng luận án và chưa kiểm vật.","word_count":502,"references":[{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"},{"number":11,"title":"Yến Thọ. Thành hoàng làng Phương Sơn: huyền tích, thần tích và hiện thực. Tạp chí Cửa Việt; chưa xác lập ngày đăng từ trang đã đọc.","url":"https://tapchicuaviet.vn/nguoi-dat-que-huong/thanh-hoang-lang-phuong-son-huyen-tich-than-tich-va-hien-thuc-12787.html","scope":"Đọc bài viết; phân biệt truyền thuyết, tường thuật về miếu và trích dẫn sắc phong. Chưa kiểm bản gốc sắc hoặc khảo sát hiện vật trực tiếp.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Miếu Nghè và đời sống về sau của một tác phẩm đá","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[2,11],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0041":{"id":"BDS-0041","title":"Ngô Xá — Hai miếu làng và dấu nền ở Cồn Giàng","lead":"Ngô Xá có dấu tích kiến trúc nằm trong một cảnh quan làng đã đổi công năng. Trọng tâm bài là xác định phần nào thuộc chứng cứ Champa và phần nào thuộc lịch sử sử dụng gò về sau.","province_source":"Quảng Trị","address_source":"Triệu Trung - Triệu Phong","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Nguyễn Văn Quảng ghi Cồn Giàng, còn gọi Lùm Giàng, xóm Đồng Bái, làng Ngô Xá Tây, xã Triệu Trung, Triệu Phong. Cần giữ tên xóm và gò để tránh nhầm những địa danh Ngô Xá khác. Địa chỉ hiện hành và phạm vi pháp lý chưa được xác nhận trong bài này. [1, tr.72]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án dẫn khảo tả Parmentier năm 1909 về gò có vật liệu gạch và đá, rồi mô tả tình trạng nguồn khảo sát sau này. Đó là chuỗi ghi nhận một địa điểm, chưa phải chứng cứ sử dụng liên tục. Cần truy ảnh và sơ đồ gốc nếu muốn so mức hao hụt của gò. [1, tr.72]"},{"title":"Kiến trúc và cảnh quan","text":"Vị trí ở bờ bắc hệ Vĩnh Định có ý nghĩa cảnh quan, song chưa đủ xác định chức năng giao thông hay bến. Nguồn ghi hai nhóm kích thước gạch và hai mảnh chân bệ sa thạch. Chúng xác nhận vật liệu xây dựng, chưa cho biết số tháp hoặc số pha. [1, tr.72]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Hai miếu được gọi miếu Bà Hỏa và miếu thổ thần trong khảo tả. Tên miếu phản ánh lớp sử dụng làng; chưa có căn cứ để chuyển nguyên các tên ấy thành thần chủ Champa. Những mảnh chân bệ cũng chưa đủ nhận diện vật thờ từng đặt bên trên. [1, tr.72]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được xác lập cho Ngô Xá trong phần nguồn đã đọc. Vì vậy bài không gán một vương triều hoặc niên đại thế kỷ từ các di tích lân cận. Cần giữ trạng thái chưa xác định thay vì xếp mặc định vào khoảng thế kỷ IX–X."},{"title":"Hiện vật và nơi lưu giữ","text":"Các mảnh đá tại gò cần hồ sơ đo, ảnh và nhận diện mặt tiếp xúc. Chưa có một sưu tập bảo tàng mang xuất xứ Ngô Xá được khóa bằng số kiểm kê ở đây. Không được suy rằng một bệ còn lại chứng minh linga hoặc tượng cụ thể cũng đã được tìm thấy. [1, tr.72]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Việc lập ranh vùng khảo sát nên đi cùng lịch sử sửa miếu và canh tác. Cần ghi riêng cấu kiện tái sử dụng trong miếu với đá còn gắn nền; nếu thu gom đồng loạt, mối quan hệ này sẽ mất. Chưa có đánh giá hiện trạng thực địa năm 2026."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi có thể kiểm trước là phần gò nào còn địa tầng và các mảnh bệ có thuộc cùng bộ không. Sau đó mới đối sánh Ngô Xá với Quảng Điền hoặc Dương Lệ. Sự cùng hiện diện gần sông chưa đủ thành bằng chứng về một mạng đền đồng thời."}],"thesis_locator":"72","reference_numbers":[1],"related_ids":["BDS-0035","BDS-0036","BDS-0043"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0041","name":"Ngô Xá","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":476,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Hai miếu làng và dấu nền ở Cồn Giàng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0042":{"id":"BDS-0042","title":"Thạch Hãn — Hai gò cổ dưới không gian đô thị","lead":"Thạch Hãn không nên được biểu diễn như một điểm phế tích duy nhất khi tư liệu cũ đã mô tả hai gò. Đô thị hóa và việc di chuyển tác phẩm càng làm cần thiết một hồ sơ nhiều vị trí, nhiều thời điểm.","province_source":"Quảng Trị","address_source":"Thị xã Quảng Trị","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt dấu tích ở khu vực gần nhà thờ, đường Hai Bà Trưng, thị xã Quảng Trị theo địa chỉ thời điểm nghiên cứu. Tên phường khác nhau trong các nguồn cần đối chiếu lịch sử địa giới; chưa coi khác biệt ấy là bằng chứng có thêm một di tích. [1, tr.77–78]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Cadière được luận án dẫn mô tả hai gò theo hướng bắc–nam, cách khoảng 500 m: Cồn Dàng Trên ở phía nam lớn hơn, Cồn Dàng Dưới ở phía bắc nhỏ hơn. Đây là mô tả lịch sử cần định vị lại; không nên dùng khoảng cách dẫn lại làm tọa độ chính xác. [1, tr.77]"},{"title":"Kiến trúc và cảnh quan","text":"Đá cửa và dấu gạch cho thấy kiến trúc đã tồn tại, nhưng phần lớn bối cảnh đã biến đổi trong đô thị. Một bản đồ có thể giữ vùng ứng viên của từng gò, kèm nguồn và thời điểm; chưa nên phục nguyên tuyến đường hoặc trục nghi lễ nối chúng. [1, tr.77–78]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tượng nam mất đầu và phù điêu thường được gọi cảnh chơi polo đặt ra những vấn đề khác nhau. Tác phẩm đầu thiếu thuộc tính không nên tự nhận là thần chủ; cảnh sinh hoạt cũng không tự cho biết chức năng điện thờ. Danh xưng polo cần được giữ như một cách đọc hình tượng cần đối chiếu. [1, tr.78]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được nối chắc trong bộ nguồn đã kiểm. Những cách xếp niên đại khác nhau cho tượng nam và phù điêu chưa tạo ra một niên đại chung của hai gò. Sự khác phong cách có thể phản ánh nhiều pha hoặc nhiều nguồn gốc; cần kiểm trước khi lựa chọn. [1, tr.78]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi tượng nam tại Bảo tàng Cổ vật Cung đình Huế và phù điêu tại Đà Nẵng. Cần khóa số kiểm kê cùng gò xuất xứ cụ thể nếu có. Nhãn Thạch Hãn rộng chưa cho phép trả tác phẩm về Cồn Dàng Trên hoặc Dưới bằng suy đoán. [1, tr.77–78]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là đối chiếu địa bạ, bản đồ và ảnh đô thị với mô tả hai gò. Những công trình hiện tại không phải mốc nguyên thủy của đền. Dữ liệu vị trí cần được lưu với mức bất định, tránh cung cấp dẫn đường đến một khu đất chưa xác nhận."},{"title":"Những vấn đề đang nghiên cứu","text":"Thạch Hãn có thể làm trường hợp nghiên cứu về sự phân tán ký ức và vật thể khi một phế tích nằm trong đô thị. Muốn bàn về quan hệ giữa hai cơ sở phải kiểm tính đồng thời và xuất xứ tác phẩm trước; hai gò gần nhau không mặc nhiên là một quần thể cùng chủ thể bảo trợ."}],"thesis_locator":"77–78","reference_numbers":[1],"related_ids":["BDS-0038","BDS-0039","BDS-0043"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0042","name":"Thạch Hãn","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":498,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Hai gò cổ dưới không gian đô thị","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0043":{"id":"BDS-0043","title":"Trà Lộc — Yoni trong cảnh quan bàu và lớp thờ Bà Giàng","lead":"Trà Lộc còn một dấu thờ tự đáng chú ý giữa cảnh quan bàu, gò và làng. Giá trị nghiên cứu nằm ở cả vật đá lẫn các thay đổi trong cách lắp đặt và sử dụng nó.","province_source":"Quảng Trị","address_source":"Hải Xuân - Hải Lăng","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án ghi Lùm Giàng, xóm Chùa, Hải Xuân, Hải Lăng. Tên Trà Lộc trong du lịch sinh thái không tự xác định ranh giới khảo cổ; hồ sơ cần tách khu cảnh quan rộng với vị trí vật thờ và vùng nền gạch. Địa chỉ hiện nay chưa được xác nhận. [1, tr.75–76]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn mô tả một miếu Bà Giàng xây lại bằng vật liệu mới và yoni ở phía trước. Lịch sử sửa miếu chưa được khóa bằng hồ sơ công trình. Cần giữ mốc khảo sát của luận án thay vì trình bày mô tả này như ảnh chụp hiện trạng năm 2026. [1, tr.75–76]"},{"title":"Kiến trúc và cảnh quan","text":"Yoni đặt trên bệ nhiều tầng trong khu có gạch và vật liệu. Tác giả nhận xét hướng vòi và khả năng dịch chuyển; riêng hướng ấy chưa đủ chứng minh vị trí gốc. Cần kiểm liên kết giữa bệ, lớp nền và dấu đặt đá, không dùng phương vị đơn lẻ để phục nguyên hướng đền. [1, tr.76]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Yoni hỗ trợ nhận diện một lớp thờ Śiva; tên Bà Giàng là dữ liệu của lớp thờ tự về sau. Hai đá tròn đặt trên yoni được nguồn xem là vật bổ sung, không nên giới thiệu như linga Champa đã xác định. Hốc dạng bát giác cho phép đặt giả thuyết về bộ phận mất, chưa đủ phục chế nó. [1, tr.76]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc gắn chắc với Trà Lộc được kiểm. Những phát hiện thuộc thời kỳ khác trong vùng, nếu có, không tự chứng minh đền được sử dụng liên tục qua nhiều thiên niên kỷ. Bài giữ niên đại nền kiến trúc ở trạng thái chưa khóa."},{"title":"Hiện vật và nơi lưu giữ","text":"Vật thờ đang được mô tả tại địa điểm cần hồ sơ riêng cho yoni, bệ và các đá đặt thêm. Không lập một bộ hiện vật nguyên thủy chỉ vì chúng đang ở cùng nhau. Chưa có danh mục chuyển vào bảo tàng được kiểm trực tiếp trong bài này. [1, tr.76]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là chụp và đo nguyên trạng trước khi có sửa miếu hoặc thay bệ. Cảnh quan bàu cần được ghi cùng cao độ và mùa nước, song chưa tự xác định tình trạng thủy văn cổ. Việc tiếp cận phải theo điều kiện của cộng đồng sử dụng miếu."},{"title":"Những vấn đề đang nghiên cứu","text":"Trà Lộc phù hợp nghiên cứu sự tái sử dụng vật thờ và cảnh quan nước. Một quan hệ Đan–Mạng cần được chứng minh bằng hành động và mốc thời gian, chẳng hạn ai lắp lại vật, sửa miếu hoặc thay cách thờ; không nên suy sự tiếp nối nguyên vẹn của tín ngưỡng từ một tên gọi."}],"thesis_locator":"75–76","reference_numbers":[1],"related_ids":["BDS-0041","BDS-0044","BDS-0054"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0043","name":"Trà Lộc","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":480,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Yoni trong cảnh quan bàu và lớp thờ Bà Giàng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0044":{"id":"BDS-0044","title":"Câu Hoan hoặc Cu Hoan — Bộ linga và những cách đọc khác nhau","lead":"Câu Hoan có nhóm hiện vật tôn giáo được ghi nhận sớm, song tên gọi và định danh một số tác phẩm còn cần đối chiếu. Bài giữ riêng những vật đã thấy, vật chỉ còn trong mô tả và các đề nghị lắp ghép.","province_source":"Quảng Trị","address_source":"Hải Thiện - Hải Lăng","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng BDS-0044 viết Câu Hoan, còn luận án dùng Cu Hoan, ở xóm Cồn Chùa, thôn 2, Hải Thiện, Hải Lăng. Hai dạng tên được nối có điều kiện, chờ kiểm trang nguồn và địa danh làng. Không thay âm thầm tên gốc trong dữ liệu. [1, tr.66; 2]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án dẫn khảo tả Cadière và Parmentier về linga, đầu tượng người, Mukhalinga và phù điêu hộ vệ. Một số vật không còn được tác giả thấy trong khảo sát sau này. Chưa xác định được chúng đã chuyển vào sưu tập hay mất, nên không dùng từ thất lạc như kết luận cuối. [1, tr.66–67]"},{"title":"Kiến trúc và cảnh quan","text":"Địa điểm nằm trên cồn cát, với vật liệu gạch và các đá thờ quanh miếu Bà Giàng. Chưa có bình đồ khai quật được dùng để khóa số tháp. Những mảnh yoni được đề nghị ghép với linga cần kiểm các mặt gãy và lịch sử phát hiện trước khi dựng một bộ thờ nguyên thủy. [1, tr.66–67]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Linga ba phần được nguồn mô tả có lớp sơn đỏ. Đầu người từng được nhận diện Brahmā hoặc Śiva cho thấy bất đồng hình tượng thực sự. Cần dựa vào thuộc tính còn lại và ảnh đủ góc; không lấy lựa chọn của một tác giả làm kết luận tuyệt đối khi căn cứ chưa được kiểm trực tiếp. [1, tr.67]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được khóa mã cho Câu Hoan. Khoảng giữa thế kỷ IX trong luận án là đề nghị từ phong cách, không phải năm khởi dựng. Niên đại của các tác phẩm khác nhau trong danh mục cũ cũng cần kiểm riêng. [1, tr.67]"},{"title":"Hiện vật và nơi lưu giữ","text":"Phải lập danh mục ít nhất ba trạng thái: vật được nguồn thấy tại miếu, vật được ghi trong khảo tả cũ và vật đã có hồ sơ bảo tàng nếu xác minh được. Đầu tượng, Mukhalinga và linga không được hợp chỉ vì đều gắn hình người hoặc cơ quan sinh thực. [1, tr.66–67]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Không nên cạo lớp sơn hoặc ghép lại yoni chỉ nhằm làm vật giống một mô hình điển hình. Hồ sơ bảo tồn cần xác định vật liệu, lớp can thiệp và tình trạng nứt. Bản đồ chỉ bổ sung dẫn đường sau xác nhận vị trí miếu và phạm vi nền còn lại."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi ưu tiên là tên gọi chỉ một địa điểm hay có sự chép nhầm trong bảng, sau đó là quan hệ thật giữa các bộ phận đá. Đối sánh với Trà Lộc và Kim Đâu chỉ có ý nghĩa nếu phân biệt hình thái vật thờ với cách lắp đặt về sau."}],"thesis_locator":"66–67","reference_numbers":[1,2],"related_ids":["BDS-0033","BDS-0043"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0044","name":"Câu Hoan","identity_note":"Câu Hoan / Cu Hoan: biến thể tên cần kiểm trang sách gốc.","word_count":482,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Bộ linga và những cách đọc khác nhau","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,2],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0045":{"id":"BDS-0045","title":"Trung Sơn — Hồ sơ đang chờ giải quyết tên địa điểm","lead":"Trung Sơn cần một bài giới thiệu thận trọng vì tên trong dòng nguồn chưa nối chắc với tên trong các khảo tả. Giá trị trước mắt của hồ sơ là làm rõ bài toán nhận diện, tránh xây một di tích từ dữ liệu của nơi khác.","province_source":"Quảng Trị","address_source":"Hải Thành - Hải Lăng","source_page":"63","review_status":"editorial_draft_identity_unresolved","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0045 ghi Trung Sơn, Hải Thành, Hải Lăng, Quảng Trị. Trong phần luận án đã kiểm có Trung Đơn tại Hải Thành; bài Nguyễn Văn Mạnh năm 2015 lại liệt kê Trung Dân. Ba dạng này là các đầu mối đối chiếu, chưa được coi là một tên đã chuẩn hóa. [1, tr.76–77;2;12]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Chưa xác lập được lịch sử phát hiện riêng cho chính tên Trung Sơn. Nếu báo cáo Trung Đơn được chứng minh cùng địa điểm, nó mới có thể bổ sung lịch sử khảo sát của hồ sơ này. Hiện bài không chuyển các mốc phát hiện hoặc thay đổi hiện trường của Trung Đơn sang Trung Sơn."},{"title":"Kiến trúc và cảnh quan","text":"Chưa có mặt bằng hoặc vùng gò được khóa cho BDS-0045. Lùm Tháp trong khảo tả Trung Đơn chỉ là địa điểm cần so sánh. Dữ liệu bản đồ phải giữ vị trí chưa xác định hoặc ứng viên có nhãn, không lấy tâm xã Hải Thành để tạo cảm giác chính xác. [1, tr.76–77]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Chưa có hiện vật định danh chắc thuộc Trung Sơn trong lượt kiểm này. Không gán Śiva giáo, Phật giáo hoặc một thần chủ từ các mô tả của tên gần giống. Tên dân gian chỉ được bổ sung sau khi biết nó gắn với đúng gò nào."},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được nối chắc với tên Trung Sơn. Việc chưa tìm thấy trong phần nguồn được đọc không chứng minh địa điểm không có bia; đây là giới hạn tư liệu. Những mã bia của vùng Hải Lăng không được gắn tự động bằng địa giới."},{"title":"Hiện vật và nơi lưu giữ","text":"Chưa có nơi lưu giữ hiện vật được xác nhận cho chính dòng BDS này. Khi tìm trong catalogue cần giữ cả ba dạng tên và chụp lại nhãn xuất xứ. Một kết quả gần tên là ứng viên để kiểm, chưa là bằng chứng hoàn tất chuỗi xuất xứ."},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên hiện tại là bảo tồn tính minh bạch của hồ sơ: giữ nguyên dòng nguồn, ghi các ứng viên và lý do chưa đồng nhất. Chưa nên tạo chỉ đường, gợi ý tham quan hoặc mời khảo sát trên một thửa đất chưa được xác định."},{"title":"Những vấn đề đang nghiên cứu","text":"Các bước có thể giải quyết hồ sơ là xem lại trang sách tạo BDS-0045, đối chiếu chữ Trung Sơn–Trung Đơn–Trung Dân và bản đồ làng, rồi kiểm thực địa có sự hỗ trợ địa phương. Khi chưa qua các bước ấy, bài giới thiệu ngắn hơn các di tích khác là hệ quả đúng của mức chứng cứ, không phải lý do để lấp bằng một lịch sử suy đoán."}],"thesis_locator":"Chưa nối chắc; đối tượng so sánh tr.76–77","reference_numbers":[1,2,12],"related_ids":["BDS-0043","BDS-0046"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0045","name":"Trung Sơn","identity_note":"Trung Sơn / Trung Đơn / Trung Dân chưa đồng nhất.","word_count":480,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"},{"number":12,"title":"Nguyễn Văn Mạnh (14/05/2015). Văn hóa Champa ở Quảng Trị: tiềm năng và giải pháp phát triển du lịch. Tạp chí Cửa Việt.","url":"https://tapchicuaviet.vn/nguoi-dat-que-huong/van-hoa-champa-o-quang-tri-tiem-nang-va-giai-phap-phat-trien-du-lich--9787.html","scope":"Đọc danh sách địa điểm, trong đó có Nam Sơn và Phương Sơn; giữ dạng Trung Dân của bài để đối chiếu, không tự sửa thành Trung Sơn.","access":"cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Hồ sơ đang chờ giải quyết tên địa điểm","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,2,12],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0046":{"id":"BDS-0046","title":"Trường Sanh — Một gò tháp bị biến đổi và các tên Phật Lồi","lead":"Trường Sanh lưu lại trong chuỗi khảo tả cũ và những dấu vật liệu trên gò. Việc kiến trúc và đá thờ không còn được nhìn thấy đầy đủ khiến lịch sử nguồn trở thành phần cốt yếu của hồ sơ.","province_source":"Quảng Trị","address_source":"Hải Thành - Hải Lăng","source_page":"63","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0046 ghi Hải Thành, Hải Lăng; luận án ghi đội 3, Hải Trường, Hải Lăng. Cần đối chiếu địa giới theo thời gian và vị trí gò trước khi chuẩn hóa địa chỉ. Trường Sanh và Trường Sinh có thể là biến thể tên, nhưng trường tên nguồn vẫn phải được bảo toàn. [1, tr.82–83;2]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Parmentier được luận án dẫn mô tả một miếu Bà Lồi hoặc Phật Lồi, mảnh thân tượng sa thạch và phạm vi gạch khá rộng. Trong khảo sát sau, tác giả không tìm lại được đầy đủ các vật đá. Đây là khác biệt giữa các thời điểm quan sát, chưa tự xác định nguyên nhân mất dấu. [1, tr.82–83]"},{"title":"Kiến trúc và cảnh quan","text":"Gò đã được dùng làm nhà, vườn và nơi chôn cất theo mô tả nguồn. Gạch còn lại giúp nhận diện dấu xây dựng nhưng không cho một bình đồ. Phạm vi gạch trong báo cáo cũ là vùng phân bố vật liệu, chưa phải đường kính chính xác của ngôi đền. [1, tr.82–83]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tên Bà Lồi hoặc Phật Lồi cần giữ như một cách cộng đồng nhận diện vật và nơi thờ. Nó không đủ phân loại cơ sở gốc là Phật giáo. Khi chỉ còn mô tả mảnh thân tượng, việc nhận diện thần chủ phải để mở."},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được khóa cho Trường Sanh. Bài cũng chưa sử dụng một niên đại thế kỷ cho nền đền vì dữ liệu hiện có chưa đủ. Gạch dày hoặc phong cách một mảnh đá không nên biến thành một ngày dựng tháp."},{"title":"Hiện vật và nơi lưu giữ","text":"Cần tìm ảnh và hồ sơ của mảnh tượng từng được ghi, đồng thời kiểm các cấu kiện tái sử dụng tại làng. Một đầu mối ảnh trong bộ sưu tập số ECLEVI có thể giúp truy tư liệu, nhưng trang chỉ mục chưa thay thế việc kiểm đúng phiếu ảnh và xuất xứ. [1, tr.82–83;6]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn cần ưu tiên khu vực còn khả năng giữ nền dưới đất và hồ sơ hiện vật chưa tìm lại được. Điều tra điền dã nên ghi cả vị trí quan sát không thấy dấu, kèm phạm vi thực sự được khảo sát; không mở rộng thành kết luận toàn khu không còn gì."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi chính là gò trong các nguồn có cùng vị trí và còn lớp khảo cổ đến đâu. Sau khi khóa địa điểm, mới có thể đặt Trường Sanh trong quan hệ với các gò vùng Hải Lăng. Tên Phật Lồi giống nhau giữa nhiều làng là hiện tượng cần nghiên cứu, không phải khóa đồng nhất di tích."}],"thesis_locator":"82–83","reference_numbers":[1,2,6],"related_ids":["BDS-0044","BDS-0045"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0046","name":"Trường Sanh","identity_note":"Trường Sanh: Hải Thành khác Hải Trường; cần lịch sử địa giới.","word_count":474,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"},{"number":6,"title":"ECLEVI / PACHA, Collection Patrimoine Cham. Trang Thématiques, nền tảng địa tin học EHESS.","url":"https://psig.huma-num.fr/omeka-s/s/eclevi/page/thematiques","scope":"Đầu mối nhan đề và liên kết được ghi nhận ở lượt rà soát trước; lần kiểm lại 04/11/2026 hết thời gian tải. Chưa kiểm đủ phiếu từng ảnh, tác giả, ngày chụp, quyền ảnh và tọa độ. Không dùng như nguồn xác nhận hiện trạng.","access":"cong_khai_truy_cap_khong_on_dinh"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Một gò tháp bị biến đổi và các tên Phật Lồi","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,2,6],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0001":{"id":"BDS-0001","title":"Liễu Cốc — Hai tháp bên sông Bồ qua khai quật 2024–2025","lead":"Trên gò phù sa bên hữu ngạn sông Bồ, Liễu Cốc lưu giữ hai đền tháp gạch cùng dấu tích tường bao, tháp Cổng và đường đi. Hai đợt khai quật 2024–2025 đã làm rõ thêm kiến trúc và phát hiện đá trang trí đầu bò, đầu phù điêu Phật cùng những mảnh minh văn Sanskrit, mở ra cách đọc nhiều giai đoạn sử dụng di tích.","province_source":"Thừa Thiên Huế","address_source":"Làng Liễu Cốc Thượng, khu vực Bàu Tháp/Xuân Tháp, Hương Xuân, Hương Trà (địa chỉ trong báo cáo 2024); báo cáo 07/2025 ghi phường Kim Trà, thành phố Huế.","source_page":"60","review_status":"primary_excavation_reports_crosschecked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh, địa chỉ và hồ sơ pháp lý","text":"Tháp đôi Liễu Cốc thuộc làng Liễu Cốc Thượng, khu vực Bàu Tháp/Xuân Tháp. Báo cáo 2024 dùng địa chỉ phường Hương Xuân, thị xã Hương Trà, tỉnh Thừa Thiên Huế; bìa báo cáo tháng 07/2025 ghi phường Kim Trà, thành phố Huế. Theo báo cáo 2024, di tích được xếp hạng di tích kiến trúc – nghệ thuật quốc gia tại Quyết định 921/QĐ/BT ngày 20/7/1994; đây là thông tin dẫn từ báo cáo, chưa đối chiếu bản quyết định gốc. Tọa độ trên bản đồ được giữ theo bộ vị trí của dự án. [11, tr.1–2] [12, bìa; tr.2]"},{"title":"Lịch sử khảo sát và các pha xây dựng","text":"Đợt 2024 tập trung làm lộ nền móng tháp Bắc, một phần tháp Cổng, tường bao phía đông và đường đi. Đợt 2025 mở hai hố khai quật tổng cộng 60 m² cùng hai hố thám sát tổng cộng 6 m², làm rõ tiền sảnh tháp Bắc, một phần tháp Nam và tường bao phía bắc, nam. Báo cáo 2025 tổng kết hai đợt khoảng 150 m², hơn 6% diện tích quy hoạch 2.428 m²; số liệu diện tích giữa các phần báo cáo mang tính tổng kết, không dùng để cộng thành một con số đo chính xác hơn. Đoàn khai quật đề xuất tháp Bắc cuối thế kỷ IX, tháp Nam cuối IX–đầu X, có thể muộn hơn khoảng 10–20 năm. Khoảng cách này dựa trên kiến trúc, trang trí và tự dạng chữ, chưa phải niên đại tuyệt đối. Báo cáo 2024 từng tổng thuật các đề xuất khác từ cuối VIII–đầu IX đến XI–XII; cần giữ lịch sử nhận định thay vì coi một khung niên đại là đã khóa. [11, tr.5; 15–16] [12, tr.3; 12–13]"},{"title":"Kiến trúc, số đo và cảnh quan","text":"Di tích nằm trên gò phù sa thấp bên hữu ngạn sông Bồ; báo cáo 2024 ghi cách sông khoảng 820 m về phía nam. Hai tháp bố trí trên hai trục gần đông–tây, cửa chính phía đông. Tháp Bắc được đo năm 2024: thân 5,70 × 5,62 m, tường dày 1,60–1,65 m, lòng chính điện đông–tây 2,85 m và bắc–nam 2,65 m; hướng cửa đông lệch bắc 14°. Báo cáo 2025 đo tháp Nam: thân 6,15 × 6,08 m, tường dày 1,97 m, phần tường tây còn cao 4,92 m; cửa đông lệch bắc 16°. Báo cáo chưa mô tả đầy đủ vị trí của từng phép đo; cần đối chiếu bản vẽ trước khi kiểm tra chéo lòng tháp, tường và kích thước phủ bì. Tiền sảnh tháp Bắc được làm rõ năm 2025, dài 2,90 m, rộng 4,17 m; tiền sảnh Nam dài 3,34 m, rộng 4,44 m. Khuôn viên giữa hai tường bao bắc–nam rộng khoảng 24,7 m, phủ bì khoảng 28 m. Hai hố thám sát ngoài hai tháp chưa gặp dấu tích tháp thứ ba trong phạm vi đã mở. Tháp Hỏa, nhà bia, nhà dài và toàn bộ tường phía tây vẫn cần kiểm; báo cáo 2025 thận trọng hơn cách gọi một số kiến trúc trong báo cáo 2024. [11, tr.2; 7–10] [12, tr.5–9; 13]"},{"title":"Thần linh và các lớp thực hành tín ngưỡng","text":"Các đá nhấn góc hình đầu bò được đoàn khai quật nhận diện là Nandin; báo cáo 2025 còn nêu những mảnh đá có thể thuộc yoni và linga. Đây là đầu mối khảo sát tín ngưỡng Śiva, chưa đủ xác định chắc thần chủ của từng tháp. Đầu phù điêu Phật tìm năm 2024 là chứng cứ hiện vật Phật giáo tại địa điểm, nhưng niên đại được ghi khác nhau: báo cáo 2024 xếp XI–XII, báo cáo 2025 khi nhắc lại xếp X–XI. Hiện vật nằm trong lớp có tàn tích kiến trúc đổ, không được mô tả là tượng thờ nguyên vị; vì vậy chưa thể từ hiện vật này xác định công năng khởi dựng của hai tháp. Miếu Dương Phi/Bà Giàng trước tháp Nam thuộc lớp thờ Bà Chúa Tháp về sau; báo cáo ghi việc xây dựng/tái tạo vào đời Thành Thái và lễ ngày 23/4 âm lịch. Lớp tín ngưỡng này cần phân biệt với thời xây tháp Champa. [11, tr.2; 6; 12; 15] [12, tr.1; 10]"},{"title":"Văn khắc và giới hạn định niên","text":"Báo cáo 2024 ghi ba mảnh bia, gồm hai mảnh có chữ và một mảnh cạnh; phần hồi cố trong báo cáo 2025 ghi bốn mảnh của đợt 2024, gồm ba mảnh mặt và một mảnh diềm. Đợt 2025 riêng ghi thêm bảy mảnh đá có chữ Phạn (Sanskrit); dựa trên nguyên liệu đá, đoàn khảo cổ đề xuất có ít nhất hai bia, hoặc một bia và một cấu kiện đá có minh văn, niên đại tự dạng khoảng đầu thế kỷ X. Số mảnh không phải số bia; chưa cộng gộp hai đợt khi danh mục chỉnh lý chưa thống nhất. Hai báo cáo chưa cung cấp bản đọc, phiên âm, dịch văn bản hay mã C. xác lập cho các mảnh này. Vì vậy không gán vua, thần danh hoặc năm dựng tháp từ nội dung minh văn chưa đọc được. [11, tr.12] [12, tr.1; 10]"},{"title":"Hiện vật, vật liệu và nơi lưu giữ","text":"Đợt 2024 thống kê 4.807 tiêu bản, trong đó có 50 mảnh đá trang trí đầu bò và đầu phù điêu Phật còn cao 20 cm, rộng 15 cm, dày 10 cm. Đợt 2025 thống kê 9.380 tiêu bản và mảnh, có 64 mảnh trang trí đầu bò, bảy mảnh minh văn, cấu kiện chóp và năm mảnh thạch anh. Các mảnh nghi linga–yoni và cách giải thích thạch anh bị lấy từ hố thiêng đều còn là nhận định. Ba bình vôi năm 2024 được báo cáo đầu tiên gán Champa IX–XI, nhưng phần hồi cố năm 2025 chuyển thành gốm Phước Tích XVI–XVIII; dùng nhận định mới kèm lịch sử thay đổi, chưa coi là kết quả giám định cuối cùng. Báo cáo 2025 mô tả gạch dài 28–31 cm, rộng 11–20 cm, đa số dày 5,5–6,5 cm, lõi xám đen, mặt có vết chải; gạch lành bao ngoài và gạch vỡ trong lõi tường. Giải thích mạch xây bằng đất sét mịn pha loãng và nguồn gạch gần di tích là nhận định khảo cổ; hai báo cáo chưa có phân tích thành phần hay thực nghiệm để xác nhận chất kết dính hoặc quy trình nung. Chưa xác nhận nơi lưu giữ cuối cùng của từng hiện vật sau chỉnh lý. [11, tr.10–14] [12, tr.1; 9–11]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Theo báo cáo 2024, cuối năm 2023 địa phương đã hoàn thành đường bê tông từ Quốc lộ 1A vào di tích và bãi đỗ xe; đây là thông tin theo thời điểm báo cáo, chưa phải khảo sát điều kiện tham quan hiện nay. Báo cáo 2025 kiến nghị nghiên cứu mái che hai tháp, bảo tồn kết cấu gạch, cảnh quan và miếu Dương Phi, đồng thời mở rộng khai quật. Những kiến nghị này chưa được hiểu là hạng mục đã thi công. Phần kiến trúc còn đứng và nền móng vừa phát lộ cần được bảo vệ đồng thời; không suy từ tình trạng hố đào năm 2025 thành tình trạng bảo tồn hiện tại. [11, tr.2–3] [12, tr.12–13]"},{"title":"Đối chiếu nguồn và những vấn đề còn mở","text":"Ưu tiên tiếp theo là đối chiếu danh mục hiện vật giữa hai đợt, kiểm niên đại đầu Phật và bình vôi, đọc minh văn, làm rõ pha xây hai tháp và các kiến trúc phụ. Báo cáo 2025 vừa nhận xét cao độ hai nền gần nhau (tr.4), vừa đề xuất lệch thời gian 10–20 năm từ trang trí (tr.12); nên hiểu là gần nhau về giai đoạn, chưa đủ chứng minh cùng một lần xây. Không dùng mốc chính trị 1306 như niên đại chắc chắn của lớp đổ tháp khi chưa có phép định niên địa tầng độc lập. Nhận định “duy nhất trên thế giới” trong báo cáo chưa được dùng làm kết luận của bản đồ vì thiếu đối sánh toàn diện. Liên hệ với thành Phú Ốc hay mạng di tích sông Bồ là câu hỏi nghiên cứu cảnh quan, chưa phải quan hệ thiết chế đã xác lập. [11, tr.6; 13] [12, tr.4; 11–13]"}],"thesis_locator":"98–99","reference_numbers":[1,10,11,12],"related_ids":["BDS-0002","BDS-0050"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0001","name":"Liễu Cốc","identity_note":"Đã đọc trực tiếp hai báo cáo sơ bộ tháng 06/2024 và 07/2025. Số trang chú dẫn là trang in; trang PDF tương ứng = trang in + 1. Niên đại và chức năng kiến trúc còn có phần là nhận định sơ bộ của đoàn khảo cổ.","word_count":1398,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":10,"title":"Nguyễn Ngọc Chất – Nguyễn Ngọc Tân (09/07/2025). Bảo tàng Lịch sử Quốc gia báo cáo kết quả khai quật giai đoạn 2 tại di tích tháp đôi Liễu Cốc, thành phố Huế.","url":"https://baotanglichsuquocgia.vn/vi/Articles/3090/75595/bao-tang-lich-su-quoc-gia-bao-cao-ket-qua-khai-quat-giai-djoan-2-tai-di-tich-thap-djoi-lieu-coc-thanh-pho-hue.html","scope":"Đã mở lại thông báo chính thức: đăng 09/07/2025, hội nghị ngày 08/07/2025. Đây là thông báo tóm tắt cùng đợt nghiên cứu, không tính như một chứng cứ độc lập với hai báo cáo.","access":"cong_khai"},{"number":11,"title":"Sở Văn hóa và Thể thao tỉnh Thừa Thiên Huế – Bảo tàng Lịch sử Quốc gia (06/2024). Báo cáo sơ bộ kết quả thăm dò và khai quật khảo cổ tại di tích Tháp đôi Liễu Cốc.","url":"","scope":"Đọc trực tiếp toàn bộ bản PDF do Lê Trí Công cung cấp: 19 trang PDF, nội dung đánh số tr.1–17. Bìa không đánh số; trang PDF = trang in + 1. Đối chiếu ảnh trang hiện vật tr.12. Nguồn sơ cấp dạng báo cáo sơ bộ; không phải báo cáo chỉnh lý cuối cùng.","access":"ban_bao_cao_do_tac_gia_cung_cap"},{"number":12,"title":"Sở Văn hóa và Thể thao thành phố Huế – Bảo tàng Lịch sử Quốc gia (07/2025). Báo cáo sơ bộ kết quả thăm dò và khai quật giai đoạn 2 – năm 2025 tại di tích Tháp đôi Liễu Cốc, phường Kim Trà, thành phố Huế.","url":"","scope":"Đọc trực tiếp toàn bộ bản PDF do Lê Trí Công cung cấp: 14 trang PDF, nội dung đánh số tr.1–13; trang PDF = trang in + 1. Đã kiểm ảnh các trang tổng kết và hiện vật. Phần nhắc kết quả 2024 là hồi cố, không phải toàn bộ hiện vật mới của đợt 2025.","access":"ban_bao_cao_do_tac_gia_cung_cap"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Hai tháp bên sông Bồ qua khai quật 2024–2025","primary_crosscheck":[{"relation":"khac_biet","source":12,"locator":"tr.1, đối chiếu [11] tr.12","data":"Đầu phù điêu Phật: 2024 xếp XI–XII; hồi cố 2025 xếp X–XI. Ba bình vôi: 2024 gán Champa IX–XI; 2025 gán Phước Tích XVI–XVIII.","note":"Chưa có hồ sơ giám định cuối cùng; giữ cả hai cách ghi. Không đổi niên đại đầu Phật thành niên đại dựng tháp."},{"relation":"khac_biet","source":12,"locator":"tr.1; 10, đối chiếu [11] tr.12","data":"Số mảnh bia của đợt 2024 được ghi ba trong báo cáo 2024, bốn trong hồi cố 2025; đợt 2025 ghi riêng bảy mảnh.","note":"Chưa cộng thành tổng chung và chưa gán mã C.; số mảnh không đồng nghĩa số bia."},{"relation":"bo_sung","source":12,"locator":"tr.5–9; 12–13","data":"Làm rõ tiền sảnh Bắc, một phần tháp Nam và giới hạn hai tường bao. Đề xuất Bắc cuối IX; Nam cuối IX–đầu X.","note":"Tổng mặt bằng vẫn chưa đầy đủ; khoảng lệch 10–20 năm là suy luận của đoàn khai quật."},{"relation":"can_kiem","source":12,"locator":"tr.13, đối chiếu [11] tr.5; 13","data":"Báo cáo 2024 từng gọi dấu vết tháp Hỏa; tổng kết 2025 vẫn đặt câu hỏi có hay không nhà bia, tháp Hỏa và nhà dài.","note":"Hồ sơ bản đồ giữ các chức năng này ở mức giả thuyết cần khai quật thêm."},{"relation":"can_kiem","source":12,"locator":"tr.9","data":"Mục vật liệu kiến trúc ghi tổng 8.866 tiêu bản nhưng tiểu mục gạch 8.806 và ngói 30 cộng thành 8.836.","note":"Lệch 30 tiêu bản trong bản báo cáo; chưa tự sửa tổng hoặc phân bổ phần chênh. Các tổng hiện vật chỉ trích theo báo cáo."}],"inventory_links":[],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,10,11,12],"note":"Đã đọc trực tiếp hai báo cáo khai quật sơ bộ; đối chiếu thông báo công khai cùng đoàn nghiên cứu. Không tính các bản tóm tắt cùng nguồn là chứng cứ độc lập."},"excavation_phases":[{"date":"2024 · Báo cáo 06/2024","actor":"Bảo tàng Lịch sử Quốc gia phối hợp Sở Văn hóa và Thể thao tỉnh Thừa Thiên Huế.","area":"Báo cáo ghi hơn 80 m²; ba hố quanh tháp Bắc được nối và mở rộng thành hố 9,4 × 10,3 m, cùng năm hố thám sát. Không đồng nhất diện tích kế hoạch với diện tích hố mở rộng.","architecture":"Nền móng tháp Bắc; một phần tháp Cổng và tường bao phía đông; đường đi, nền sân.","finds":"4.807 tiêu bản theo thống kê báo cáo; đá đầu bò, đầu phù điêu Phật, mảnh bia, gốm và tiền đồng.","measurements":"Bắc: thân 5,70 × 5,62 m; lòng 2,85 × 2,65 m; hướng đông lệch bắc 14°. Móng xuất lộ 8,50 × 8,35 m, chưa trọn các phía.","locator":"[11, tr.1; 5; 7–12]"},{"date":"2025 · Báo cáo 07/2025","actor":"Bảo tàng Lịch sử Quốc gia phối hợp Sở Văn hóa và Thể thao thành phố Huế.","area":"60 m² khai quật và 6 m² thám sát; báo cáo tổng kết hai đợt khoảng 150 m² trên khu quy hoạch 2.428 m².","architecture":"Toàn bộ tiền sảnh Bắc; một phần nền móng Nam; tường bao phía bắc và nam.","finds":"9.380 tiêu bản và mảnh theo báo cáo; 64 mảnh trang trí đầu bò; bảy mảnh minh văn; cấu kiện chóp; gốm, thạch anh và mảnh kim loại.","measurements":"Nam: thân 6,15 × 6,08 m; tường 1,97 m; đế 6,56 × 6,98 m, cao 1,12 m; cửa đông lệch bắc 16°. Khoảng trong hai tường bao bắc–nam 24,7 m.","locator":"[12, tr.3; 5–10; 13]"}],"measurement_table":{"title":"Đối chiếu số đo hai tháp","caption":"Số đo theo báo cáo; chiều đầu là đông–tây, chiều sau là bắc–nam.","headers":["Hạng mục","Tháp Bắc","Tháp Nam"],"rows":[["Thân tháp","5,70 × 5,62 m (2024)","6,15 × 6,08 m (2025)"],["Đế tháp","6,56 × 6,38 m; cao 0,95 m (2024)","6,56 × 6,98 m; cao 1,12 m (2025)"],["Tường dày","1,60–1,65 m (2024)","1,97 m (2025)"],["Lòng chính điện","2,85 × 2,65 m (2024)","Chưa có số đo lòng trong phần khai quật 2025"],["Tiền sảnh","Dài 2,90 m; rộng 4,17 m (2025)","Dài 3,34 m; rộng 4,44 m (2025)"],["Hướng cửa chính","Đông lệch bắc 14° (2024)","Đông lệch bắc 16° (2025)"]],"locator":"[11, tr.7–8] [12, tr.5–7]"},"report_images":[{"file":"lieu-coc-cong-dscf9202.jpg","title":"Liễu Cốc — kiến trúc gạch còn lại","alt":"Các mảng tường và chân đế tháp Liễu Cốc, trên thân tháp có cây cỏ mọc.","caption":"Ảnh tư liệu về phần kiến trúc còn lại của di tích.","credit":"Ảnh: Lê Trí Công."},{"file":"lieu-coc-cong-dscf9203.jpg","title":"Liễu Cốc — chi tiết kiến trúc gạch","alt":"Cận cảnh các gờ giật cấp và ô hộc trên kiến trúc gạch Liễu Cốc.","caption":"Chi tiết gờ, trụ và ô hộc trang trí trên khối xây gạch.","credit":"Ảnh: Lê Trí Công."},{"file":"lieu-coc-2024-plan.jpg","title":"Tổng mặt bằng các hố khai quật và thám sát năm 2024","alt":"Ảnh chụp từ trên cao di tích Liễu Cốc, có các khung đỏ H1–H3 và TS1–TS5.","caption":"Ảnh chụp từ trên cao thể hiện vị trí các hố H1–H3 quanh tháp Bắc và các hố thám sát TS1–TS5; phản ánh phạm vi nghiên cứu năm 2024.","credit":"Nguồn: báo cáo sơ bộ khai quật Liễu Cốc 06/2024, phần II, tr.5; bản ảnh do Lê Trí Công cung cấp."},{"file":"lieu-coc-2024-finds.jpg","title":"Hiện vật khảo cổ trong báo cáo năm 2024","alt":"Bảng ảnh đá trang trí đầu bò, đầu phù điêu Phật, mảnh bia và ba bình vôi Liễu Cốc.","caption":"Giữ nguyên bảng ảnh và chú thích của nguồn. Báo cáo 2024 ghi đầu Phật XI–XII và bình vôi Champa IX–XI; phần hồi cố năm 2025 ghi đầu Phật X–XI, bình vôi Phước Tích XVI–XVIII. Xem phần đối chiếu nguồn bên dưới.","credit":"Nguồn ảnh: báo cáo sơ bộ khai quật Liễu Cốc 06/2024, tr.11–12; bảng ảnh do Lê Trí Công cung cấp."}]},"BDS-0002":{"id":"BDS-0002","title":"Mỹ Khánh hoặc Phú Diên — Kiến trúc dưới cát và câu hỏi về niên đại","lead":"Mỹ Khánh, thường được biết đến với tên tháp Phú Diên, là trường hợp quan trọng để nghiên cứu một kiến trúc được vùi trong cát ven biển. Điều kiện phát hiện đặc biệt cần đi cùng cách đọc thận trọng về tuổi tháp, chức năng các nền phụ và cảnh quan cổ.","province_source":"Thừa Thiên Huế","address_source":"","source_page":"60","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt tháp tại thôn Mỹ Khánh, xã Phú Diên, Phú Vang. Hai tên nên cùng xuất hiện trong chỉ mục nhưng không làm mất tên gốc của dòng nguồn. Bài chưa xác nhận địa chỉ sau sắp xếp hành chính hoặc điều kiện mở cửa hiện nay. [1, tr.88]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn ghi phát hiện ngày 18/4/2001 và các cuộc khai quật năm 2001, 2005. Đây là các mốc nghiên cứu hiện đại, cần tách khỏi thời gian xây và vùi lấp. Hiện vật tại từng cuộc đào phải được nhận diện theo hố và lớp để tránh coi toàn bộ là vật sử dụng đồng thời. [1, tr.88–90]"},{"title":"Kiến trúc và cảnh quan","text":"Tháp chính có nền chữ nhật, cửa về phía đông theo khảo tả, cùng nền phụ và dấu một kiến trúc hoặc bàn thờ phía trước. Chức năng nền phụ từng được đề nghị khác nhau, như maṇḍapa hoặc kośagṛha. Vị trí tương đối một mình chưa phân xử được; cần xem lối đi, cấu trúc nền và quan hệ địa tầng. [1, tr.88–90]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Yoni trong lòng tháp hỗ trợ nhận diện lớp thờ Śiva; linga được nguồn xem là đã mất. Giả thuyết mái từng bằng vật liệu nhẹ dựa vào tình trạng gạch đổ cần được trình bày như suy luận, không như hình dáng mái đã biết. Thiếu vật liệu có thể có nhiều nguyên nhân. [1, tr.89–90]"},{"title":"Văn khắc liên quan","text":"Luận án dẫn kết quả C14 là 750 ± 40. Chưa có mã phòng thí nghiệm, ngữ cảnh mẫu và đường hiệu chỉnh được kiểm trong bài này, nên không dùng con số đó như năm xây chính xác. Chữ Hán được ghi trên một số viên gạch là đối tượng văn tự riêng, chưa được xem như bia lập tháp. [1, tr.90]"},{"title":"Hiện vật và nơi lưu giữ","text":"Các vật được nguồn nhắc gồm yoni, đèn đồng, gốm và gạch có dấu khắc. Chưa có danh mục bàn giao để xác nhận nơi giữ hiện hành từng món. Cần tách vật còn ở công trình, vật trong kho khai quật và vật đã trưng bày; không ghi một địa chỉ chung cho tất cả. [1, tr.89–90]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn đòi hỏi theo dõi môi trường quanh kiến trúc và phần nền đã đào, đặc biệt quan hệ nước, cát và lớp gạch. Bài không kết luận giải pháp che phủ hiện tại đạt hay không khi chưa có quan trắc. Thông tin tiếp cận phải theo đơn vị quản lý, không suy từ ảnh cũ."},{"title":"Những vấn đề đang nghiên cứu","text":"Lớp cát vùi không tự cho phép vẽ đường bờ biển cổ hoặc gọi đây là đền của một cảng. Cần kết hợp địa mạo, niên đại trầm tích và các pha kiến trúc. Mỹ Khánh nên được dùng để kiểm những mô hình ấy bằng dữ liệu độc lập, thay vì làm minh họa cho một lịch sử biển đã được giả định trước."}],"thesis_locator":"88–90","reference_numbers":[1],"related_ids":["BDS-0001","BDS-0055"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0002","name":"Mỹ Khánh","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":527,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Kiến trúc dưới cát và câu hỏi về niên đại","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0047":{"id":"BDS-0047","title":"Đức Nhuận — Nền gạch và hành trình của tượng Nandin","lead":"Đức Nhuận có giá trị từ hai chuỗi chứng cứ khác nhau: dấu nền tại địa điểm và lịch sử chuyển giữ tượng Nandin. Chỉ khi nối hai chuỗi bằng hồ sơ xuất xứ mới có thể đọc chúng như một cơ sở thờ.","province_source":"Thừa Thiên Huế","address_source":"Quảng Phú - Quảng Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án ghi Đức Nhuận, Quảng Phú, Quảng Điền, Thừa Thiên Huế. Địa chỉ nguồn cần được giữ nguyên, còn tên đơn vị hiện nay để một trường cập nhật riêng. Chưa có văn bản được kiểm để xác nhận tình trạng pháp lý và ranh giới khoanh vùng. [1, tr.95–96]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn dẫn phát hiện Nandin năm 1969 và những lần thay đổi nơi giữ sau đó, đồng thời mô tả khảo sát hoặc thám sát nền. Cần tách lời kể về lần tìm tượng với quan sát trực tiếp tường gạch; hai chứng cứ chưa chắc có cùng độ chính xác vị trí. [1, tr.95–96]"},{"title":"Kiến trúc và cảnh quan","text":"Dấu tường trên gò đang được sử dụng và phần nền được tác giả mô tả hỗ trợ xác nhận có kiến trúc gạch. Một đoạn tường chưa đủ phục nguyên số tháp hoặc chiều dài cả khu. So sánh kỹ thuật móng với nơi khác cần dựa vào vật liệu và cấu trúc, không chỉ kích thước còn lại. [1, tr.95–96]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Nandin cho thấy một lớp hình tượng liên quan thờ Śiva. Tượng không tự xác định chủ thể lập đền hoặc vị trí chính điện. Nếu vị trí tìm được ghi theo hồi ức, cần kiểm độ tin cậy trước khi đặt Nandin vào một sơ đồ nghi lễ giả định. [1, tr.95–96]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được nối chắc với Đức Nhuận. Niên đại thế kỷ IX mà luận án đề nghị cho Nandin là niên đại phong cách của tác phẩm, chưa phải mốc xây tường gạch. Hai nhóm chứng cứ cần một phép nối độc lập. [1, tr.96]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi chuỗi chuyển tượng qua Sịa, cơ quan cấp huyện và thư viện Nguyễn Chí Thanh tại thời điểm nguồn. Chuỗi ấy cần đối chiếu chứng từ bàn giao; chưa dùng như xác nhận nơi trưng bày năm 2026. Những mốc chuyển giữ có thể tạo thành hồ sơ quan hệ, với mức chắc riêng cho từng mắt xích. [1, tr.95–96]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là khóa vị trí nền còn lại và số kiểm kê Nandin, ghi ảnh những phần đang lộ trên đất sử dụng. Bản đồ công khai không cần đưa thông tin cá nhân của người sử dụng thửa đất; chỉ cần phạm vi khảo cổ và điều kiện khảo sát được xác nhận."},{"title":"Những vấn đề đang nghiên cứu","text":"Đức Nhuận có thể so sánh Nandin với Kim Đâu và Quảng Điền ở Quảng Trị, nhưng chưa được suy cùng xưởng. Các biến đổi nơi giữ cho phép nghiên cứu lịch sử sưu tập và thiết chế bảo tồn; chúng không trực tiếp phản ánh mạng bảo trợ thời Champa."}],"thesis_locator":"95–96","reference_numbers":[1],"related_ids":["BDS-0033","BDS-0036","BDS-0050"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0047","name":"Đức Nhuận","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":483,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Nền gạch và hành trình của tượng Nandin","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0048":{"id":"BDS-0048","title":"Cổ Tháp — Một tên gò và khoảng trống sau biến đổi sử dụng đất","lead":"Cổ Tháp là hồ sơ ít hiện vật được kiểm trực tiếp, vì vậy bài tập trung vào địa điểm, lịch sử biến đổi và những giới hạn của việc định niên đại. Tên gọi giàu gợi ý không thay thế được lớp khảo cổ.","province_source":"Thừa Thiên Huế","address_source":"Quảng Vinh - Quảng Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt Cổ Tháp ở Phổ Lai, Quảng Vinh, Quảng Điền. Cần phân biệt với Cồn Tháp tại Phú Ốc và với mọi tên gọi cổ tháp dùng như danh từ chung. Hồ sơ chưa xác nhận địa chỉ hành chính mới hoặc ranh giới pháp lý. [1, tr.99–100]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn ghi thông tin khu đất từng sử dụng cho công trình thời chiến và về sau làm vườn ươm. Một phần dựa trên hồi ức địa phương, cần kiểm ảnh hoặc bản đồ cùng thời. Lịch sử sử dụng đất giúp lý giải khả năng mất dấu nhưng không tự định tuổi nền tháp. [1, tr.99–100]"},{"title":"Kiến trúc và cảnh quan","text":"Gạch và mô tả đá chạm là căn cứ nhận diện dấu tích kiến trúc. Chưa có bình đồ khai quật hoặc đoạn nền được dùng để phục nguyên toàn công trình trong bài này. Diện tích sử dụng về sau cũng không thể làm diện tích của đền gốc."},{"title":"Thần linh và thực hành tín ngưỡng","text":"Chưa có ảnh hoặc tác phẩm đủ thuộc tính được kiểm để khóa thần chủ. Không gán Śiva giáo hay Phật giáo từ việc vật từng được đưa vào một ngôi chùa. Nơi giữ về sau và bối cảnh tôn giáo nguyên thủy là hai loại quan hệ khác nhau. [1, tr.100]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc gắn chắc với Cổ Tháp. Đề nghị niên đại sau thế kỷ X dựa trên việc dùng đá cần được kiểm lại bằng tiêu chí cụ thể; riêng vật liệu đá không đủ làm mốc thời gian. Bài để niên đại kiến trúc chưa xác định. [1, tr.100]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án thuật lại đường chuyển của một phù điêu qua chùa Thanh Cần nhưng chưa khóa được nơi giữ sau đó. Những lời kể chuyển nhượng không được trình bày ở đây như một sự kiện mua bán đã có chứng từ. Cần tìm ảnh, nhãn cũ và người từng khảo sát để nhận diện đúng vật. [1, tr.100]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn trước mắt gồm lưu hồ sơ gò, thu thập ảnh trước biến đổi và xác định phần đất còn khả năng có nền. Không nên tìm kiếm bằng đào tự phát vì có thể phá chính ngữ cảnh ít ỏi còn lại. Chưa có cơ sở cung cấp dẫn đường chính xác cho công chúng."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi có thể giải quyết trước là vật đá được kể có thực sự thuộc Cổ Tháp và có ảnh nào nhận dạng được. Chỉ sau đó mới đối sánh phong cách hoặc nối với các trung tâm vùng Ô Lâu. Thiếu dữ liệu cần hiện thành trạng thái hồ sơ, thay vì được phủ bằng một đoạn lịch sử chung của Champa."}],"thesis_locator":"99–100","reference_numbers":[1],"related_ids":["BDS-0049","BDS-0050"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0048","name":"Cổ Tháp","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":487,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Một tên gò và khoảng trống sau biến đổi sử dụng đất","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0049":{"id":"BDS-0049","title":"Cồn Tháp — Gò gạch gần thành Phú Ốc","lead":"Cồn Tháp được nhận diện trong tương quan với thành Phú Ốc và các miếu làng. Khoảng cách gần là đầu mối khảo sát, nhưng chưa đủ xác lập một quan hệ chức năng hoặc sự đồng thời giữa đền và thành.","province_source":"Thừa Thiên Huế","address_source":"Phú Ốc - Hương Trà","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Nguyễn Văn Quảng đặt di tích tại Phú Ốc, Tứ Hạ, Hương Trà. Cần giữ tên Cồn Tháp riêng với Cổ Tháp ở Phổ Lai. Cả địa chỉ hiện hành và tình trạng khoanh vùng cần một lần kiểm độc lập trước khi xuất bản bản đồ dẫn đường. [1, tr.99]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Luận án ghi gò và vật liệu ở thời điểm khảo sát, cùng lịch sử sử dụng làm đất trồng và chôn cất. Chưa có một cuộc khai quật được dùng làm căn cứ xác định pha xây trong bài này. Việc tên tháp còn trong ký ức không đủ cho biết công trình mất vào thế kỷ nào. [1, tr.99]"},{"title":"Kiến trúc và cảnh quan","text":"Gò được mô tả cao khoảng 0,7 m và nằm gần phía bắc thành Phú Ốc. Đó là kích thước phần nổi lúc quan sát, chưa là chiều cao nguyên thủy hoặc diện tích đền. Miếu Ông và miếu Bà gần gò cần điểm riêng; không mặc nhiên dựng chúng lên mặt bằng điện thờ Champa. [1, tr.99]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Chưa có tác phẩm đủ thuộc tính để xác định thần chủ Cồn Tháp. Các tên miếu Ông, Bà phản ánh lớp tín ngưỡng làng, cần nghiên cứu bằng lịch sử miếu và hiện vật cụ thể. Không nên phân công hai miếu thành một cặp nam–nữ thần Champa chỉ từ tên gọi."},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được nối chắc với Cồn Tháp. Bài chưa gán thời gian xây bằng niên đại giả định của thành Phú Ốc; quan hệ gần nhau cần được kiểm bằng địa tầng, vật liệu và định niên đại độc lập."},{"title":"Hiện vật và nơi lưu giữ","text":"Nhóm vật liệu chủ yếu được ghi là gạch trên gò. Chưa có sưu tập bảo tàng được khóa bằng số kiểm kê trong lượt rà này. Không chuyển các tác phẩm của Cổ Tháp hoặc vùng Tứ Hạ nói chung sang hồ sơ Cồn Tháp để làm đầy danh mục. [1, tr.99]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là lập mặt bằng hiện trạng sử dụng đất, giữ vị trí dấu gạch và những khu vực chưa bị xáo trộn. Hồ sơ bảo tồn của gò cần liên kết nhưng không nhập với hồ sơ thành, vì ranh giới và nguy cơ của hai loại dấu tích có thể khác nhau."},{"title":"Những vấn đề đang nghiên cứu","text":"Cồn Tháp thích hợp để kiểm một giả thuyết đền–thành, với điều kiện không coi giả thuyết là dữ kiện đầu vào. Cần hỏi hai nơi có cùng pha không, có lối đi hoặc ranh tổ chức chung không và chứng cứ nào có thể bác bỏ sự liên hệ."}],"thesis_locator":"99","reference_numbers":[1],"related_ids":["BDS-0048","BDS-0001"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0049","name":"Cồn Tháp","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":467,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Gò gạch gần thành Phú Ốc","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0050":{"id":"BDS-0050","title":"Vân Trạch Hòa — Ba nền tháp và một chương trình điêu khắc","lead":"Vân Trạch Hòa có dữ liệu kiến trúc và điêu khắc đủ phong phú để nghiên cứu tổ chức một quần thể. Nhưng ngay lịch sử khai quật trong tài liệu tổng hợp còn một điểm không thống nhất, cần được đưa ra minh bạch.","province_source":"Thừa Thiên Huế","address_source":"Phong Thu - Phong Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án ghi xóm Cồn Chùa, Vân Trạch Hòa, Phong Thu, Phong Điền, trong cảnh quan phía bắc hệ Ô Lâu. Địa chỉ ấy cần đối chiếu với địa giới hiện hành. Các tác phẩm mang nhãn Vân Trạch Hòa phải giữ tên xuất xứ và nối riêng với vị trí khai quật. [1, tr.84,90]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Bảng tổng hợp của luận án ghi khai quật năm 1997, trong khi phần khảo tả ghi năm 1999. Bài giữ cả hai mốc và yêu cầu truy báo cáo gốc, chưa tự chọn một năm. Đây là bất nhất của nguồn, không phải bằng chứng về hai cuộc khai quật khác nhau. [1, tr.84,90]"},{"title":"Kiến trúc và cảnh quan","text":"Khảo tả trình bày ba nền, trong đó nền trung tâm và nền phía bắc có kích thước khác nhau, cửa về đông. Những cửa giả và trang trí tường được nguồn mô tả giúp đọc cấu trúc, nhưng chưa đủ định chức năng mọi kiến trúc. Các hố lõi và vật đặt trong nền phải đọc theo hồ sơ khai quật, không chỉ qua mặt bằng tóm tắt. [1, tr.90–91]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Bệ thờ được đọc với hệ thần hộ phương và phù điêu Liṅgodbhavamūrti mở ra chương trình hình tượng liên quan Śiva. Tên từng nhân vật cần kiểm từ ảnh nhiều mặt, thuộc tính và bản mô tả gốc. Không dùng sự có mặt của nhiều thần để mặc nhiên khẳng định một giáo phái hỗn hợp. [1, tr.90–91]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được khóa mã trong phần nguồn đã kiểm. Khoảng cuối IX–đầu X được luận án đề nghị từ phong cách hiện vật. Nó chưa tự cho thứ tự xây ba nền; cần dữ liệu quan hệ tường, nền và lớp phá hủy để phân pha. [1, tr.91]"},{"title":"Hiện vật và nơi lưu giữ","text":"Các hiện vật được nguồn ghi tại Bảo tàng Lịch sử ở Huế cần đối chiếu số kiểm kê, ảnh từng mặt và xuất xứ theo nền. ECLEVI có đầu mối ảnh Vân Trạch Hòa, nhưng phải kiểm phiếu từng ảnh trước khi dùng làm bằng chứng về mặt chưa được quan sát. [1, tr.91;6]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn nên gắn quản lý các nền với một hồ sơ cấu kiện thống nhất. Nếu tác phẩm đã rời nơi đào, bản sao trưng bày cần ghi rõ là bản sao và không làm mất sơ đồ vị trí phát hiện. Chưa có khảo sát hiện trạng năm 2026 trong bài."},{"title":"Những vấn đề đang nghiên cứu","text":"Câu hỏi ưu tiên là ba kiến trúc được xây đồng thời hay phát triển qua nhiều pha, và chương trình điêu khắc có thuộc một đợt không. Khung Đan–Mạng có thể dùng để đặt giả thuyết về năng lực tổ chức xây, nhưng quy mô nền không tự chứng minh danh tính người bảo trợ hoặc địa vị một kinh đô."}],"thesis_locator":"90–91; bảng tr.84","reference_numbers":[1,6],"related_ids":["BDS-0001","BDS-0047","BDS-0051"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0050","name":"Vân Trạch Hòa","identity_note":"Vân Trạch Hòa: bảng luận án ghi 1997, phần khảo tả ghi 1999; cần báo cáo đào gốc.","word_count":507,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":6,"title":"ECLEVI / PACHA, Collection Patrimoine Cham. Trang Thématiques, nền tảng địa tin học EHESS.","url":"https://psig.huma-num.fr/omeka-s/s/eclevi/page/thematiques","scope":"Đầu mối nhan đề và liên kết được ghi nhận ở lượt rà soát trước; lần kiểm lại 04/11/2026 hết thời gian tải. Chưa kiểm đủ phiếu từng ảnh, tác giả, ngày chụp, quyền ảnh và tọa độ. Không dùng như nguồn xác nhận hiện trạng.","access":"cong_khai_truy_cap_khong_on_dinh"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Ba nền tháp và một chương trình điêu khắc","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,6],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0051":{"id":"BDS-0051","title":"Ưu Điềm — Đá thờ Champa trong một không gian chùa","lead":"Ưu Điềm cho thấy giá trị của việc đọc một di tích qua những vật đá được giữ và tái sử dụng trong chùa. Không gian đang sử dụng có lịch sử riêng, cần phân biệt với chức năng của cơ sở Champa trước đó.","province_source":"Thừa Thiên Huế","address_source":"Phú Trạch - Phong Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0051 ghi Phú Trạch, Phong Điền; luận án dùng Phong Hòa, Phong Điền. Trước khi coi đó là lỗi, cần đối chiếu đơn vị tổng, xã và từng thời kỳ. Trường địa chỉ nguồn được giữ nguyên, chưa đổi sang địa chỉ mới bằng suy đoán. [1, tr.93–94;2]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Các khảo tả Cadière và Parmentier được luận án tập hợp mô tả vật liệu kiến trúc và đá thờ. Nguồn sau có thể dẫn lại nguồn trước, nên không đếm thành nhiều lần xác nhận độc lập nếu chưa thấy quan sát mới. Việc chùa nằm trên hoặc kế tục một nền cũ cần kiểm bằng cấu trúc dưới đất. [1, tr.93–94]"},{"title":"Kiến trúc và cảnh quan","text":"Các nhóm trụ cửa, đá bệ và dấu kiến trúc gợi một cơ sở xây dựng đáng kể, nhưng bố trí hiện vật trong chùa không phải bình đồ đền gốc. Cần lập sơ đồ vị trí đang giữ và bản đồ nơi phát hiện, chấp nhận có vật chưa biết xuất xứ chi tiết. [1, tr.93–94]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Linga–yoni, phù điêu Śiva–Pārvatī và các mảnh tượng hỗ trợ nhận diện lớp Hindu. Những tên Bà hoặc Phật Lồi cần ghi theo cách thờ tại chỗ, không dùng để phủ định định danh hình tượng; ngược lại, định danh hình tượng cũng không xóa lịch sử tiếp nhận của cộng đồng. [1, tr.94]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được khóa cho Ưu Điềm. Khoảng cuối IX–đầu X trong luận án là đề nghị từ phong cách tác phẩm, không phải năm dựng ngôi chùa hiện nay hoặc toàn thể nền đền. Cần tách rõ các đối tượng được định niên đại. [1, tr.94]"},{"title":"Hiện vật và nơi lưu giữ","text":"Danh mục cần có từng trụ, từng bệ và từng tượng thay vì một mục chung đá Chăm. Lớp sơn, mặt gãy và dấu tái lắp là thông tin về lịch sử vật thể, không nên loại bỏ khi chụp tư liệu. Bài chưa xác nhận đủ số lượng và nơi giữ hiện hành qua kiểm kê trực tiếp. [1, tr.93–94]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên bảo tồn là thỏa thuận với cơ sở đang sử dụng để ghi nguyên trạng, theo dõi tác động của sửa chùa và tránh dùng đá cổ làm kết cấu mới. Chưa nên đề nghị di chuyển hàng loạt trước khi hiểu ngữ cảnh và tình trạng vật."},{"title":"Những vấn đề đang nghiên cứu","text":"Ưu Điềm phù hợp nghiên cứu sự biến đổi chức năng và tên gọi của cùng vật thờ. Cần hỏi những lần tập hợp, sơn và di chuyển diễn ra khi nào; không mặc nhiên coi sự hiện diện trong chùa là bằng chứng tiếp nối nguyên vẹn một nghi lễ Champa."}],"thesis_locator":"93–94","reference_numbers":[1,2],"related_ids":["BDS-0050","BDS-0052","BDS-0054"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0051","name":"Ưu Điềm","identity_note":"Ưu Điềm: cần phân biệt địa chỉ tổng Phú Trạch với xã Phong Hòa theo thời gian.","word_count":480,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Đá thờ Champa trong một không gian chùa","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_multiple","reference_numbers":[1,2],"note":"Nhiều nguồn thứ cấp hoặc dữ liệu dự án; chưa có đối chiếu nguồn gốc."},"excavation_phases":[]},"BDS-0052":{"id":"BDS-0052","title":"Xuân Hòa — Ba dạng tên và một liên kết địa điểm còn mở","lead":"Xuân Hòa là một hồ sơ phải đặt việc phân biệt địa danh lên trước phục nguyên lịch sử. Bài Cadière năm 1917 giúp nhận diện một nhóm điêu khắc gần Huế, nhưng chưa tự chứng minh đó là địa điểm của dòng BDS tại Phong Điền.","province_source":"Thừa Thiên Huế","address_source":"Phú Trạch - Phong Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"BDS-0052 ghi Xuân Hòa, Phú Trạch, Phong Điền. Trong khi đó, luận án thảo luận Xuân Hóa hoặc Xuân Huế gần chùa Tường Vân, Thủy Xuân. Hồ sơ giữ hai đối tượng cần đối chiếu, chưa chuyển điểm BDS về Thủy Xuân. Cũng cần phân biệt với Xuân Hòa ở Quảng Trị. [1, tr.96–97;2]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Bài Les sculptures chames de Xuan-Hoa của Cadière ghi một nhóm đá tại khu gần chùa Tường Vân. Chú thích giải thích các dạng Xuân Hòa, Xuân Huế, Thiên Hòa theo thông tin tác giả nhận được. Đây là chứng cứ tên gọi đầu thế kỷ XX, chưa đủ giải quyết địa chỉ Phú Trạch của BDS. [5, tr.285–289]"},{"title":"Kiến trúc và cảnh quan","text":"Cadière mô tả năm đá gồm một bộ phận đỉnh cột, một con sư tử, hai đầu makara và một linga đặt gần miếu. Tập hợp đá trong một nơi thờ về sau không tự xác định vị trí tháp gốc. Hướng dẫn đường trong bài là tư liệu lịch sử, không nên dùng làm lộ trình hiện nay. [5, tr.285–287]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Tác giả ghi thờ Bà Dàng và đề nghị cách giải thích danh hiệu cùng một thực hành chữa bệnh mắt. Bài giữ đó là quan sát và giả thuyết dân tộc học của Cadière, không xác nhận hiệu quả chữa bệnh hoặc suy ra trực tiếp nghi lễ Champa thời trung đại. [5, tr.287–289]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc Champa được khóa cho đúng BDS-0052. Danh hiệu trên bài vị mà Cadière chép thuộc lớp văn bản về sau; không được nhập thành một bia Sanskrit hoặc dùng làm niên đại xây tháp. Quan hệ giữa tên thần và vật thờ vẫn cần kiểm riêng. [5]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án ghi nhóm tác phẩm trong sưu tập Bảo tàng Cổ vật Cung đình Huế. Muốn nối với năm đá năm 1917 phải so ảnh, kích thước và lịch sử bàn giao. Một tên giống trên nhãn chưa đủ xác nhận từng tác phẩm; bài chưa gán số kiểm kê chưa được mở. [1, tr.96–97]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên là giải quyết chuỗi địa danh và chuyển vị trước khi dẫn đường. Nơi đặt miếu lúc Cadière đến, vị trí miếu trước di dời và nơi giữ bảo tàng phải được biểu diễn thành các điểm có vai trò khác nhau, không chọn một điểm đại diện cho cả lịch sử."},{"title":"Những vấn đề đang nghiên cứu","text":"Xuân Hòa cho phép nghiên cứu cách tên kiêng húy, tên làng và tên thần làm phức tạp việc truy xuất hiện vật. Cần kiểm chính trang sách tạo BDS-0052 và bản đồ Phú Trạch trước khi đồng nhất. BAVH là một nguồn gốc để truy, không phải lý do bỏ qua khác biệt địa chỉ."}],"thesis_locator":"96–97; bảng tr.86","reference_numbers":[1,2,5],"related_ids":["BDS-0051","BDS-0053"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0052","name":"Xuân Hòa","identity_note":"Dòng nguồn Phú Trạch, Phong Điền chưa đồng nhất với nhóm Xuân Hòa/Xuân Huế ở Thủy Xuân.","word_count":493,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"},{"number":5,"title":"Léopold Cadière (1917). Les sculptures chames de Xuan-Hoa. BAVH, số 4; các đoạn dùng ở tr.285–289.","url":"","scope":"Đọc trực tiếp văn bản trích xuất từ số 17_4BAVH.PDF: tiêu đề, tên tác giả, tên địa điểm, năm đá và thảo luận miếu Bà Dàng. Chưa hiệu khảo chữ Hán từ ảnh. Phân biệt trang bài gốc với số trang được dẫn trong luận án.","access":"ban_doc_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Ba dạng tên và một liên kết địa điểm còn mở","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,2,5],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [5]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0053":{"id":"BDS-0053","title":"Giám Biều hoặc Nham Biều — Một pho tượng và lịch sử tranh luận","lead":"Giám Biều được biết nhiều qua nhóm vật đá và những cách đọc khác nhau về một pho tượng mất đầu. Bài cần tách mô tả vật, diễn giải hình tượng và lịch sử chuyển giữ, đồng thời giữ việc nối tên với Nham Biều ở trạng thái cần kiểm.","province_source":"Thừa Thiên Huế","address_source":"Long Hồ - Hương Trà","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Dòng BDS-0053 dùng Giám Biều; luận án thảo luận Nham Biều thuộc Hương Hồ, Hương Trà. Đây là liên kết định danh cần đối chiếu, không phải lý do tự sửa toàn bộ tên nguồn. Cần phân biệt rõ với Nhan Biều ở Quảng Trị và văn khắc C.149. [1, tr.97–98;2]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"BAVH năm 1915 thảo luận lại tượng và các báo cáo đã có, trong đó dẫn Parmentier năm 1909 và thông tin khảo sát trước đó. Vì vậy không nên dựng trình tự Parmentier khảo tả sau bài 1915. Những thông tin về lũ phá dấu tích cần ghi theo hồi ức nguồn, chưa là mốc địa chất được kiểm. [1, tr.97–98;4, tr.471–474] Parmentier năm 1919 nói rõ ông xem lại nhóm vật đã được BAVH công bố; trang mở đầu liệt kê ba vật xuất xứ Giám Biều. Số vật trong lần công bố ấy không nhất thiết bằng số ghi trong danh mục về sau. [3, tr.7]"},{"title":"Kiến trúc và cảnh quan","text":"Luận án cho biết không còn nhận diện đầy đủ dấu kiến trúc tại nơi khảo sát. Ngưỡng, bệ và mảnh trang trí là chứng cứ của một công trình, nhưng chưa tạo ra bình đồ. Nơi tượng từng được đặt cũng cần phân biệt với nơi tượng được tìm hoặc lưu giữ về sau. [1, tr.97–98]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Giới tính và chức năng tượng từng có các cách đọc khác nhau. Những diễn giải từ dáng bụng hoặc trạng thái cơ thể trong bài cũ không được coi là chẩn đoán y khoa hay định danh thần đã chắc. Với đầu và thuộc tính bị mất, bài giữ mức nhận diện nam thần hoặc nhân vật theo nguồn, chờ kiểm vật. [4, tr.471–474]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được khóa cho Giám Biều/Nham Biều. Khoảng X–XI trong luận án là nhận định phong cách một nhóm vật, không phải ngày mất đền. Một niên đại tác phẩm không giải quyết được thời điểm di chuyển hoặc tái sử dụng. [1, tr.98]"},{"title":"Hiện vật và nơi lưu giữ","text":"Luận án dẫn nhóm vật tại Bảo tàng Cổ vật Cung đình Huế gồm tượng và các cấu kiện. Cần nối từng món với ảnh cũ, catalogue và lịch sử tiếp nhận; không coi bốn món cùng nhãn là một bộ đồng thời khi chưa kiểm nguồn phát hiện. [1, tr.97–98]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Ưu tiên bảo tồn hồ sơ là số hóa các lần chụp và mô tả tượng, giữ rõ ai quan sát trực tiếp, ai dẫn lại. Ở địa điểm, cần ghi phạm vi khảo sát và khả năng nền đã bị cuốn hoặc biến đổi, không biến việc không thấy dấu thành chứng cứ không từng có kiến trúc."},{"title":"Những vấn đề đang nghiên cứu","text":"Giám Biều là trường hợp tốt để nghiên cứu lịch sử tri thức: cùng một vật có thể được đọc khác qua các thời kỳ. Lớp quan hệ nên hiển thị sự dẫn lại giữa báo cáo, thay vì làm người đọc tưởng nhiều tác giả là nhiều xác nhận độc lập. Việc phân tích Đan–Mạng cần bắt đầu từ quan hệ chứng cứ đã khóa ấy."}],"thesis_locator":"97–98","reference_numbers":[1,2,3,4],"related_ids":["BDS-0038","BDS-0052"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0053","name":"Giám Biều","identity_note":"Giám Biều / Nham Biều: liên kết tên cần đối chiếu bản đồ và catalogue.","word_count":557,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"},{"number":2,"title":"Danh mục dòng nguồn BDS của Bản Đồ Di Sản Champa, bản 41; chép từ Lê Đình Phụng – Phạm Văn Triệu, tr.60–71 theo siêu dữ liệu dự án.","url":"","scope":"Đọc dữ liệu atlas_public_source.json và giữ nguyên mã, tên, địa chỉ nguồn, số trang sách. Thông tin đủ về nhan đề và ấn bản sách chưa được xác minh trong lượt biên soạn này; không trình bày bảng nội bộ như một ấn bản sách độc lập đã kiểm.","access":"du_lieu_du_an"},{"number":3,"title":"Henri Parmentier (1919). Sculptures cames conservées à Hué. BEFEO 19, tr.7–12. DOI: 10.3406/befeo.1919.5654.","url":"https://www.persee.fr/doc/befeo_0336-1519_1919_num_19_1_5654","scope":"Đọc trực tiếp trang 7: nguồn nói rõ việc xem lại các vật đã được BAVH bàn luận; chưa kiểm toàn bộ tr.8–12.","access":"cong_khai"},{"number":4,"title":"Bulletin des Amis du Vieux Hué (1915), số 4. Mục La statue et les autres sculptures chames de Giam-Bieu, tr.471–474.","url":"","scope":"Đọc văn bản trích xuất từ số 15_4BAVH.PDF trong kho dự án. Chưa khóa tác giả mục; nguồn dẫn lại Odend’hal, Parmentier và ý kiến Gaide. Không tính các dẫn lại như các xác nhận độc lập.","access":"ban_doc_du_an"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Một pho tượng và lịch sử tranh luận","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"secondary_with_primary_crosscheck","reference_numbers":[1,2,3,4],"note":"Có nguồn gốc hoặc ấn bản văn khắc bổ sung hay xác nhận một số mệnh đề: [3], [4]. Mức này mô tả loại nguồn có mặt, không có nghĩa toàn bài đã được xác minh độc lập."},"excavation_phases":[]},"BDS-0054":{"id":"BDS-0054","title":"Phước Tích — Yoni, đá cửa và cảnh quan bến làng","lead":"Phước Tích cần một hồ sơ khảo cổ riêng trong không gian làng di sản. Những đá thờ và cấu kiện cho phép nhận diện một lớp vật chất Champa, nhưng không nên dùng giá trị của cả làng để thay cho chứng cứ của một nền đền cụ thể.","province_source":"Thừa Thiên Huế","address_source":"Phong Hòa - Phong Điền","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt nhóm dấu tích tại Phước Tích, Phong Hòa, Phong Điền, trong khu gần miếu Quảng Tế. Địa chỉ và vị trí từng vật cần được kiểm lại. Tình trạng pháp lý của làng không tự xác nhận xếp hạng hoặc ranh bảo vệ riêng cho phế tích. [1, tr.94]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn ghi những vật đá ở khu miếu và nhóm khác tại bến Cây Bàng. Đây là ít nhất hai nơi quan sát cần hồ sơ riêng. Chưa có cơ sở xác định tất cả vật đến từ cùng nền, cùng lần phát hiện hoặc cùng pha sử dụng. [1, tr.94]"},{"title":"Kiến trúc và cảnh quan","text":"Yoni, các bộ phận khung cửa và đá ở bến cho thấy dấu kiến trúc tôn giáo, nhưng vị trí hiện tại chưa đủ dựng bình đồ tháp. Một cấu kiện còn dang dở có thể giúp nghiên cứu chế tác, song cần xác minh tình trạng bề mặt trước khi gọi là phế phẩm xưởng. [1, tr.94]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Yoni hỗ trợ nhận diện lớp thờ Śiva. Các đá tròn đặt thêm bên trên không tự là linga nguyên thủy; giả thuyết thay thế vật mất cần kiểm lịch sử lắp đặt. Tên miếu và các thực hành hiện nay thuộc một lớp tư liệu khác, cần được mô tả theo chính ngữ cảnh của chúng. [1, tr.94]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc riêng được khóa cho nhóm dấu tích Phước Tích trong lượt đọc này. Bài không gán niên đại từ tuổi làng hoặc tuổi miếu. Chưa biết năm không đồng nghĩa không có giá trị; nó xác định phần việc nghiên cứu còn thiếu."},{"title":"Hiện vật và nơi lưu giữ","text":"Mỗi đá ở miếu và bến cần mã riêng, ảnh đủ mặt và lịch sử chuyển vị. Bài chưa có kiểm kê bảo tàng để xác nhận vật nào đã rời làng. Không chuyển tác phẩm từ Ưu Điềm sang Phước Tích chỉ vì cùng vùng Phong Hòa trong địa chỉ nguồn. [1, tr.94]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn cần đi cùng người quản lý miếu và không gian bến. Các can thiệp chỉnh trang làng nên ghi nhận đá cổ trước khi di chuyển, kể cả vật chưa được định danh. Không làm mới bề mặt hoặc tạo một bộ linga–yoni hoàn chỉnh từ các đá không có xuất xứ chắc."},{"title":"Những vấn đề đang nghiên cứu","text":"Cần kiểm quan hệ giữa gò đền, miếu và bến bằng địa tầng cùng hồ sơ chuyển vị. Việc vật được thấy gần nước chưa chứng minh một bến Champa hoặc tuyến vận chuyển đá. Phước Tích có thể góp phần nghiên cứu sự tái sử dụng di sản trong làng, nếu từng giai đoạn được tách rõ."}],"thesis_locator":"94","reference_numbers":[1],"related_ids":["BDS-0043","BDS-0051","BDS-0050"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0054","name":"Phước Tích","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":484,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Yoni, đá cửa và cảnh quan bến làng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0055":{"id":"BDS-0055","title":"Linh Thái — Dấu Champa trên núi và các lớp kiến trúc về sau","lead":"Linh Thái đòi hỏi phân lớp đặc biệt cẩn thận: dấu gạch và đá Champa nằm trong một cảnh quan đã có nhiều đợt xây dựng. Không thể xem mọi kiến trúc trên núi đều thuộc cùng một thời kỳ.","province_source":"Thừa Thiên Huế","address_source":"Vinh Hiền - Phú Lộc","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án đặt di tích ở núi Quy Sơn, khu Vĩnh Hiền, Phú Lộc, gần cửa Tư Hiền. Linh Thái là tên cần nối với vị trí khảo sát cụ thể trên núi. Địa chỉ hành chính và điều kiện đường lên hiện nay chưa được xác nhận trong bài. [1, tr.91–92]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Các quan sát và thám sát được luận án mô tả phân biệt những lớp vật liệu khác nhau. Một số kiến trúc gạch từng bị nhận là Champa được tác giả đặt lại vào giai đoạn Nguyễn. Bảng và phần mô tả cần đối chiếu báo cáo gốc trước khi khóa mốc năm thám sát. [1, tr.84,91–92]"},{"title":"Kiến trúc và cảnh quan","text":"Nguồn chia các vị trí nghiên cứu trên núi thành những khu cao độ khác nhau. Các tên H1, H2 là ký hiệu trong khảo sát, chưa là tên chính thức phổ quát. Dấu tái sử dụng gạch và đá làm việc phục nguyên nền đền Champa khó hơn; phải đọc mạch xây và lớp nền, không chỉ vật liệu. [1, tr.91–92]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Nhóm tượng và cấu kiện mở ra câu hỏi về chức năng tôn giáo, nhưng từng định danh cần kiểm theo ảnh và thuộc tính. Địa thế nhìn ra vùng cửa biển chưa chứng minh đền có chức năng chỉ dẫn hàng hải hoặc kiểm soát tàu thuyền. Đó là các giả thuyết cần loại chứng cứ khác."},{"title":"Văn khắc liên quan","text":"Luận án nhắc chữ trên cấu kiện và một trao đổi học thuật về định niên đại. Trao đổi riêng không thay một ấn bản văn khắc công khai; bài chưa gán mã C. hoặc vương hiệu khi chưa kiểm bản đọc. Cách gọi hệ chữ trong tài liệu cũ cũng cần phân biệt với định danh chữ cổ theo nghiên cứu hiện nay. [1, tr.92]"},{"title":"Hiện vật và nơi lưu giữ","text":"Nguồn ghi hiện vật phân tán tại các cơ sở ở Huế và đơn vị nghiên cứu. Cần khóa số kiểm kê từng món và khu phát hiện, tránh tổng số quan sát trở thành số vật hiện đang trưng bày. Các đề nghị niên đại khoảng XII–XIII phải gắn đúng vật, không áp cho mọi lớp trên núi. [1, tr.91–92]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Bảo tồn nên có bản đồ nhiều lớp: nền có thể thuộc Champa, công trình Nguyễn và những vị trí tái sử dụng đá. Một phương án dọn nền chỉ giữ thứ bị coi là cổ nhất có thể phá mất lịch sử biến đổi. Chưa có đánh giá an toàn tiếp cận hoặc tình trạng nền năm 2026."},{"title":"Những vấn đề đang nghiên cứu","text":"Linh Thái phù hợp kiểm quan hệ núi–cửa biển và sự tái chiếm dụng không gian thiêng, nhưng cần niên đại độc lập cho từng lớp. Trong khung Đan–Mạng, điều đáng hỏi là ai tái sử dụng vật và tái định nghĩa địa điểm, với chứng cứ nào; không mặc định địa thế tạo ra một quyền lực cảng biển."}],"thesis_locator":"91–92","reference_numbers":[1],"related_ids":["BDS-0002","BDS-0056"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0055","name":"Linh Thái","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":516,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Dấu Champa trên núi và các lớp kiến trúc về sau","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]},"BDS-0056":{"id":"BDS-0056","title":"Lương Hậu — Phù điêu Śiva múa trong không gian miếu làng","lead":"Lương Hậu kết hợp dấu kiến trúc, vật thờ và các tên thần được cộng đồng sử dụng về sau. Bài cần cho thấy giá trị của từng lớp, đồng thời không biến mọi dấu cổ gần nhau thành một quần thể đã được xác định.","province_source":"Thừa Thiên Huế","address_source":"Thủy Lương - Hương Thủy","source_page":"64","review_status":"editorial_draft_source_checked_with_limits","coordinate_status":"unchanged_not_field_verified","sections":[{"title":"Định danh địa chỉ và hồ sơ pháp lý","text":"Luận án ghi Lương Hậu, Thủy Lương, Hương Thủy. Tên thôn hoặc khu và địa chỉ hành chính hiện nay cần kiểm riêng. Phạm vi khoảng một hecta được nguồn mô tả là vùng dấu tích, chưa phải diện tích một ngôi đền nguyên vẹn. [1, tr.93]"},{"title":"Lịch sử phát hiện và các giai đoạn","text":"Nguồn ghi gạch, đoạn tường và những lời kể về nền dưới đất, cùng hiện vật giữ trong miếu. Lời kể có giá trị định hướng thám sát nhưng chưa thay một mặt cắt khảo cổ. Cần xác định phần nào do tác giả thấy trực tiếp và phần nào qua người cung cấp tin. [1, tr.93]"},{"title":"Kiến trúc và cảnh quan","text":"Đá và gạch đã được sử dụng lại khiến việc đọc bình đồ cần thận trọng. Một giếng đá ở vùng lân cận được gợi liên quan Champa chưa tự thuộc cùng cơ sở; cần định niên đại và kiểm cấu trúc. Khoảng cách gần không phải bằng chứng về hệ thống nước của đền. [1, tr.93]"},{"title":"Thần linh và thực hành tín ngưỡng","text":"Phù điêu Śiva múa được giữ trong không gian có tên Bà Giàng, Bô Y Na hoặc Bà Chuẩn Đề theo nguồn. Đây là dữ liệu về các cách gọi và sử dụng, không làm hình tượng tự đổi thành cùng một thần danh. Cần phân biệt nhận diện nghệ thuật với danh xưng trong thực hành thờ tự. [1, tr.93]"},{"title":"Văn khắc liên quan","text":"Chưa có văn khắc được nối chắc với Lương Hậu. Khoảng đầu thế kỷ X được luận án đề nghị cho phù điêu là niên đại phong cách; chưa định tuổi toàn bộ gạch, giếng hoặc miếu. Muốn phục nguyên các pha phải có dữ liệu độc lập cho từng nhóm. [1, tr.93]"},{"title":"Hiện vật và nơi lưu giữ","text":"Yoni dùng lại làm chỗ đặt tượng và phù điêu cần hồ sơ vật thể riêng. Tư thế lắp đặt lúc khảo sát chưa phải bố trí điện thờ Champa. Bài chưa xác nhận hiện trạng hay số lượng năm 2026 bằng một cuộc kiểm kê mới. [1, tr.93]"},{"title":"Bảo tồn và tiếp cận di tích","text":"Cần ghi nguyên trạng trước sửa miếu, kể cả lớp sơn, vật kê và dấu tái lắp. Việc khảo sát giếng hoặc tường dưới đất cần quy trình chuyên môn, không đào dò từ lời kể. Chỉ nên đưa dẫn đường sau khi cơ sở thờ và lối tiếp cận được xác nhận."},{"title":"Những vấn đề đang nghiên cứu","text":"Lương Hậu có thể góp phần nghiên cứu sự chuyển nghĩa của tác phẩm khi vào đời sống làng. Những quan hệ ấy phải có thời điểm và chủ thể nếu biết; không nên diễn đạt như một sự tiếp nối tôn giáo không đổi. So sánh với Ưu Điềm hoặc Phước Tích cần chú ý cả điểm giống lẫn khác trong cách tái sử dụng."}],"thesis_locator":"93","reference_numbers":[1],"related_ids":["BDS-0051","BDS-0054","BDS-0055"],"atlas_url":"https://ban-do-di-san-champa.arch-letricong.chatgpt.site/#BDS-0056","name":"Lương Hậu","identity_note":"Chưa xác nhận địa chỉ hiện hành, kiểm kê bảo tàng và hiện trạng năm 2026.","word_count":489,"references":[{"number":1,"title":"Nguyễn Văn Quảng (2018). Các di tích đền - tháp, thành - lũy Champa ở Quảng Bình, Quảng Trị, Thừa Thiên Huế. Luận án tiến sĩ Lịch sử, chuyên ngành Khảo cổ học, Trường ĐHKHXH&NV, ĐHQGHN.","url":"https://www.ussh.vnu.edu.vn/vi/dao-tao/luan-an/ttla-cac-di-tich-den-thap-thanh-luy-champa-o-quang-binh-quang-tri-thua-thien-hue-17434.html","scope":"Bản toàn văn trong kho dự án: đối chiếu bìa, mục lục, bảng 2.1–2.3; đọc các khảo tả liên quan trong chương 2, tr.47–100. Một số trang được đọc qua OCR từ ảnh, chưa tuyên bố hiệu khảo toàn văn. Số trang chú dẫn là trang in; trong bản PDF 266 trang được dùng, trang PDF = trang in + 4. URL là thông tin luận án, không phải toàn văn.","access":"du_lieu_du_an_va_thong_tin_thu_muc_cong_khai"}],"related_relation_type":"editorial_cross_reference_not_proven_historical_link","subtitle":"Phù điêu Śiva múa trong không gian miếu làng","primary_crosscheck":[],"inventory_links":[],"source_basis":{"level":"single_secondary_source","reference_numbers":[1],"note":"Bài dựa vào một nguồn thứ cấp (luận án 2018); các nguồn gốc được luận án dẫn chưa đọc trực tiếp."},"excavation_phases":[]}}};
